INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0777f88b-b3c4-4efb-98cc-52711af60d10', '感遇十二首 九', '感遇十二首 九', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["抱影吟中夜，誰聞此歎息。","美人適異方，庭樹含幽色。","白雲愁不見，滄海飛無翼。","鳳皇一朝來，竹花斯可食。"]', '["抱影吟中夜，誰闻此歎息。","美人適異方，庭樹含幽色。","白云愁不见，滄海飞無翼。","鳳皇一朝来，竹花斯可食。"]', '诗', 'shi', '', NULL, '感遇十二首 九 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('468d30a8-978e-49a0-aa3f-6390b0440b1f', '感遇十二首 十', '感遇十二首 十', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["漢上有游女，求思安可得。","袖中一札書，欲寄雙飛翼。","冥冥愁不見，耿耿徒緘憶。","紫蘭秀空蹊，皓露奪幽色。","馨香歲欲晚，感歎情何極。","白雲在南山，日暮長太息。"]', '["漢上有游女，求思安可得。","袖中一札书，欲寄雙飞翼。","冥冥愁不见，耿耿徒緘憶。","紫蘭秀空蹊，皓露奪幽色。","馨香歲欲晚，感歎情何極。","白云在南山，日暮长太息。"]', '诗', 'shi', '', NULL, '感遇十二首 十 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbf565de-5d46-42a6-92ea-8593a6bc2229', '感遇十二首 十一', '感遇十二首 十一', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["我有異鄉憶，宛在雲溶溶。","憑此目不覯，要之心所鍾。","但欲附高鳥，安敢攀飛龍。","至精無感遇，悲惋填心胸。","歸來扣寂寞，人願天豈從。"]', '["我有異乡憶，宛在云溶溶。","憑此目不覯，要之心所鍾。","但欲附高鸟，安敢攀飞龙。","至精無感遇，悲惋填心胸。","归来扣寂寞，人願天豈從。"]', '诗', 'shi', '', NULL, '感遇十二首 十一 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9445cb2e-feca-4e06-9523-e98f6e9d22f3', '感遇十二首 十二', '感遇十二首 十二', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["閉門跡羣化，憑林結所思。","嘯歎此寒木，疇昔乃芳蕤。","朝陽鳳安在，日暮蟬獨悲。","浩思極中夜，深嗟欲待誰。","所懷誠已矣，既往不可追。","鼎食非吾事，雲仙嘗我期。","胡越方杳杳，車馬何遲遲。","天壤一何異，幽嘿臥簾帷。"]', '["閉门跡羣化，憑林結所思。","嘯歎此寒木，疇昔乃芳蕤。","朝陽鳳安在，日暮蟬独悲。","浩思極中夜，深嗟欲待誰。","所懷誠已矣，既往不可追。","鼎食非吾事，云仙嘗我期。","胡越方杳杳，车马何遲遲。","天壤一何異，幽嘿臥簾帷。"]', '诗', 'shi', '', NULL, '感遇十二首 十二 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('015fb1b1-38b5-4343-85fd-8c05dce895cb', '江上遇疾風', '江上遇疾风', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["疾風江上起，鼓怒揚煙埃。","白晝晦如夕，洪濤聲若雷。","投林鳥鎩羽，入浦魚曝鰓。","瓦飛屋且發，帆快檣已摧。","不知天地氣，何爲此喧豗。"]', '["疾风江上起，鼓怒揚煙埃。","白晝晦如夕，洪濤声若雷。","投林鸟鎩羽，入浦鱼曝鰓。","瓦飞屋且發，帆快檣已摧。","不知天地氣，何爲此喧豗。"]', '诗', 'shi', '', NULL, '江上遇疾風 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15007e5d-15e8-4ebb-9dc3-e35af867b9a3', '自商行謁復州盧使君虔', '自商行謁复州盧使君虔', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["一身遶千山，遠作行路人。","未遂東吳歸，暫出西京塵。","仲宣荆州客，今余竟陵賓。","往蹟雖不同，託意皆有因。","商嶺莓苔滑，石坂上下頻。","江漢沙泥潔，永日光景新。","獨淚起殘夜，孤吟望初晨。","驅馳竟何事，章句依深仁。"]', '["一身遶千山，远作行路人。","未遂东吳归，暫出西京塵。","仲宣荆州客，今余竟陵賓。","往蹟雖不同，託意皆有因。","商嶺莓苔滑，石坂上下頻。","江漢沙泥潔，永日光景新。","独泪起殘夜，孤吟望初晨。","驱驰竟何事，章句依深仁。"]', '诗', 'shi', '', NULL, '自商行謁復州盧使君虔 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9ac40a0-4639-4fcb-9520-7aecd5d4c9e6', '夢澤中行', '梦澤中行', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["楚山爭蔽虧，日月無全輝。","楚路饒迴惑，旅人有迷歸。","騏驥思北首，鷓鴣願南飛。","我懷京洛遊，未厭風塵衣。"]', '["楚山爭蔽虧，日月無全輝。","楚路饒迴惑，旅人有迷归。","騏驥思北首，鷓鴣願南飞。","我懷京洛游，未厭风塵衣。"]', '诗', 'shi', '', NULL, '夢澤中行 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c956cd69-5f68-45a2-bf67-ac8ff591f77c', '京山行', '京山行', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["衆䖟聚病馬，流血不得行。","後路起夜色，前山聞虎聲。","此時遊子心，百尺風中旌。"]', '["衆䖟聚病马，流血不得行。","後路起夜色，前山闻虎声。","此时游子心，百尺风中旌。"]', '诗', 'shi', '', NULL, '京山行 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb5825af-7fba-4c01-bf48-c3bb17c9617f', '旅次湘沅有懷靈均', '旅次湘沅有懷靈均', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["分拙多感激，久遊遵長途。","經過湘水源，懷古方踟躕。","舊稱楚靈均，此處殞忠軀。","側聆故老言，遂得旌賢愚。","名參君子場，行爲小人儒。","騷文衒貞亮，體物情崎嶇。","三黜有慍色，即非賢哲模。","五十爵高秩，謬膺從大夫。","胸襟積憂愁，容鬢復彫枯。","死爲不弔鬼，生作猜謗徒。","吟澤潔其身，忠節寧見輸。","懷沙滅其性，孝行焉能俱。","且聞善稱君，一何善自殊。","且聞過稱己，一何過不渝。","悠哉風土人，角黍投川隅。","相傳歷千祀，哀悼延八區。","如今聖明朝，養育無羈孤。","君臣逸雍熙，德化盈紛敷。","巾車徇前侶，白日猶昆吾。","寄君臣子心，戒此真良圖。"]', '["分拙多感激，久游遵长途。","經過湘水源，懷古方踟躕。","旧稱楚靈均，此处殞忠軀。","側聆故老言，遂得旌賢愚。","名參君子場，行爲小人儒。","騷文衒貞亮，體物情崎嶇。","三黜有慍色，即非賢哲模。","五十爵高秩，謬膺從大夫。","胸襟積憂愁，容鬢复彫枯。","死爲不弔鬼，生作猜謗徒。","吟澤潔其身，忠節寧见輸。","懷沙滅其性，孝行焉能俱。","且闻善稱君，一何善自殊。","且闻過稱己，一何過不渝。","悠哉风土人，角黍投川隅。","相傳歷千祀，哀悼延八區。","如今聖明朝，養育無羈孤。","君臣逸雍熙，德化盈紛敷。","巾车徇前侶，白日猶昆吾。","寄君臣子心，戒此真良圖。"]', '诗', 'shi', '', NULL, '旅次湘沅有懷靈均 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d5b5fec-ba90-4b43-b1d4-7b0103cdfecd', '過彭澤', '過彭澤', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["揚帆過彭澤，舟人訝歎息。","不見種柳人，霜風空寂歷。"]', '["揚帆過彭澤，舟人訝歎息。","不见種柳人，霜风空寂歷。"]', '诗', 'shi', '', NULL, '過彭澤 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81558696-7b82-4a2d-a6f6-40b6abeb8b83', '過分水嶺', '過分水嶺', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["山壯馬力短，馬行石齒中。","十步九舉轡，迴環失西東。","溪水變爲雨，懸崖陰濛濛。","客衣飄颻秋，葛花零落風。","白日捨我沒，征途忽然窮。"]', '["山壯马力短，马行石齒中。","十步九舉轡，迴环失西东。","溪水变爲雨，懸崖陰濛濛。","客衣飄颻秋，葛花零落风。","白日捨我沒，征途忽然窮。"]', '诗', 'shi', '', NULL, '過分水嶺 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c1944d5-903c-487e-86bd-c253d36f874b', '分水嶺別夜示從弟寂', '分水嶺別夜示從弟寂', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["南中少平地，山水重疊生。","別泉萬餘曲，迷舟獨難行。","四際亂峰合，一眺千慮幷。","潺湲冬夏冷，光彩晝夜明。","賞心難久勝，離腸忽自驚。","古木搖霽色，高風動秋聲。","飲爾一樽酒，慰我百憂輕。","嘉期何處定，此晨堪寄情。"]', '["南中少平地，山水重叠生。","別泉万餘曲，迷舟独难行。","四際亂峰合，一眺千慮幷。","潺湲冬夏冷，光彩晝夜明。","賞心难久勝，離腸忽自驚。","古木搖霽色，高风动秋声。","饮爾一樽酒，慰我百憂轻。","嘉期何处定，此晨堪寄情。"]', '诗', 'shi', '', NULL, '分水嶺別夜示從弟寂 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12bda257-d0ec-425b-ae82-044bc5bd5252', '連州吟 一', '連州吟 一', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["春風朝夕起，吹綠日日深。","試爲連州吟，淚下不可禁。","連山何連連，連天碧岑岑。","哀猿哭花死，子規裂客心。","蘭芷結新佩，瀟湘遺舊音。","怨聲能翦弦，坐撫零落琴。"]', '["春风朝夕起，吹綠日日深。","試爲連州吟，泪下不可禁。","連山何連連，連天碧岑岑。","哀猿哭花死，子規裂客心。","蘭芷結新佩，瀟湘遺旧音。","怨声能翦弦，坐撫零落琴。"]', '诗', 'shi', '', NULL, '連州吟 一 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36b6f467-dc98-4ac0-9b1b-316b4a65db43', '連州吟 二', '連州吟 二', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["羽翼不自有，相追力難任。","唯憑方寸靈，獨夜萬里尋。","方尋魂飄颻，南夢山嶇嶔。","髣髴驚魍魎，悉窣聞楓林。","正直被放者，鬼魅無所侵。","賢人多安排，俗士多虛欽。","孤懷吐明月，衆毀鑠黃金。","願君保玄曜，壯志無自沉。"]', '["羽翼不自有，相追力难任。","唯憑方寸靈，独夜万里尋。","方尋魂飄颻，南梦山嶇嶔。","髣髴驚魍魎，悉窣闻楓林。","正直被放者，鬼魅無所侵。","賢人多安排，俗士多虛欽。","孤懷吐明月，衆毀鑠黄金。","願君保玄曜，壯志無自沉。"]', '诗', 'shi', '', NULL, '連州吟 二 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6c96e59-7b85-441f-9dd6-eccdf167757c', '連州吟 三', '連州吟 三', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["朝亦連州吟，暮亦連州吟。","連州果有信，一紙萬里心。","開緘白雲斷，明月墮衣襟。","南風嘶舜琯，苦竹動猿音。","萬里愁一色，瀟湘雨淫淫。","兩劒忽相觸，雙蛟恣浮沈。","鬬水正迴斡，倒流安可禁。","空愁江海信，驚浪隔相尋。"]', '["朝亦連州吟，暮亦連州吟。","連州果有信，一紙万里心。","开緘白云斷，明月墮衣襟。","南风嘶舜琯，苦竹动猿音。","万里愁一色，瀟湘雨淫淫。","兩劒忽相觸，雙蛟恣浮沈。","鬬水正迴斡，倒流安可禁。","空愁江海信，驚浪隔相尋。"]', '诗', 'shi', '', NULL, '連州吟 三 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38745ddb-3c6b-429d-b0d4-d89824c3d6a4', '旅行', '旅行', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["楚水結冰薄，楚雲爲雨微。","野梅參差發，旅榜逍遙歸。"]', '["楚水結冰薄，楚云爲雨微。","野梅參差發，旅榜逍遙归。"]', '诗', 'shi', '', NULL, '旅行 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18be44ca-4432-4648-9db6-c3b9bc5a8e3a', '上河陽李大夫', '上河陽李大夫', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["上將秉神略，至兵無猛威。","三軍當嚴冬，一撫勝重衣。","霜劒奪衆景，夜星失長輝。","蒼鷹獨立時，惡鳥不敢飛。","武牢鎖天關，河橋紐地機。","大將奚以安，守此稱者稀。","貧士少顏色，貴門多輕肥。","試登山嶽高，方見草木微。","山嶽恩既廣，草木心皆歸。"]', '["上將秉神略，至兵無猛威。","三軍當嚴冬，一撫勝重衣。","霜劒奪衆景，夜星失长輝。","蒼鷹独立时，惡鸟不敢飞。","武牢鎖天关，河橋紐地機。","大將奚以安，守此稱者稀。","貧士少顏色，貴门多轻肥。","試登山嶽高，方见草木微。","山嶽恩既廣，草木心皆归。"]', '诗', 'shi', '', NULL, '上河陽李大夫 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f954ce2-044e-45a3-9c6c-2f90a64718c8', '投贈張端公', '投贈張端公', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["君子量不極，胸吞百川流。","嫉邪霜氣直，問俗春辭柔。","日戶晝輝靜，月杯夜景幽。","詠驚芙蓉發，笑激風飆秋。","鸞步獨無侶，鶴音仍寡儔。","幸霑分寸顧，散此千萬憂。"]', '["君子量不極，胸吞百川流。","嫉邪霜氣直，问俗春辞柔。","日戶晝輝静，月杯夜景幽。","詠驚芙蓉發，笑激风飆秋。","鸾步独無侶，鹤音仍寡儔。","幸霑分寸顧，散此千万憂。"]', '诗', 'shi', '', NULL, '投贈張端公 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5175448-bb74-43b5-9610-475dd2f92b7f', '贈蘇州韋郎中使君', '贈蘇州韋郎中使君', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["謝客吟一聲，霜落羣聽清。","文含元氣柔，鼓動萬物輕。","嘉木依性植，曲枝亦不生。","塵埃徐庾詞，金玉曹劉名。","章句作雅正，江山益鮮明。","萍蘋一浪草，菰蒲片池榮。","曾是康樂詠，如今搴其英。","顧惟菲薄質，亦願將此幷。"]', '["謝客吟一声，霜落羣听清。","文含元氣柔，鼓动万物轻。","嘉木依性植，曲枝亦不生。","塵埃徐庾词，金玉曹劉名。","章句作雅正，江山益鲜明。","萍蘋一浪草，菰蒲片池榮。","曾是康乐詠，如今搴其英。","顧惟菲薄質，亦願將此幷。"]', '诗', 'shi', '', NULL, '贈蘇州韋郎中使君 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd7e9429-04bb-4f9e-98f5-ba6ff5c4380c', '上張徐州', '上張徐州', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["爲水不入海，安得浮天波。","爲木不在山，安得橫日柯。","再來君子傍，始覺精義多。","大德唯一施，衆情自偏頗。","至樂無宮徵，至聲遺謳謌。","願鼓空桑弦，永使萬物和。","顧己誠拙訥，干名已蹉跎。","獻詞惟在口，所欲無餘佗。","乍作支泉石，乍作翳松蘿。","一不改方圓，破質爲琢磨。","賤子本如此，大賢心若何。","豈是無異途，異途難經過。"]', '["爲水不入海，安得浮天波。","爲木不在山，安得橫日柯。","再来君子傍，始覺精義多。","大德唯一施，衆情自偏頗。","至乐無宮徵，至声遺謳謌。","願鼓空桑弦，永使万物和。","顧己誠拙訥，干名已蹉跎。","獻词惟在口，所欲無餘佗。","乍作支泉石，乍作翳松蘿。","一不改方圓，破質爲琢磨。","賤子本如此，大賢心若何。","豈是無異途，異途难經過。"]', '诗', 'shi', '', NULL, '上張徐州 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bbe57c4-65b2-4f16-8039-2e2a70c1316a', '上包祭酒', '上包祭酒', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["嶽嶽冠蓋彥，英英文字雄。","瓊音獨聽時，塵韻固不同。","春雲生紙上，秋濤起胸中。","時吟五君詠，再舉七子風。","何幸松桂侶，見知勤苦功。","願將黃鶴翅，一借飛雲空。"]', '["嶽嶽冠蓋彥，英英文字雄。","瓊音独听时，塵韻固不同。","春云生紙上，秋濤起胸中。","时吟五君詠，再舉七子风。","何幸松桂侶，见知勤苦功。","願將黄鹤翅，一借飞云空。"]', '诗', 'shi', '', NULL, '上包祭酒 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8edbaec-abd4-4508-96b5-5b99d41cdf2a', '贈別崔純亮', '贈別崔純亮', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["食薺腸亦苦，強歌聲無歡。","出門即有礙，誰謂天地寬。","有礙非遐方，長安大道傍。","小人智慮險，平地生太行。","鏡破不改光，蘭死不改香。","始知君子心，交久道益彰。","君心與我懷，離別俱迴遑。","譬如浸蘖泉，流苦已日長。","忍泣目易衰，忍憂形易傷。","項籍豈不壯，賈生豈不良。","當其失意時，涕泗各沾裳。","古人勸加餐，此餐難自強。","一飯九祝噎，一嗟十斷腸。","況是兒女怨，怨氣凌彼蒼。","彼蒼若有知，白日下清霜。","今朝始驚歎，碧落空茫茫。"]', '["食薺腸亦苦，強歌声無歡。","出门即有礙，誰謂天地寬。","有礙非遐方，长安大道傍。","小人智慮險，平地生太行。","镜破不改光，蘭死不改香。","始知君子心，交久道益彰。","君心與我懷，離別俱迴遑。","譬如浸蘖泉，流苦已日长。","忍泣目易衰，忍憂形易傷。","項籍豈不壯，賈生豈不良。","當其失意时，涕泗各沾裳。","古人勸加餐，此餐难自強。","一飯九祝噎，一嗟十斷腸。","況是兒女怨，怨氣凌彼蒼。","彼蒼若有知，白日下清霜。","今朝始驚歎，碧落空茫茫。"]', '诗', 'shi', '', NULL, '贈別崔純亮 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('722122cd-6919-4b44-938d-9ce698f0dfb0', '贈文應上人', '贈文應上人', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["棲遲青山巔，高靜身所便。","不踐有命草，但飲無聲泉。","齋性空轉寂，學情深更專。","經文開貝葉，衣製垂秋蓮。","厭此俗人羣，暫來還却旋。"]', '["棲遲青山巔，高静身所便。","不踐有命草，但饮無声泉。","斋性空轉寂，学情深更專。","經文开貝葉，衣製垂秋蓮。","厭此俗人羣，暫来還却旋。"]', '诗', 'shi', '', NULL, '贈文應上人 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b326233-1546-4645-8931-5bc81bcec480', '嚴河南', '嚴河南', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["赤令風骨峭，語言清霜寒。","不必用雄威，見者毛髮攢。","我有赤令心，未得赤令官。","終朝衡門下，忍志將筑彈。","君從西省郎，正有東洛觀。","洛民蕭條久，威恩憫撫難。","苦竹聲嘯雪，夜齋聞千竿。","詩人偶寄耳，聽苦心多端。","多端落杯酒，酒中方得歡。","隱士多飲酒，此言信難刊。","取次令坊沽，舉止務在寬。","何必紅燭嬌，始言清宴闌。","丈夫莫矜莊，矜莊不中看。"]', '["赤令风骨峭，語言清霜寒。","不必用雄威，见者毛髮攢。","我有赤令心，未得赤令官。","終朝衡门下，忍志將筑彈。","君從西省郎，正有东洛观。","洛民蕭條久，威恩憫撫难。","苦竹声嘯雪，夜斋闻千竿。","诗人偶寄耳，听苦心多端。","多端落杯酒，酒中方得歡。","隐士多饮酒，此言信难刊。","取次令坊沽，舉止務在寬。","何必紅燭嬌，始言清宴闌。","丈夫莫矜莊，矜莊不中看。"]', '诗', 'shi', '', NULL, '嚴河南 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97a3737c-dafe-4fbf-9cef-d59793fa827b', '贈李觀', '贈李观', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["誰言形影親，燈滅影去身。","誰言魚水歡，水竭魚枯鱗。","昔爲同恨客，今爲獨笑人。","捨予在泥轍，飄跡上雲津。","臥木易成蠹，棄花難再春。","何言對芳景，愁望極蕭晨。","埋劒誰識氣，匣弦日生塵。","願君語高風，爲余問蒼旻。"]', '["誰言形影親，灯滅影去身。","誰言鱼水歡，水竭鱼枯鱗。","昔爲同恨客，今爲独笑人。","捨予在泥轍，飄跡上云津。","臥木易成蠹，棄花难再春。","何言对芳景，愁望極蕭晨。","埋劒誰識氣，匣弦日生塵。","願君語高风，爲余问蒼旻。"]', '诗', 'shi', '', NULL, '贈李觀 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5e26004-8a53-4cd3-bc7f-105c85b67b09', '吳安西館贈從弟楚客', '吳安西館贈從弟楚客', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["蒙籠楊柳館，中有南風生。","風生今爲誰，湘客多遠情。","孤枕楚水夢，獨帆楚江程。","覺來殘恨深，尚與歸路幷。","玉匣五弦在，請君時一鳴。"]', '["蒙籠楊柳館，中有南风生。","风生今爲誰，湘客多远情。","孤枕楚水梦，独帆楚江程。","覺来殘恨深，尚與归路幷。","玉匣五弦在，請君时一鳴。"]', '诗', 'shi', '', NULL, '吳安西館贈從弟楚客 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d751d09e-5305-4a2c-ab02-3a6beac7ebae', '贈章仇將軍', '贈章仇將軍', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["將軍不誇劒，才氣爲英雄。","五嶽拽力內，百川傾意中。","本立誰敢拔，飛文自難窮。","前時天地翻，已有扶正功。"]', '["將軍不誇劒，才氣爲英雄。","五嶽拽力內，百川傾意中。","本立誰敢拔，飞文自难窮。","前时天地翻，已有扶正功。"]', '诗', 'shi', '', NULL, '贈章仇將軍 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('caed2f58-c96d-4d76-b27d-025989ec7125', '贈道月上人', '贈道月上人', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["僧貌淨無點，僧衣寧綴華。","尋常晝日行，不使身影斜。","飯朮煮松柏，坐山敷雲霞。","欲知禪隱高，緝薜爲袈裟。"]', '["僧貌淨無点，僧衣寧綴华。","尋常晝日行，不使身影斜。","飯朮煮松柏，坐山敷云霞。","欲知禪隐高，緝薜爲袈裟。"]', '诗', 'shi', '', NULL, '贈道月上人 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a9e3e53-cd89-43f4-a90f-f9f21e52899a', '抒情因上郎中二十二叔監察十五叔兼呈李益端公柳縝評事', '抒情因上郎中二十二叔監察十五叔兼呈李益端公柳縝評事', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["方憑指下弦，寫出心中言。","寸草賤子命，高山主人恩。","遊邊風沙意，夢楚波濤魂。","一日引別袂，九迴沾淚痕。","自悲何以然，在禮闕晨昏。","名利時轉甚，是非宵亦喧。","浮情少定主，百慮隨世翻。","舉此胸臆恨，幸從賢哲論。","明明三飛鸞，照物如朝暾。"]', '["方憑指下弦，寫出心中言。","寸草賤子命，高山主人恩。","游邊风沙意，梦楚波濤魂。","一日引別袂，九迴沾泪痕。","自悲何以然，在禮闕晨昏。","名利时轉甚，是非宵亦喧。","浮情少定主，百慮隨世翻。","舉此胸臆恨，幸從賢哲論。","明明三飞鸾，照物如朝暾。"]', '诗', 'shi', '', NULL, '抒情因上郎中二十二叔監察十五叔兼呈李益端公柳縝評事 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4a41811-d96e-4c66-bd18-54f4a135d638', '贈城郭道士', '贈城郭道士', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["望裏失却山，聽中遺却泉。","松枝休策雲，藥囊翻貯錢。","曾依青桂隣，學得白雪弦。","別來意未迴，世上爲隱仙。"]', '["望裏失却山，听中遺却泉。","松枝休策云，藥囊翻貯錢。","曾依青桂隣，学得白雪弦。","別来意未迴，世上爲隐仙。"]', '诗', 'shi', '', NULL, '贈城郭道士 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc0652a6-84c4-49e7-9f68-acdbe9e4de73', '桐廬山中贈李明府', '桐廬山中贈李明府', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["靜境無濁氛，清雨零碧雲。","千山不隱響，一葉動亦聞。","即此佳志士，精微誰相羣。","欲識楚章句，袖中蘭茝薰。"]', '["静境無濁氛，清雨零碧云。","千山不隐响，一葉动亦闻。","即此佳志士，精微誰相羣。","欲識楚章句，袖中蘭茝薰。"]', '诗', 'shi', '', NULL, '桐廬山中贈李明府 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d23cf818-caff-4858-b6f8-d7f178987574', '獻漢南樊尚書', '獻漢南樊尚书', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["天下昔崩亂，大君識賢臣。","衆木盡搖落，始見竹色真。","兵勢走山嶽，陽光潛埃塵。","心開玄女符，面縛清波人。","異俗既從化，澆風亦歸淳。","自公理斯郡，寒谷皆變春。","旗影卷赤電，劒鋒匣青鱗。","如何嵩高氣，作鎮楚水濱。","雲鏡忽開霽，孤光射無垠。","乃知尋常鑒，照影不照神。"]', '["天下昔崩亂，大君識賢臣。","衆木尽搖落，始见竹色真。","兵勢走山嶽，陽光潛埃塵。","心开玄女符，面縛清波人。","異俗既從化，澆风亦归淳。","自公理斯郡，寒谷皆变春。","旗影卷赤電，劒鋒匣青鱗。","如何嵩高氣，作鎮楚水濱。","云镜忽开霽，孤光射無垠。","乃知尋常鑒，照影不照神。"]', '诗', 'shi', '', NULL, '獻漢南樊尚書 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c89c328c-c196-4212-a4e1-fde7e2798b61', '贈轉運陸中丞', '贈轉運陸中丞', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["掌運職既大，摧邪名更雄。","鵬飛簸曲雲，鶚怒生直風。","投彼霜雪令，翦除荆棘叢。","楚倉傾向西，吳米發自東。","帆影咽河口，車聲聾關中。","堯知才策高，人喜道路通。","皆經內史力，繼得酇侯功。","萊子真爲少，相如未免窮。","衣花野菡萏，書葉山梧桐。","不是宗匠心，誰憐久棲蓬。"]', '["掌運職既大，摧邪名更雄。","鵬飞簸曲云，鶚怒生直风。","投彼霜雪令，翦除荆棘叢。","楚倉傾向西，吳米發自东。","帆影咽河口，车声聾关中。","堯知才策高，人喜道路通。","皆經內史力，繼得酇侯功。","萊子真爲少，相如未免窮。","衣花野菡萏，书葉山梧桐。","不是宗匠心，誰怜久棲蓬。"]', '诗', 'shi', '', NULL, '贈轉運陸中丞 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dce990f-7981-4f47-93fb-69ee9ba11688', '贈萬年陸郎中', '贈万年陸郎中', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["天子憂劇縣，寄深華省郎。","紛紛風響珮，蟄蟄劒開霜。","舊事笑堆案，新聲唯雅章。","誰言百里才，終作橫天梁。","江鴻恥承眷，雲津未能翔。","徘徊塵俗中，短毳無輝光。"]', '["天子憂劇縣，寄深华省郎。","紛紛风响珮，蟄蟄劒开霜。","旧事笑堆案，新声唯雅章。","誰言百里才，終作橫天梁。","江鴻恥承眷，云津未能翔。","徘徊塵俗中，短毳無輝光。"]', '诗', 'shi', '', NULL, '贈萬年陸郎中 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a27558b-ebcb-4073-a6fa-fe619881a570', '擢第後東歸書懷獻座主呂侍御', '擢第後东归书懷獻座主呂侍御', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["昔歲辭親淚，今爲戀主泣。","去住情難竝，別離景易戢。","夭矯大空鱗，曾爲小泉蟄。","幽意獨沈時，震雷忽相及。","神行既不宰，直致非所執。","至運本遺功，輕生各自立。","大君思此化，良佐自然集。","寶鏡無私光，時文有新習。","慈親誡志就，賤子歸情急。","擢第謝靈臺，牽衣出皇邑。","行襟海日曙，逸抱江風入。","蒹葭得波浪，芙蓉紅岸濕。","雲寺勢動搖，山鐘韻噓吸。","舊遊期再踐，懸水得重挹。","松蘿雖可居，青紫終當拾。"]', '["昔歲辞親泪，今爲戀主泣。","去住情难竝，別離景易戢。","夭矯大空鱗，曾爲小泉蟄。","幽意独沈时，震雷忽相及。","神行既不宰，直致非所執。","至運本遺功，轻生各自立。","大君思此化，良佐自然集。","寶镜無私光，时文有新習。","慈親誡志就，賤子归情急。","擢第謝靈台，牽衣出皇邑。","行襟海日曙，逸抱江风入。","蒹葭得波浪，芙蓉紅岸濕。","云寺勢动搖，山鐘韻噓吸。","旧游期再踐，懸水得重挹。","松蘿雖可居，青紫終當拾。"]', '诗', 'shi', '', NULL, '擢第後東歸書懷獻座主呂侍御 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe123ad6-7f8b-4bc9-a03d-16c07efc1358', '古意贈梁肅補闕', '古意贈梁肅補闕', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["曲木忌日影，讒人畏賢明。","自然照燭間，不受邪佞輕。","不有百煉火，孰知寸金精。","金鉛正同鑪，願分精與麤。"]', '["曲木忌日影，讒人畏賢明。","自然照燭间，不受邪佞轻。","不有百煉火，孰知寸金精。","金鉛正同鑪，願分精與麤。"]', '诗', 'shi', '', NULL, '古意贈梁肅補闕 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('586b9736-995d-4a92-b4c5-a65e70432e96', '贈黔府王中丞楚', '贈黔府王中丞楚', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["舊說天下山，半在黔中青。","又聞天下泉，半落黔中鳴。","山水千萬遶，中有君子行。","儒風一以扇，汙俗心皆平。","我願中國春，化從異方生。","昔爲陰草毒，今爲陽華英。","嘉實綴綠蔓，涼湍瀉清聲。","逍遙物景勝，視聽空曠幷。","困驥猶在轅，沉珠尚隱精。","路遐莫及眄，泥汙日已盈。","歲晏將何從，落葉甘自輕。"]', '["旧说天下山，半在黔中青。","又闻天下泉，半落黔中鳴。","山水千万遶，中有君子行。","儒风一以扇，汙俗心皆平。","我願中国春，化從異方生。","昔爲陰草毒，今爲陽华英。","嘉實綴綠蔓，涼湍瀉清声。","逍遙物景勝，視听空曠幷。","困驥猶在轅，沉珠尚隐精。","路遐莫及眄，泥汙日已盈。","歲晏將何從，落葉甘自轻。"]', '诗', 'shi', '', NULL, '贈黔府王中丞楚 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d975de03-a422-47c9-b4a1-30768576d816', '上達奚舍人', '上達奚舍人', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["北山少日月，草木苦風霜。","貧士在重坎，食梅有酸腸。","萬俗皆走圓，一身猶學方。","常恐衆毀至，春葉成秋黃。","大賢秉高鑒，公燭無私光。","暗室曉未及，幽行涕空行。"]', '["北山少日月，草木苦风霜。","貧士在重坎，食梅有酸腸。","万俗皆走圓，一身猶学方。","常恐衆毀至，春葉成秋黄。","大賢秉高鑒，公燭無私光。","暗室晓未及，幽行涕空行。"]', '诗', 'shi', '', NULL, '上達奚舍人 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01413869-a26e-4025-af70-eea03a58cbfe', '贈主人', '贈主人', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["斗水瀉大海，不如瀉枯池。","分明賢達交，豈顧豪華兒。","海有不足流，豪有不足資。","枯鱗易爲水，貧士易爲施。","幸覩君子席，會將幽賤期。","側聞清風議，飫如黃金巵。","此道與日月，同光無盡時。"]', '["斗水瀉大海，不如瀉枯池。","分明賢達交，豈顧豪华兒。","海有不足流，豪有不足資。","枯鱗易爲水，貧士易爲施。","幸覩君子席，會將幽賤期。","側闻清风議，飫如黄金巵。","此道與日月，同光無尽时。"]', '诗', 'shi', '', NULL, '贈主人 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('508a04f0-aed1-4158-aefe-be0ff41797ae', '贈建業契公', '贈建業契公', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["師住青山寺，清華常繞身。","雖然到城郭，衣不上棲塵。"]', '["師住青山寺，清华常繞身。","雖然到城郭，衣不上棲塵。"]', '诗', 'shi', '', NULL, '贈建業契公 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bd8ab64-ee6d-4ba5-938c-85650dace115', '獻襄陽于大夫', '獻襄陽于大夫', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["襄陽青山郭，漢江白銅堤。","謝公領茲郡，山水無塵泥。","鐵馬萬霜雪，絳旗千虹霓。","風漪參差泛，石板重疊躋。","舊淚不復墮，新歡居然齊。","還畊竟原野，歸老相扶攜。","物色增曖曖，寒芳更萋萋。","淵清有遐略，高躅無近蹊。","即此富蒼翠，自然引翔棲。","曩遊常抱憶，夙好今尚暌。","願言從逸轡，暇日凌清溪。"]', '["襄陽青山郭，漢江白銅堤。","謝公領茲郡，山水無塵泥。","鐵马万霜雪，絳旗千虹霓。","风漪參差泛，石板重叠躋。","旧泪不复墮，新歡居然齊。","還畊竟原野，归老相扶携。","物色增曖曖，寒芳更萋萋。","淵清有遐略，高躅無近蹊。","即此富蒼翠，自然引翔棲。","曩游常抱憶，夙好今尚暌。","願言從逸轡，暇日凌清溪。"]', '诗', 'shi', '', NULL, '獻襄陽于大夫 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6bcc594-fe63-4aa7-8d76-3a15d7fba078', '贈鄭夫子魴', '贈鄭夫子魴', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["天地入胸臆，吁嗟生風雷。","文章得其微，物象由我裁。","宋玉逞大句，李白飛狂才。","苟非聖賢心，孰與造化該。","勉矣鄭夫子，驪珠今始胎。"]', '["天地入胸臆，吁嗟生风雷。","文章得其微，物象由我裁。","宋玉逞大句，李白飞狂才。","苟非聖賢心，孰與造化該。","勉矣鄭夫子，驪珠今始胎。"]', '诗', 'shi', '', NULL, '贈鄭夫子魴 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec94c0a3-ef97-4d8c-b008-3fd1764cd335', '大隱坊 崔從事鄖以直隳職', '大隐坊 崔從事鄖以直隳職', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["古人留清風，千載遙贈君。","破松見貞心，裂竹見直文。","殘月色不改，高賢德常新。","家懷詩書富，宅抱草木貧。","安得一蹄泉，來化千尺鱗。","含意永不語，釣璜幽水濱。"]', '["古人留清风，千載遙贈君。","破松见貞心，裂竹见直文。","殘月色不改，高賢德常新。","家懷诗书富，宅抱草木貧。","安得一蹄泉，来化千尺鱗。","含意永不語，釣璜幽水濱。"]', '诗', 'shi', '', NULL, '大隱坊 崔從事鄖以直隳職 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b88f75dc-df70-45f9-87c9-11713eed0137', '大隱坊 章仇將軍良棄功守貧', '大隐坊 章仇將軍良棄功守貧', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["飲君江海心，詎能辨淺深。","挹君山嶽德，誰能齊嶔岑。","東海精爲月，西嶽氣凝金。","進則萬景晝，退則羣物陰。","我欲薦此言，天門峻沈沈。","風飆亦感激，爲我颼飀吟。"]', '["饮君江海心，詎能辨淺深。","挹君山嶽德，誰能齊嶔岑。","东海精爲月，西嶽氣凝金。","進則万景晝，退則羣物陰。","我欲薦此言，天门峻沈沈。","风飆亦感激，爲我颼飀吟。"]', '诗', 'shi', '', NULL, '大隱坊 章仇將軍良棄功守貧 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2dd3fa6-35ad-47a2-bc87-9f4ce44faf33', '大隱坊 趙記室俶在職無事', '大隐坊 趙記室俶在職無事', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["卑靜身後老，高動物先摧。","方圓水任器，剛勁木成灰。","大道母羣物，達人腹衆才。","時吟堯舜篇，心向無爲開。","彼隱山萬曲，我隱酒一杯。","公庭何所有，日日清風來。"]', '["卑静身後老，高动物先摧。","方圓水任器，剛勁木成灰。","大道母羣物，達人腹衆才。","时吟堯舜篇，心向無爲开。","彼隐山万曲，我隐酒一杯。","公庭何所有，日日清风来。"]', '诗', 'shi', '', NULL, '大隱坊 趙記室俶在職無事 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35e85885-54bb-4a99-ac17-260899034522', '贈韓郎中愈 一', '贈韓郎中愈 一', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["何以定交契，贈君高山石。","何以保貞堅，贈君青松色。","貧居過此外，無可相彩飾。","聞君碩鼠詩，吟之淚空滴。"]', '["何以定交契，贈君高山石。","何以保貞堅，贈君青松色。","貧居過此外，無可相彩飾。","闻君碩鼠诗，吟之泪空滴。"]', '诗', 'shi', '', NULL, '贈韓郎中愈 一 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c718f5d-5eee-4d05-bdd8-08ad87cd204c', '贈韓郎中愈 二', '贈韓郎中愈 二', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["碩鼠既穿墉，又嚙機上絲。","穿墉有閑土，嚙絲無餘衣。","朝吟枯桑柘，暮泣空杼機。","豈是無巧妙，絲斷將何施。","衆人尚肥華，志士多飢羸。","願君保此節，天意當察微。"]', '["碩鼠既穿墉，又嚙機上絲。","穿墉有闲土，嚙絲無餘衣。","朝吟枯桑柘，暮泣空杼機。","豈是無巧妙，絲斷將何施。","衆人尚肥华，志士多飢羸。","願君保此節，天意當察微。"]', '诗', 'shi', '', NULL, '贈韓郎中愈 二 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('691d3e81-f1d2-43ed-a8ce-181569c03d05', '贈韓郎中愈 三', '贈韓郎中愈 三', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["前日遠別離，今日生白髮。","欲知萬里情，曉臥半牀月。","常恐百蟲秋，使我芳草歇。"]', '["前日远別離，今日生白髮。","欲知万里情，晓臥半牀月。","常恐百蟲秋，使我芳草歇。"]', '诗', 'shi', '', NULL, '贈韓郎中愈 三 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22107002-3bdc-478c-a488-2aa99acc3f8b', '戲贈無本 一', '戲贈無本 一', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["長安秋聲乾，木葉相號悲。","瘦僧臥冰凌，嘲詠含金痍。","金痍非戰痕，峭病方在茲。","詩骨聳東野，詩濤湧退之。","有時踉蹌行，人驚鶴阿師。","可惜李杜死，不見此狂癡。"]', '["长安秋声乾，木葉相號悲。","瘦僧臥冰凌，嘲詠含金痍。","金痍非戰痕，峭病方在茲。","诗骨聳东野，诗濤湧退之。","有时踉蹌行，人驚鹤阿師。","可惜李杜死，不见此狂癡。"]', '诗', 'shi', '', NULL, '戲贈無本 一 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b4c36ff-cac2-4e3d-97e2-9bcff5c4e3b8', '戲贈無本 二', '戲贈無本 二', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["燕僧聳聽詞，袈裟喜新翻。","北岳厭利殺，玄功生微言。","天高亦可飛，海廣亦可源。","文章杳無底，劚掘誰能根。","夢靈髣髴到，對我方與論。","拾月鯨口邊，何人免爲吞。","燕僧擺造化，萬有隨手犇。","補綴雜霞衣，笑傲諸貴門。","將明文在身，亦爾道所存。","朔雪凝別句，朔風飄征魂。","再期嵩少遊，一訪蓬蘿村。","春草步步綠，春山日日暄。","遙鶯相應吟，晚聽恐不繁。","相思塞心胸，高逸難攀援。"]', '["燕僧聳听词，袈裟喜新翻。","北岳厭利殺，玄功生微言。","天高亦可飞，海廣亦可源。","文章杳無底，劚掘誰能根。","梦靈髣髴到，对我方與論。","拾月鯨口邊，何人免爲吞。","燕僧擺造化，万有隨手犇。","補綴杂霞衣，笑傲諸貴门。","將明文在身，亦爾道所存。","朔雪凝別句，朔风飄征魂。","再期嵩少游，一訪蓬蘿村。","春草步步綠，春山日日暄。","遙鶯相應吟，晚听恐不繁。","相思塞心胸，高逸难攀援。"]', '诗', 'shi', '', NULL, '戲贈無本 二 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8e9ed33-399c-4995-aae0-e0209c3eff2e', '寄張籍', '寄張籍', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["夜鏡不照物，朝光何時升。","黯然秋思來，走入志士膺。","志士惜時逝，一宵三四興。","清漢徒自朗，濁河終無澄。","舊愛忽已遠，新愁坐相凌。","君其隱壯懷，我亦逃名稱。","古人貴從晦，君子忌黨朋。","傾敗生所競，保全歸懵懵。","浮雲何當來，潛虯會飛騰。"]', '["夜镜不照物，朝光何时升。","黯然秋思来，走入志士膺。","志士惜时逝，一宵三四兴。","清漢徒自朗，濁河終無澄。","旧愛忽已远，新愁坐相凌。","君其隐壯懷，我亦逃名稱。","古人貴從晦，君子忌黨朋。","傾敗生所競，保全归懵懵。","浮云何當来，潛虯會飞腾。"]', '诗', 'shi', '', NULL, '寄張籍 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7b782c4-dbcf-497a-b9ef-63ceacc60522', '憶周秀才素上人時聞各在一方', '憶周秀才素上人时闻各在一方', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["東西分我情，魂夢安能定。","野客雲作心，高僧月爲性。","浮雲自高閑，明月常空淨。","衣敝得古風，居山無俗病。","吟聽碧雲語，手把青松柄。","羨爾欲寄書，飛禽杳難倩。"]', '["东西分我情，魂梦安能定。","野客云作心，高僧月爲性。","浮云自高闲，明月常空淨。","衣敝得古风，居山無俗病。","吟听碧云語，手把青松柄。","羨爾欲寄书，飞禽杳难倩。"]', '诗', 'shi', '', NULL, '憶周秀才素上人時聞各在一方 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('469ea863-7b08-4a83-824c-82ccf185f177', '舟中喜遇從叔簡別後寄上時從叔初擢第歸江南郊不從行', '舟中喜遇從叔簡別後寄上时從叔初擢第归江南郊不從行', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["一意兩片雲，暫合還却分。","南雲乘慶歸，北雲與誰羣。","寄聲千里風，相喚聞不聞。"]', '["一意兩片云，暫合還却分。","南云乘慶归，北云與誰羣。","寄声千里风，相喚闻不闻。"]', '诗', 'shi', '', NULL, '舟中喜遇從叔簡別後寄上時從叔初擢第歸江南郊不從行 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('151122cb-9900-416d-8b06-bafacb4e5549', '懷南岳隱士 一', '懷南岳隐士 一', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["見說祝融峰，擎天勢似騰。","藏千尋布水，出十八高僧。","古路無人跡，新霞吐石稜。","終居將爾叟，一一共余登。"]', '["见说祝融峰，擎天勢似腾。","藏千尋布水，出十八高僧。","古路無人跡，新霞吐石稜。","終居將爾叟，一一共余登。"]', '诗', 'shi', '', NULL, '懷南岳隱士 一 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('370aba20-4559-4d44-99f4-c63a73126e38', '懷南岳隱士 二', '懷南岳隐士 二', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["千峰映碧湘，真叟此中藏。","飯不煮石喫，眉應似髮長。","楓梩搘酒甕，鶴蝨落琴牀。","強效忘機者，斯人尚未忘。"]', '["千峰映碧湘，真叟此中藏。","飯不煮石喫，眉應似髮长。","楓梩搘酒甕，鹤蝨落琴牀。","強效忘機者，斯人尚未忘。"]', '诗', 'shi', '', NULL, '懷南岳隱士 二 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fecd42d7-482f-4022-8ca7-e7adcdf1169c', '春夜憶蕭子真', '春夜憶蕭子真', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["半夜不成寐，燈盡又無月。","獨向堦前立，子規啼不歇。","況我有金蘭，忽爾爲胡越。","爭得明鏡中，久長無白髮。"]', '["半夜不成寐，灯尽又無月。","独向堦前立，子規啼不歇。","況我有金蘭，忽爾爲胡越。","爭得明镜中，久长無白髮。"]', '诗', 'shi', '', NULL, '春夜憶蕭子真 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('661df0b5-7ae6-4190-bdf7-70a639fad61d', '寄院中諸公', '寄院中諸公', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["奕奕秋水傍，駸駸綠雲蹄。","月仙有高曜，靈鳳無卑棲。","翠色遶雲谷，碧華凝月溪。","竹林遞歷覽，雲寺行攀躋。","冠豸獨屈蠖，匣龍期剸犀。","千山驚月曉，百里聞霜鼙。","戎府多秀異，謝公期相攜。","因之仰羣彥，養拙固難齊。"]', '["奕奕秋水傍，駸駸綠云蹄。","月仙有高曜，靈鳳無卑棲。","翠色遶云谷，碧华凝月溪。","竹林遞歷覽，云寺行攀躋。","冠豸独屈蠖，匣龙期剸犀。","千山驚月晓，百里闻霜鼙。","戎府多秀異，謝公期相携。","因之仰羣彥，養拙固难齊。"]', '诗', 'shi', '', NULL, '寄院中諸公 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb282e80-c8c0-427b-a0f0-5f86341bb962', '寄洺州李大夫', '寄洺州李大夫', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["自從薊師反，中國事紛紛。","儒道一失所，賢人多在軍。","鳥巢憂迸射，鹿耳駭驚聞。","劍折唯恐匣，弓貪不讓勳。","方知省事將，動必謝前羣。","鸛陣常先罷，魚符最晚分。","步閑洺水曲，笑激太行雲。","詩叟未相識，竹兒爭見君。","殷勤越談說，記盡古風文。"]', '["自從薊師反，中国事紛紛。","儒道一失所，賢人多在軍。","鸟巢憂迸射，鹿耳駭驚闻。","劍折唯恐匣，弓貪不讓勳。","方知省事將，动必謝前羣。","鸛陣常先罷，鱼符最晚分。","步闲洺水曲，笑激太行云。","诗叟未相識，竹兒爭见君。","殷勤越談说，記尽古风文。"]', '诗', 'shi', '', NULL, '寄洺州李大夫 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9c03668-409b-4290-b7cb-22c8b1ecdbd5', '寄盧虔使君', '寄盧虔使君', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["霜露再相換，遊人猶未歸。","歲新月改色，客久線斷衣。","有鶴冰在翅，竟久力難飛。","千家舊素沼，昨日生綠輝。","春色若可借，爲君步芳菲。"]', '["霜露再相換，游人猶未归。","歲新月改色，客久線斷衣。","有鹤冰在翅，竟久力难飞。","千家旧素沼，昨日生綠輝。","春色若可借，爲君步芳菲。"]', '诗', 'shi', '', NULL, '寄盧虔使君 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dd4e413-e9fd-4afc-9c55-fff3ee1a86d3', '寄崔純亮', '寄崔純亮', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["百川有餘水，大海無滿波。","器量各相懸，賢愚不同科。","羣辯有姿語，衆歡無行歌。","唯餘洛陽子，鬱鬱恨常多。","時讀過秦篇，爲君涕滂沱。"]', '["百川有餘水，大海無满波。","器量各相懸，賢愚不同科。","羣辯有姿語，衆歡無行歌。","唯餘洛陽子，鬱鬱恨常多。","时读過秦篇，爲君涕滂沱。"]', '诗', 'shi', '', NULL, '寄崔純亮 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddd8f318-28d9-45fe-9660-fac93b8210f4', '汴州離亂後憶韓愈李翱', '汴州離亂後憶韓愈李翱', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["會合一時哭，別離三斷腸。","殘花不待風，春盡各飛揚。","歡去收不得，悲來難自防。","孤門清館夜，獨臥明月牀。","忠直血白刃，道路聲蒼黃。","食恩三千士，一旦爲豺狼。","海島士皆直，夷門士非良。","人心既不類，天道亦反常。","自殺與彼殺，未知何者臧。"]', '["會合一时哭，別離三斷腸。","殘花不待风，春尽各飞揚。","歡去收不得，悲来难自防。","孤门清館夜，独臥明月牀。","忠直血白刃，道路声蒼黄。","食恩三千士，一旦爲豺狼。","海島士皆直，夷门士非良。","人心既不類，天道亦反常。","自殺與彼殺，未知何者臧。"]', '诗', 'shi', '', NULL, '汴州離亂後憶韓愈李翱 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('037daca3-070f-4844-b52b-53ea28fbe276', '寄張籍', '寄張籍', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["未見天子面，不如雙盲人。","賈生對文帝，終日猶悲辛。","夫子亦如盲，所以空泣麟。","有時獨齋心，髣髴夢稱臣。","夢中稱臣言，覺後真埃塵。","東京有眼富不如，西京無眼貧西京。","無眼猶有耳隔牆，時聞天子車轔轔。","轔轔車聲輾冰玉，南郊壇上禮百神。","西明寺後窮瞎張太祝，縱爾有眼誰爾珍。","天子咫尺不得見，不如閉眼且養真。"]', '["未见天子面，不如雙盲人。","賈生对文帝，終日猶悲辛。","夫子亦如盲，所以空泣麟。","有时独斋心，髣髴梦稱臣。","梦中稱臣言，覺後真埃塵。","东京有眼富不如，西京無眼貧西京。","無眼猶有耳隔牆，时闻天子车轔轔。","轔轔车声輾冰玉，南郊壇上禮百神。","西明寺後窮瞎張太祝，縱爾有眼誰爾珍。","天子咫尺不得见，不如閉眼且養真。"]', '诗', 'shi', '', NULL, '寄張籍 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c72ab4e6-6649-40e9-8c7a-f3e5bf6f3fe8', '寄義興小女子', '寄義兴小女子', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["江南莊宅淺，所固唯疎籬。","小女未解行，酒弟老更癡。","家中多吳語，教爾遙可知。","山怪夜動門，水妖時弄池。","所憂癡酒腸，不解委曲辭。","漁妾性崛強，耕童手皴釐。","想茲爲襁褓，如鳥拾柴枝。","我詠元魯山，胸臆流甘滋。","終當學自乳，起坐常相隨。"]', '["江南莊宅淺，所固唯疎籬。","小女未解行，酒弟老更癡。","家中多吳語，教爾遙可知。","山怪夜动门，水妖时弄池。","所憂癡酒腸，不解委曲辞。","漁妾性崛強，耕童手皴釐。","想茲爲襁褓，如鸟拾柴枝。","我詠元魯山，胸臆流甘滋。","終當学自乳，起坐常相隨。"]', '诗', 'shi', '', NULL, '寄義興小女子 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dddb79fa-7c1c-4854-9738-3d4de5dbfcce', '憶江南弟', '憶江南弟', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["白首眼垂血，望爾唯夢中。","筋力強起時，魂魄猶在東。","眼光寄明星，起來東望空。","望空不見人，江海波無窮。","衰老無氣力，呼叫不成風。","孑然憶憶言，落地何由通。","常師共被教，竟作生離翁。","生離不可訴，上天何曾聰。","未忍對松栢，自鞭殘朽躬。","自鞭亦何益，知教非所崇。","努力拄杖來，餘活與爾同。","不然死後恥，遺死亦有終。"]', '["白首眼垂血，望爾唯梦中。","筋力強起时，魂魄猶在东。","眼光寄明星，起来东望空。","望空不见人，江海波無窮。","衰老無氣力，呼叫不成风。","孑然憶憶言，落地何由通。","常師共被教，竟作生離翁。","生離不可訴，上天何曾聰。","未忍对松栢，自鞭殘朽躬。","自鞭亦何益，知教非所崇。","努力拄杖来，餘活與爾同。","不然死後恥，遺死亦有終。"]', '诗', 'shi', '', NULL, '憶江南弟 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18150e75-3efd-4f7d-a525-89761eb9b260', '宿空姪院寄澹公', '宿空姪院寄澹公', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["夜坐冷竹聲，二三高人語。","燈窗看律鈔，小師別爲侶。","雪簷晴滴滴，茗椀華舉舉。","磬音多風飆，聲韻聞江楚。","官街不相隔，詩思空愁予。","明日策杖歸，去住兩延佇。"]', '["夜坐冷竹声，二三高人語。","灯窗看律鈔，小師別爲侶。","雪簷晴滴滴，茗椀华舉舉。","磬音多风飆，声韻闻江楚。","官街不相隔，诗思空愁予。","明日策杖归，去住兩延佇。"]', '诗', 'shi', '', NULL, '宿空姪院寄澹公 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7aab388-f346-40c3-809f-ca48fefe588c', '寄陝府鄧給事', '寄陝府鄧給事', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["陝城臨大道，館宇屹幾鮮。","候謁隨芳語，鏗詞芬蜀牋。","從來鏡目下，見盡道心前。","自謂古詩量，異將新學偏。","戇人年六十，每月請三千。","不敢等閑用，願爲長壽錢。","非關亦潔爾，將以救羸然。","孤省癡皎皎，默吟寫綿綿。","病書憑晝日，驛信寄宵鞭。","疾訴將何諭，肆鱗今倒懸。","塵鯉見枯浪，土鬣思乾泉。","感感無緒蕩，愁愁作□邊。","貞元文祭酒，比謹學韋玄。","滿坐風無雜，當朝雅獨全。","見知囑徐孺，賞句類陶淵。","一顧生鴻羽，再言將鶴翩。","宣揚隘車馬，君子湊駢闐。","曾是此同睠，至今應賜憐。","磨墨零落淚，楷字貢仁賢。"]', '["陝城臨大道，館宇屹幾鲜。","候謁隨芳語，鏗词芬蜀牋。","從来镜目下，见尽道心前。","自謂古诗量，異將新学偏。","戇人年六十，每月請三千。","不敢等闲用，願爲长壽錢。","非关亦潔爾，將以救羸然。","孤省癡皎皎，默吟寫綿綿。","病书憑晝日，驛信寄宵鞭。","疾訴將何諭，肆鱗今倒懸。","塵鯉见枯浪，土鬣思乾泉。","感感無緒蕩，愁愁作□邊。","貞元文祭酒，比謹学韋玄。","满坐风無杂，當朝雅独全。","见知囑徐孺，賞句類陶淵。","一顧生鴻羽，再言將鹤翩。","宣揚隘车马，君子湊駢闐。","曾是此同睠，至今應賜怜。","磨墨零落泪，楷字貢仁賢。"]', '诗', 'shi', '', NULL, '寄陝府鄧給事 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e6bfc9a-9e1a-42e6-bf59-89566c0b1932', '送諫議十六叔至孝義渡後奉寄', '送諫議十六叔至孝義渡後奉寄', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["曉渡明鏡中，霞衣相飄颻。","浪鳧驚亦雙，蓬客將誰僚。","別飲孤易醒，離憂壯難銷。","文清雖無敵，儒貴不敢驕。","江吏捧紫泥，海旗剪紅蕉。","分明太守禮，跨躡毗陵橋。","伊洛去未迴，遐矚空寂寥。"]', '["晓渡明镜中，霞衣相飄颻。","浪鳧驚亦雙，蓬客將誰僚。","別饮孤易醒，離憂壯难銷。","文清雖無敵，儒貴不敢驕。","江吏捧紫泥，海旗剪紅蕉。","分明太守禮，跨躡毗陵橋。","伊洛去未迴，遐矚空寂寥。"]', '诗', 'shi', '', NULL, '送諫議十六叔至孝義渡後奉寄 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7029a7d-14d4-4ef3-a1fd-3924e4f1cc8d', '至孝義渡寄鄭軍事唐二十五', '至孝義渡寄鄭軍事唐二十五', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["咫尺不得見，心中空嗟嗟。","官街泥水深，下脚道路斜。","嵩少玉峻峻，伊雒碧華華。","岸亭當四迥，詩老獨一家。","洧叟何所如，鄭石唯有些。","何當來說事，爲君開流霞。"]', '["咫尺不得见，心中空嗟嗟。","官街泥水深，下脚道路斜。","嵩少玉峻峻，伊雒碧华华。","岸亭當四迥，诗老独一家。","洧叟何所如，鄭石唯有些。","何當来说事，爲君开流霞。"]', '诗', 'shi', '', NULL, '至孝義渡寄鄭軍事唐二十五 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2247f55-4e93-48ad-9ee3-3c65e0e55725', '答友人', '答友人', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["白日照清水，淺深無隱姿。","君子業高文，懷抱多正思。","砥行碧山石，結交青松枝。","碧山無轉易，青松難傾移。","落落出俗韻，琅琅大雅詞。","自非隨氏掌，明月安能持。","千里不可倒，一返無近期。","如何非意中，良覿忽在茲。","道語必疎淡，儒風易凌遲。","願存堅貞節，勿爲霜霰欺。"]', '["白日照清水，淺深無隐姿。","君子業高文，懷抱多正思。","砥行碧山石，結交青松枝。","碧山無轉易，青松难傾移。","落落出俗韻，琅琅大雅词。","自非隨氏掌，明月安能持。","千里不可倒，一返無近期。","如何非意中，良覿忽在茲。","道語必疎淡，儒风易凌遲。","願存堅貞節，勿爲霜霰欺。"]', '诗', 'shi', '', NULL, '答友人 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8842219-6716-4e7c-89e9-b92d58d8d654', '酬友人見寄新文', '酬友人见寄新文', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["爲客棲未定，況當玄月中。","繁雲翳碧霄，落雪和清風。","郊陌絕行人，原隰多飛蓬。","耕牛返村巷，野鳥依房櫳。","我無饑凍憂，身託蓮花宮。","安閑賴禪伯，復得疏塵蒙。","覽君郢曲文，詞彩何沖融。","謳吟不能已，頓覺形神空。"]', '["爲客棲未定，況當玄月中。","繁云翳碧霄，落雪和清风。","郊陌絕行人，原隰多飞蓬。","耕牛返村巷，野鸟依房櫳。","我無饑凍憂，身託蓮花宮。","安闲賴禪伯，复得疏塵蒙。","覽君郢曲文，词彩何沖融。","謳吟不能已，頓覺形神空。"]', '诗', 'shi', '', NULL, '酬友人見寄新文 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33ca206a-03ef-462f-a1ad-beec2ba07560', '答韓愈李觀別因獻張徐州', '答韓愈李观別因獻張徐州', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["富別愁在顏，貧別愁銷骨。","懶磨舊銅鏡，畏見新白髮。","古樹春無花，子規啼有血。","離弦不堪聽，一聽四五絕。","世途非一險，俗慮有千結。","有客步大方，驅車獨迷轍。","故人韓與李，逸翰雙皎潔。","哀我摧折歸，贈詞縱橫設。","徐方國東樞，元戎天下傑。","禰生投刺遊，王粲吟詩謁。","高情無遺照，朗抱開曉月。","有土不埋冤，有讎皆爲雪。","願爲直草木，永向君地列。","願爲古琴瑟，永向君聽發。","欲識丈夫心，會將孤劍說。"]', '["富別愁在顏，貧別愁銷骨。","懶磨旧銅镜，畏见新白髮。","古樹春無花，子規啼有血。","離弦不堪听，一听四五絕。","世途非一險，俗慮有千結。","有客步大方，驱车独迷轍。","故人韓與李，逸翰雙皎潔。","哀我摧折归，贈词縱橫設。","徐方国东樞，元戎天下傑。","禰生投刺游，王粲吟诗謁。","高情無遺照，朗抱开晓月。","有土不埋冤，有讎皆爲雪。","願爲直草木，永向君地列。","願爲古琴瑟，永向君听發。","欲識丈夫心，會將孤劍说。"]', '诗', 'shi', '', NULL, '答韓愈李觀別因獻張徐州 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63a9811c-86f6-45ec-a071-c45f8463d5f7', '答晝上人止讒作', '答晝上人止讒作', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["烈烈鸑鷟吟，鏗鏗琅玕音。","梟摧明月嘯，鶴起清風心。","渭水不可渾，涇流徒相侵。","俗侶唱桃葉，隱士鳴桂琴。","子野真遺却，浮淺藏淵深。"]', '["烈烈鸑鷟吟，鏗鏗琅玕音。","梟摧明月嘯，鹤起清风心。","渭水不可渾，涇流徒相侵。","俗侶唱桃葉，隐士鳴桂琴。","子野真遺却，浮淺藏淵深。"]', '诗', 'shi', '', NULL, '答晝上人止讒作 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('813bcd01-9d71-4337-bb3b-615d83e9c631', '答姚怤見寄', '答姚怤见寄', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["日月不同光，晝夜各有宜。","賢哲不苟合，出處亦待時。","而我獨迷見，意求異士知。","如將舞鶴管，誤向驚鳧吹。","大雅難具陳，正聲易漂淪。","君有丈夫淚，泣人不泣身。","行吟楚山玉，義淚沾衣巾。"]', '["日月不同光，晝夜各有宜。","賢哲不苟合，出处亦待时。","而我独迷见，意求異士知。","如將舞鹤管，誤向驚鳧吹。","大雅难具陳，正声易漂淪。","君有丈夫泪，泣人不泣身。","行吟楚山玉，義泪沾衣巾。"]', '诗', 'shi', '', NULL, '答姚怤見寄 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dfff14e-59b0-47fd-94a3-4dcb0dd5292a', '答郭郎中', '答郭郎中', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["松栢死不變，千年色青青。","志士貧更堅，守道無異營。","每彈瀟湘瑟，獨抱風波聲。","中有失意吟，知者淚滿纓。","何以報知者，永存堅與貞。"]', '["松栢死不变，千年色青青。","志士貧更堅，守道無異營。","每彈瀟湘瑟，独抱风波声。","中有失意吟，知者泪满纓。","何以報知者，永存堅與貞。"]', '诗', 'shi', '', NULL, '答郭郎中 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cff74d90-de40-4e9a-a1b8-f3885700f76d', '答盧虔故園見寄', '答盧虔故园见寄', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["訪舊無一人，獨歸清雒春。","花聞哭聲死，水見別容新。","亂後故鄉宅，多爲行路塵。","因悲楚左右，謗玉不知珉。"]', '["訪旧無一人，独归清雒春。","花闻哭声死，水见別容新。","亂後故乡宅，多爲行路塵。","因悲楚左右，謗玉不知珉。"]', '诗', 'shi', '', NULL, '答盧虔故園見寄 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7dc3547-262e-46d9-8dc5-65e59847b438', '汝墳蒙從弟楚材見贈時郊將入秦楚材適楚', '汝墳蒙從弟楚材见贈时郊將入秦楚材適楚', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["朝爲主人心，暮爲行客吟。","汝水忽淒咽，汝風流苦音。","北闕秦門高，南路楚石深。","分淚灑白日，離腸繞青岑。","何以寄遠懷，黃鶴能相尋。"]', '["朝爲主人心，暮爲行客吟。","汝水忽淒咽，汝风流苦音。","北闕秦门高，南路楚石深。","分泪灑白日，離腸繞青岑。","何以寄远懷，黄鹤能相尋。"]', '诗', 'shi', '', NULL, '汝墳蒙從弟楚材見贈時郊將入秦楚材適楚 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebea1a6d-f894-4fbd-a4d7-71310b0b8ac5', '同從叔簡酬盧殷少府', '同從叔簡酬盧殷少府', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["梅尉吟楚聲，竹風爲淒清。","深虛冰在性，高潔雲入情。","借水洗閑貌，寄蕉書逸名。","羞將片石文，鬬此雙瓊英。"]', '["梅尉吟楚声，竹风爲淒清。","深虛冰在性，高潔云入情。","借水洗闲貌，寄蕉书逸名。","羞將片石文，鬬此雙瓊英。"]', '诗', 'shi', '', NULL, '同從叔簡酬盧殷少府 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e27ad4d3-aca5-4d2b-947f-3f3875c3e4a0', '酬李侍御書記秋夕雨中病假見寄', '酬李侍御书記秋夕雨中病假见寄', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["秋風遶衰柳，遠客聞雨聲。","重茲阻良夕，孤坐唯積誠。","果枉移疾詠，中含嘉慮明。","洗滌煩濁盡，視聽昭曠生。","未覺衾枕倦，久爲章奏嬰。","達人不寶藥，所保在閑情。"]', '["秋风遶衰柳，远客闻雨声。","重茲阻良夕，孤坐唯積誠。","果枉移疾詠，中含嘉慮明。","洗滌煩濁尽，視听昭曠生。","未覺衾枕倦，久爲章奏嬰。","達人不寶藥，所保在闲情。"]', '诗', 'shi', '', NULL, '酬李侍御書記秋夕雨中病假見寄 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65bd4ccd-a4b5-489f-9cc9-d575d5ef735c', '答盧仝', '答盧仝', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["楚屈入水死，詩孟踏雪僵。","直氣苟有存，死亦何所妨。","日劈高查牙，清稜含冰漿。","前古後古冰，與山氣勢強。","閃怪千石形，異狀安可量。","有時春鏡破，百道聲飛揚。","潛仙不足言，朗客無隱腸。","爲君傾海宇，日夕多文章。","天下豈無緣，此山雪昂藏。","煩君前致詞，哀我老更狂。","狂歌不及狂，歌聲緣鳳皇。","鳳兮何當來，消我孤直瘡。","君文真鳳聲，宣隘滿鏗鏘。","洛友零落盡，逮茲悲重傷。","獨自奮異骨，將騎白角翔。","再三勸莫行，寒氣有刀槍。","仰慙君子多，慎勿作芬芳。"]', '["楚屈入水死，诗孟踏雪僵。","直氣苟有存，死亦何所妨。","日劈高查牙，清稜含冰漿。","前古後古冰，與山氣勢強。","閃怪千石形，異狀安可量。","有时春镜破，百道声飞揚。","潛仙不足言，朗客無隐腸。","爲君傾海宇，日夕多文章。","天下豈無緣，此山雪昂藏。","煩君前致词，哀我老更狂。","狂歌不及狂，歌声緣鳳皇。","鳳兮何當来，消我孤直瘡。","君文真鳳声，宣隘满鏗鏘。","洛友零落尽，逮茲悲重傷。","独自奮異骨，將騎白角翔。","再三勸莫行，寒氣有刀槍。","仰慙君子多，慎勿作芬芳。"]', '诗', 'shi', '', NULL, '答盧仝 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('788bf024-af98-4350-b910-fd112900b023', '奉報翰林張舍人見遺之詩', '奉報翰林張舍人见遺之诗', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["百蟲笑秋律，清削月夜聞。","曉稜視聽微，風剪葉已紛。","君子鑒大雅，老人非俊羣。","收拾古所棄，俛仰補空文。","孤韻恥春俗，餘響逸零雰。","自然蹈終南，滌暑凌寒氛。","巖霰不知午，磵澌鎮含曛。","曾是醒古醉，所以多隱淪。","江調樂之遠，溪謠生徒新。","衆蘊有餘采，寒泉空哀呻。","南謝竟莫至，北宋當時珍。","賾靈各自異，酌酒誰能均。","昔詠多寫諷，今詞詎無因。","品松何高翠，宮殿沒荒榛。","苔趾識宏製，沙潨游崩津。","忽吟陶淵明，此即羲皇人。","心放出天地，形拘在風塵。","前賢素行階，夙嗜青山勤。","達士立明鏡，朗言爲近臣。","將期律萬有，傾倒甄無垠。","鸑鷟應蟋蟀，絲毫意皆申。","況於三千章，哀叩不爲神。"]', '["百蟲笑秋律，清削月夜闻。","晓稜視听微，风剪葉已紛。","君子鑒大雅，老人非俊羣。","收拾古所棄，俛仰補空文。","孤韻恥春俗，餘响逸零雰。","自然蹈終南，滌暑凌寒氛。","巖霰不知午，磵澌鎮含曛。","曾是醒古醉，所以多隐淪。","江調乐之远，溪謠生徒新。","衆蘊有餘采，寒泉空哀呻。","南謝竟莫至，北宋當时珍。","賾靈各自異，酌酒誰能均。","昔詠多寫諷，今词詎無因。","品松何高翠，宮殿沒荒榛。","苔趾識宏製，沙潨游崩津。","忽吟陶淵明，此即羲皇人。","心放出天地，形拘在风塵。","前賢素行階，夙嗜青山勤。","達士立明镜，朗言爲近臣。","將期律万有，傾倒甄無垠。","鸑鷟應蟋蟀，絲毫意皆申。","況於三千章，哀叩不爲神。"]', '诗', 'shi', '', NULL, '奉報翰林張舍人見遺之詩 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a1659cf-edde-4a0a-b285-90e483003c2c', '送從弟郢東歸', '送從弟郢东归', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["爾去東南夜，我無西北夢。","誰言貧別易，貧別愁更重。","曉色奪明月，征人逐羣動。","秋風楚濤高，旅榜將誰共。"]', '["爾去东南夜，我無西北梦。","誰言貧別易，貧別愁更重。","晓色奪明月，征人逐羣动。","秋风楚濤高，旅榜將誰共。"]', '诗', 'shi', '', NULL, '送從弟郢東歸 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63c31a5c-2392-49c5-a0dc-b387ca65b716', '山中送從叔簡赴舉', '山中送從叔簡赴舉', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["石根百尺杉，山眼一片泉。","倚之道氣高，飲之詩思鮮。","於此逍遙場，忽奏別離弦。","却笑薜蘿子，不同鳴躍年。"]', '["石根百尺杉，山眼一片泉。","倚之道氣高，饮之诗思鲜。","於此逍遙場，忽奏別離弦。","却笑薜蘿子，不同鳴躍年。"]', '诗', 'shi', '', NULL, '山中送從叔簡赴舉 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3eb6869-21ba-4981-938c-0da0a127e375', '送別崔寅亮下第', '送別崔寅亮下第', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["天地唯一氣，用之自偏頗。","憂人成苦吟，達士爲高歌。","君子識不淺，桂枝憂更多。","歲晏期攀折，時歸且婆娑。","素質如削玉，清詞若傾河。","虯龍未化時，魚鱉同一波。","去矣當自適，故鄉饒薜蘿。"]', '["天地唯一氣，用之自偏頗。","憂人成苦吟，達士爲高歌。","君子識不淺，桂枝憂更多。","歲晏期攀折，时归且婆娑。","素質如削玉，清词若傾河。","虯龙未化时，鱼鱉同一波。","去矣當自適，故乡饒薜蘿。"]', '诗', 'shi', '', NULL, '送別崔寅亮下第 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('064df4f4-45b7-48c9-83ac-648bc4efc695', '大梁送柳淳先入關', '大梁送柳淳先入关', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["青山輾爲塵，白日無閑人。","自古推高車，爭利西入秦。","王門與侯門，待富不待貧。","空攜一束書，去去誰相親。"]', '["青山輾爲塵，白日無闲人。","自古推高车，爭利西入秦。","王门與侯门，待富不待貧。","空携一束书，去去誰相親。"]', '诗', 'shi', '', NULL, '大梁送柳淳先入關 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbff6412-2ead-4d22-830c-084cb4941c74', '送無懷道士遊富春山水', '送無懷道士游富春山水', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["造化絕高處，富春獨多觀。","山濃翠滴灑，水折珠摧殘。","溪鏡不隱髮，樹衣長遇寒。","風猿虛空飛，月狖叫嘯酸。","信此神僊路，豈爲時俗安。","煮金陰陽火，囚怪星宿壇。","花發我未識，玉生忽藂攢。","蓬萊浮蕩漾，非道相從難。"]', '["造化絕高处，富春独多观。","山濃翠滴灑，水折珠摧殘。","溪镜不隐髮，樹衣长遇寒。","风猿虛空飞，月狖叫嘯酸。","信此神僊路，豈爲时俗安。","煮金陰陽火，囚怪星宿壇。","花發我未識，玉生忽藂攢。","蓬萊浮蕩漾，非道相從难。"]', '诗', 'shi', '', NULL, '送無懷道士遊富春山水 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7be84a2-5ba3-47f7-8305-00b604fcc052', '送溫初下第', '送溫初下第', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["日落濁水中，夜光誰能分。","高懷無近趣，清抱多遠聞。","欲識丈夫志，心藏孤岳雲。","長安風塵別，咫尺不見君。"]', '["日落濁水中，夜光誰能分。","高懷無近趣，清抱多远闻。","欲識丈夫志，心藏孤岳云。","长安风塵別，咫尺不见君。"]', '诗', 'shi', '', NULL, '送溫初下第 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9494d6f3-87a2-43e8-aa96-099f9f6c2f39', '送盧虔端公守復州', '送盧虔端公守复州', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["師曠聽羣木，自然識孤桐。","正聲逢知音，願出大朴中。","知音不韻俗，獨立占古風。","忽挂觸邪冠，逮逐南飛鴻。","肅肅太守章，明明華轂熊。","商山無平路，楚水有驚潨。","日月千里外，光陰難載同。","新愁徒自積，良會何由通。"]', '["師曠听羣木，自然識孤桐。","正声逢知音，願出大朴中。","知音不韻俗，独立占古风。","忽挂觸邪冠，逮逐南飞鴻。","肅肅太守章，明明华轂熊。","商山無平路，楚水有驚潨。","日月千里外，光陰难載同。","新愁徒自積，良會何由通。"]', '诗', 'shi', '', NULL, '送盧虔端公守復州 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('687f2bd0-0bc8-4707-b619-e8b8b6d33549', '送任載齊古二秀才自洞庭遊宣城', '送任載齊古二秀才自洞庭游宣城', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["洞庭非人境，道路行虛空。","二客月中下，一帆天外風。","魚龍波五色，金碧樹千叢。","閃怪如可懼，在誠無不通。","扣奇知浩淼，采異訪穹崇。","物表即高韻，人間訪仙公。","宣城文雅地，謝守聲聞融。","證玉易爲力，辨珉誰不同。","從茲阮籍淚，且免泣途窮。"]', '["洞庭非人境，道路行虛空。","二客月中下，一帆天外风。","鱼龙波五色，金碧樹千叢。","閃怪如可懼，在誠無不通。","扣奇知浩淼，采異訪穹崇。","物表即高韻，人间訪仙公。","宣城文雅地，謝守声闻融。","證玉易爲力，辨珉誰不同。","從茲阮籍泪，且免泣途窮。"]', '诗', 'shi', '', NULL, '送任載齊古二秀才自洞庭遊宣城 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62768965-b8e2-44ba-8bc0-d25a7c9a5919', '送曉公歸庭山', '送晓公归庭山', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["庭山何崎嶇，寺路緣翠微。","秋霽山盡出，日落人獨歸。","雲生高高步，泉灑田田衣。","枯巢無還羽，新木有爭飛。","茲焉不可繼，夢寐空清輝。"]', '["庭山何崎嶇，寺路緣翠微。","秋霽山尽出，日落人独归。","云生高高步，泉灑田田衣。","枯巢無還羽，新木有爭飞。","茲焉不可繼，梦寐空清輝。"]', '诗', 'shi', '', NULL, '送曉公歸庭山 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f7f9ddf-5c2d-4d93-ac43-d2e1ca1c3e2e', '送豆盧策歸別墅', '送豆盧策归別墅', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["短松鶴不巢，高石雲不棲。","君今瀟湘去，意與雲鶴齊。","力買奇險地，手開清淺溪。","身披薜荔衣，山陟莓苔梯。","一卷冰雪文，避俗常自攜。"]', '["短松鹤不巢，高石云不棲。","君今瀟湘去，意與云鹤齊。","力買奇險地，手开清淺溪。","身披薜荔衣，山陟莓苔梯。","一卷冰雪文，避俗常自携。"]', '诗', 'shi', '', NULL, '送豆盧策歸別墅 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f403902a-a2a0-4547-8ba3-80a85a00be04', '送清遠上人歸楚山舊寺', '送清远上人归楚山旧寺', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["波中出吳境，霞際登楚岑。","山寺一別來，雲蘿三改陰。","詩誇碧雲句，道證青蓮心。","應笑泛萍者，不知松隱深。"]', '["波中出吳境，霞際登楚岑。","山寺一別来，云蘿三改陰。","诗誇碧云句，道證青蓮心。","應笑泛萍者，不知松隐深。"]', '诗', 'shi', '', NULL, '送清遠上人歸楚山舊寺 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d84abcd-8cb0-4a3c-8450-cc42e408523b', '山中送從叔簡', '山中送從叔簡', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["莫以手中瓊，言邀世上名。","莫以山中迹，久向人間行。","松栢有霜操，風泉無俗聲。","應憐枯朽質，驚此別離情。"]', '["莫以手中瓊，言邀世上名。","莫以山中迹，久向人间行。","松栢有霜操，风泉無俗声。","應怜枯朽質，驚此別離情。"]', '诗', 'shi', '', NULL, '山中送從叔簡 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('189a38ce-6ebf-44f1-a12f-f8cbb8e5d34e', '送蕭鍊師入四明山', '送蕭鍊師入四明山', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["閑於獨鶴心，大於高松年。","迥出萬物表，高棲四明巔。","千尋直裂峰，百尺倒瀉泉。","絳雪爲我飯，白雲爲我田。","靜言不語俗，靈蹤時步天。"]', '["闲於独鹤心，大於高松年。","迥出万物表，高棲四明巔。","千尋直裂峰，百尺倒瀉泉。","絳雪爲我飯，白云爲我田。","静言不語俗，靈蹤时步天。"]', '诗', 'shi', '', NULL, '送蕭鍊師入四明山 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45e7589b-be3a-46bf-9399-5347bacfd8fd', '感別送從叔校書簡再登科東歸', '感別送從叔校书簡再登科东归', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["長安車馬道，高槐結浮陰。","下有名利人，一人千萬心。","黃鵠多遠勢，滄溟無近潯。","怡怡靜退姿，泠泠思歸吟。","菱唱忽生聽，芸書迴望深。","清風散言笑，餘花綴衣襟。","獨恨魚鳥別，一飛將一沈。"]', '["长安车马道，高槐結浮陰。","下有名利人，一人千万心。","黄鵠多远勢，滄溟無近潯。","怡怡静退姿，泠泠思归吟。","菱唱忽生听，芸书迴望深。","清风散言笑，餘花綴衣襟。","独恨鱼鸟別，一飞將一沈。"]', '诗', 'shi', '', NULL, '感別送從叔校書簡再登科東歸 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d960fbb2-9162-4ed1-b8e7-7970b7fac129', '送玄亮師', '送玄亮師', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["蘭泉滌我襟，杉月棲我心。","茗啜綠淨花，經誦清柔音。","何處笑爲別，淡情愁不侵。"]', '["蘭泉滌我襟，杉月棲我心。","茗啜綠淨花，經誦清柔音。","何处笑爲別，淡情愁不侵。"]', '诗', 'shi', '', NULL, '送玄亮師 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b75d681-74aa-4fc7-ad3c-8cda5d361266', '送李尊師玄', '送李尊師玄', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["口誦碧簡文，身是青霞君。","頭冠兩片月，肩披一條雲。","松骨輕自飛，鶴心高不羣。"]', '["口誦碧簡文，身是青霞君。","头冠兩片月，肩披一條云。","松骨轻自飞，鹤心高不羣。"]', '诗', 'shi', '', NULL, '送李尊師玄 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05979c1c-21bf-46ea-809e-ad7d6707eeff', '同晝上人送郭秀才江南尋兄弟', '同晝上人送郭秀才江南尋兄弟', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["地上春色生，眼前詩彩明。","手攜片寶月，言是高僧名。","溪轉萬曲心，水流千里聲。","飛鳴向誰去，江鴻弟與兄。"]', '["地上春色生，眼前诗彩明。","手携片寶月，言是高僧名。","溪轉万曲心，水流千里声。","飞鳴向誰去，江鴻弟與兄。"]', '诗', 'shi', '', NULL, '同晝上人送郭秀才江南尋兄弟 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8a116dc-b0f6-47d8-b765-69ce805473a0', '春日同韋郎中使君送鄒儒立少府扶侍赴雲陽', '春日同韋郎中使君送鄒儒立少府扶侍赴云陽', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["離思著百草，綿綿生無窮。","側聞畿甸秀，三振詞策雄。","太守不韻俗，諸生皆變風。","郡齋敞西清，楚瑟驚南鴻。","海畔帝城望，雲陽天色中。","酒酣正芳景，詩綴新碧叢。","服綵老萊並，侍車江革同。","過隋柳顦顇，入洛花蒙籠。","高步詎留足，前程在層空。","獨慙病鶴羽，飛送力難崇。"]', '["離思著百草，綿綿生無窮。","側闻畿甸秀，三振词策雄。","太守不韻俗，諸生皆变风。","郡斋敞西清，楚瑟驚南鴻。","海畔帝城望，云陽天色中。","酒酣正芳景，诗綴新碧叢。","服綵老萊並，侍车江革同。","過隋柳顦顇，入洛花蒙籠。","高步詎留足，前程在層空。","独慙病鹤羽，飞送力难崇。"]', '诗', 'shi', '', NULL, '春日同韋郎中使君送鄒儒立少府扶侍赴雲陽 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed947732-ca9c-4b2b-b96a-6c917796caba', '送從叔校書簡南歸', '送從叔校书簡南归', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["長安別離道，宛在東南隅。","寒草根未死，愁人心已枯。","促促水上景，遙遙天際途。","生隨昏曉中，皆被日月驅。","北騎達山岳，南帆指江湖。","高蹤一超越，千里在須臾。"]', '["长安別離道，宛在东南隅。","寒草根未死，愁人心已枯。","促促水上景，遙遙天際途。","生隨昏晓中，皆被日月驱。","北騎達山岳，南帆指江湖。","高蹤一超越，千里在須臾。"]', '诗', 'shi', '', NULL, '送從叔校書簡南歸 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37972b94-000b-468a-9075-dbf997309066', '送韓愈從軍', '送韓愈從軍', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["志士感恩起，變衣非變性。","親賓改舊觀，僮僕生新敬。","坐作羣書吟，行爲孤劍詠。","始知出處心，不失平生正。","淒淒天地秋，凜凜軍馬令。","驛塵時一飛，物色極四靜。","王師既不戰，廟略在無競。","王粲有所依，元瑜初應命。","一章喻檄明，百萬心氣定。","今朝旌鼓前，笑別丈夫盛。"]', '["志士感恩起，变衣非变性。","親賓改旧观，僮僕生新敬。","坐作羣书吟，行爲孤劍詠。","始知出处心，不失平生正。","淒淒天地秋，凜凜軍马令。","驛塵时一飞，物色極四静。","王師既不戰，廟略在無競。","王粲有所依，元瑜初應命。","一章喻檄明，百万心氣定。","今朝旌鼓前，笑別丈夫盛。"]', '诗', 'shi', '', NULL, '送韓愈從軍 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('310c962f-32b2-4f23-b973-59235cdf6fec', '同茅郎中使君送河南裴文學', '同茅郎中使君送河南裴文学', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["河南有歸客，江風繞行襟。","送君無塵聽，舞鶴清瑟音。","菱蔓綴楚棹，日華正嵩岑。","如何謝文學，還起會雲吟。"]', '["河南有归客，江风繞行襟。","送君無塵听，舞鹤清瑟音。","菱蔓綴楚棹，日华正嵩岑。","如何謝文学，還起會云吟。"]', '诗', 'shi', '', NULL, '同茅郎中使君送河南裴文學 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8399a509-3f09-4027-a389-f5c4ba9e5dfe', '送李翺習之', '送李翺習之', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["習之勢翩翩，東南去遙遙。","贈君雙履足，一爲上臯橋。","臯橋路逶迤，碧水清風飄。","新秋折藕花，應對吳語嬌。","千巷分淥波，四門生早潮。","湖榜輕褭褭，酒旗高寥寥。","小時屐齒痕，有處應未銷。","舊憶如霧星，怳見於夢消。","言之燒人心，事去不可招。","獨孤宅前曲，箜篌醉中謠。","壯年俱悠悠，逮茲各焦焦。","執手復執手，唯道無枯凋。"]', '["習之勢翩翩，东南去遙遙。","贈君雙履足，一爲上臯橋。","臯橋路逶迤，碧水清风飄。","新秋折藕花，應对吳語嬌。","千巷分淥波，四门生早潮。","湖榜轻褭褭，酒旗高寥寥。","小时屐齒痕，有处應未銷。","旧憶如霧星，怳见於梦消。","言之燒人心，事去不可招。","独孤宅前曲，箜篌醉中謠。","壯年俱悠悠，逮茲各焦焦。","執手复執手，唯道無枯凋。"]', '诗', 'shi', '', NULL, '送李翺習之 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18893e95-e3ef-4d84-a099-6a797a91df59', '送丹霞子阮芳顏上人歸山', '送丹霞子阮芳顏上人归山', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["松色不肯秋，玉性不可柔。","登山須正路，飲水須直流。","倩鶴附書信，索雲作衣裘。","仙村莫道遠，枉策招交游。"]', '["松色不肯秋，玉性不可柔。","登山須正路，饮水須直流。","倩鹤附书信，索云作衣裘。","仙村莫道远，枉策招交游。"]', '诗', 'shi', '', NULL, '送丹霞子阮芳顏上人歸山 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57bf2a58-a86f-4365-8a37-2028e89e7a43', '送從舅端適楚地', '送從舅端適楚地', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["歸情似泛空，飄蕩楚波中。","羽扇掃輕汗，布帆篩細風。","江花折菡萏，岸影泊梧桐。","元舅唱離別，賤生愁不窮。"]', '["归情似泛空，飄蕩楚波中。","羽扇掃轻汗，布帆篩細风。","江花折菡萏，岸影泊梧桐。","元舅唱離別，賤生愁不窮。"]', '诗', 'shi', '', NULL, '送從舅端適楚地 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc767945-04bd-42e2-ba0d-01d4b64ab5fb', '送盧汀侍御歸天德幕', '送盧汀侍御归天德幕', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["仲宣領騎射，結束皆少年。","匹馬黃河岸，射鵰清霜天。","旌旗防日北，道路上雲巔。","古雪無銷鑠，新冰有堆填。","清溪徒聳誚，白璧自招賢。","豈比重恩者，閉門方獨全。"]', '["仲宣領騎射，結束皆少年。","匹马黄河岸，射鵰清霜天。","旌旗防日北，道路上云巔。","古雪無銷鑠，新冰有堆填。","清溪徒聳誚，白璧自招賢。","豈比重恩者，閉门方独全。"]', '诗', 'shi', '', NULL, '送盧汀侍御歸天德幕 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c49fefcb-a297-4850-a778-267e6f583e6b', '送草書獻上人歸廬山', '送草书獻上人归廬山', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["狂僧不爲酒，狂筆自通天。","將書雲霞片，直至清明巔。","手中飛黑電，象外瀉玄泉。","萬物隨指顧，三光爲迴旋。","聚書雲霮䨴，洗硯山晴鮮。","忽怒畫虵虺，噴然生風煙。","江人願停筆，驚浪恐傾船。"]', '["狂僧不爲酒，狂笔自通天。","將书云霞片，直至清明巔。","手中飞黑電，象外瀉玄泉。","万物隨指顧，三光爲迴旋。","聚书云霮䨴，洗硯山晴鲜。","忽怒畫虵虺，噴然生风煙。","江人願停笔，驚浪恐傾船。"]', '诗', 'shi', '', NULL, '送草書獻上人歸廬山 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('621cacb3-1e6d-4ad5-af43-f7dba7502681', '和薛先輩送獨孤秀才上都赴嘉會得青字', '和薛先輩送独孤秀才上都赴嘉會得青字', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["秦雲攀窈窕，楚桂搴芳馨。","五色豈徒爾，萬枝皆有靈。","仙謠天上貴，林詠雪中青。","持此一爲贈，送君翔杳冥。"]', '["秦云攀窈窕，楚桂搴芳馨。","五色豈徒爾，万枝皆有靈。","仙謠天上貴，林詠雪中青。","持此一爲贈，送君翔杳冥。"]', '诗', 'shi', '', NULL, '和薛先輩送獨孤秀才上都赴嘉會得青字 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cad5b8e8-da6b-43a0-ae0d-c402495943c4', '送崔爽之湖南', '送崔爽之湖南', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["江與湖相通，二水洗高空。","定知一日帆，使得千里風。","雪唱與誰和，俗情多不通。","何當逸翮縱，飛起泥沙中。"]', '["江與湖相通，二水洗高空。","定知一日帆，使得千里风。","雪唱與誰和，俗情多不通。","何當逸翮縱，飞起泥沙中。"]', '诗', 'shi', '', NULL, '送崔爽之湖南 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3d3999c-8bf8-48e3-9014-7fca647e2f8f', '送超上人歸天台', '送超上人归天台', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["天台山最高，動躡赤城霞。","何以靜雙目，掃山除妄花。","何以潔其性，濾泉去泥沙。","靈境物皆直，萬松無一斜。","月中見心近，雲外將俗賒。","山獸護方丈，山猿捧袈裟。","遺身獨得身，笑我牽名華。"]', '["天台山最高，动躡赤城霞。","何以静雙目，掃山除妄花。","何以潔其性，濾泉去泥沙。","靈境物皆直，万松無一斜。","月中见心近，云外將俗賒。","山獸護方丈，山猿捧袈裟。","遺身独得身，笑我牽名华。"]', '诗', 'shi', '', NULL, '送超上人歸天台 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b221fc00-ff01-48a4-8a62-a0e5f07ddba9', '同李益崔放送王鍊師還樓觀兼爲羣公先營山居', '同李益崔放送王鍊師還楼观兼爲羣公先營山居', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["十年白雲士，一卷紫芝書。","來結崆峒侶，還期縹緲居。","霞冠遺彩翠，月帔上空虛。","寄謝泉根水，清泠閑有餘。"]', '["十年白云士，一卷紫芝书。","来結崆峒侶，還期縹緲居。","霞冠遺彩翠，月帔上空虛。","寄謝泉根水，清泠闲有餘。"]', '诗', 'shi', '', NULL, '同李益崔放送王鍊師還樓觀兼爲羣公先營山居 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82b7ccd3-cab7-479b-8308-b990601db6b7', '張徐州席送岑秀才', '張徐州席送岑秀才', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["振振芝蘭步，升自君子堂。","泠泠松桂吟，生自楚客腸。","羇鳥無定棲，驚蓬在他鄉。","去茲門館閑，即彼道路長。","雨餘山川淨，麥熟草木涼。","楚淚滴章句，京塵染衣裳。","贈君無餘佗，久要不可忘。"]', '["振振芝蘭步，升自君子堂。","泠泠松桂吟，生自楚客腸。","羇鸟無定棲，驚蓬在他乡。","去茲门館闲，即彼道路长。","雨餘山川淨，麦熟草木涼。","楚泪滴章句，京塵染衣裳。","贈君無餘佗，久要不可忘。"]', '诗', 'shi', '', NULL, '張徐州席送岑秀才 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46adb3aa-63a6-4481-b0f9-842f35cb1edb', '送黃構擢第後歸江南', '送黄構擢第後归江南', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["澹澹滄海氣，結成黃香才。","幼齡思奮飛，弱冠遊靈臺。","一鶚顧喬木，衆禽不敢猜。","一驥騁長衢，衆獸不敢陪。","遂得會風雨，感通如雲雷。","至矣小宗伯，確乎心不回。","能令幽靜人，聲實喧九垓。","却憶江南道，祖筵花裏開。","春風不能別，別罷空徘徊。"]', '["澹澹滄海氣，結成黄香才。","幼齡思奮飞，弱冠游靈台。","一鶚顧喬木，衆禽不敢猜。","一驥騁长衢，衆獸不敢陪。","遂得會风雨，感通如云雷。","至矣小宗伯，確乎心不回。","能令幽静人，声實喧九垓。","却憶江南道，祖筵花裏开。","春风不能別，別罷空徘徊。"]', '诗', 'shi', '', NULL, '送黃構擢第後歸江南 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17cf9768-34e4-4556-ba50-990284295cd8', '送道士', '送道士', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["千年山上行，山上無遺蹤。","一日人間游，六合人皆逢。","自有意中侶，白寒徒相從。"]', '["千年山上行，山上無遺蹤。","一日人间游，六合人皆逢。","自有意中侶，白寒徒相從。"]', '诗', 'shi', '', NULL, '送道士 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5149be2-c4a5-481a-a7fe-45cf35f6986a', '送孟寂赴舉', '送孟寂赴舉', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["烈士不憂身，爲君吟苦辛。","男兒久失意，寶劍亦生塵。","浮俗官是貴，君子道所珍。","況當聖明主，豈乏證玉臣。","濁水無白日，清流鑒蒼旻。","賢愚皎然別，結交當有因。"]', '["烈士不憂身，爲君吟苦辛。","男兒久失意，寶劍亦生塵。","浮俗官是貴，君子道所珍。","況當聖明主，豈乏證玉臣。","濁水無白日，清流鑒蒼旻。","賢愚皎然別，結交當有因。"]', '诗', 'shi', '', NULL, '送孟寂赴舉 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4059c1d-f2c1-435f-89b1-f002888bc682', '同溧陽宰送孫秀才', '同溧陽宰送孫秀才', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["廢瑟難爲弦，南風難爲歌。","幽幽拙疾中，忽忽浮夢多。","清韻始嘯侶，雅言相與和。","訟閑每往招，祖送奈若何。","牽苦強爲贈，邦邑光峨峨。"]', '["廢瑟难爲弦，南风难爲歌。","幽幽拙疾中，忽忽浮梦多。","清韻始嘯侶，雅言相與和。","訟闲每往招，祖送奈若何。","牽苦強爲贈，邦邑光峨峨。"]', '诗', 'shi', '', NULL, '同溧陽宰送孫秀才 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cbe556f-8306-4645-88eb-361b09a7d979', '溧陽唐興寺觀薔薇花同諸公餞陳明府', '溧陽唐兴寺观薔薇花同諸公餞陳明府', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["忽驚紅琉璃，千豔萬豔開。","佛火不燒物，淨香空徘徊。","花下印文字，林間詠觴杯。","羣官餞宰官，此地車馬來。"]', '["忽驚紅琉璃，千豔万豔开。","佛火不燒物，淨香空徘徊。","花下印文字，林间詠觴杯。","羣官餞宰官，此地车马来。"]', '诗', 'shi', '', NULL, '溧陽唐興寺觀薔薇花同諸公餞陳明府 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baff4e4c-909c-4e66-a2ea-fd3e22ca827c', '送柳淳', '送柳淳', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["青山臨黃河，下有長安道。","世上名利人，相逢不知老。"]', '["青山臨黄河，下有长安道。","世上名利人，相逢不知老。"]', '诗', 'shi', '', NULL, '送柳淳 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f655033f-c2a8-4698-928e-1fbfada5043e', '送殷秀才南遊', '送殷秀才南游', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["詩句臨離袂，酒花薰別顏。","水程千里外，岸泊幾宵間。","風葉亂辭木，雪猿清叫山。","南中多古事，詠遍始應還。"]', '["诗句臨離袂，酒花薰別顏。","水程千里外，岸泊幾宵间。","风葉亂辞木，雪猿清叫山。","南中多古事，詠遍始應還。"]', '诗', 'shi', '', NULL, '送殷秀才南遊 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6396f1dc-ee8a-4de1-a0b6-27790160e4ad', '送青陽上人遊越', '送青陽上人游越', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["秋風吹白髮，微官自蕭索。","江僧何用歎，溪縣饒寂寞。","楚思物皆清，越山勝非薄。","時看鏡中月，獨向衣上落。","多謝入冥鴻，笑予在籠鶴。"]', '["秋风吹白髮，微官自蕭索。","江僧何用歎，溪縣饒寂寞。","楚思物皆清，越山勝非薄。","时看镜中月，独向衣上落。","多謝入冥鴻，笑予在籠鹤。"]', '诗', 'shi', '', NULL, '送青陽上人遊越 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('125c7c19-81d4-49af-9ea9-46464546e7ba', '奉同朝賢送新羅使', '奉同朝賢送新羅使', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["淼淼望遠國，一萍秋海中。","恩傳日月外，夢在波濤東。","浪興豁胸臆，泛程舟虛空。","既茲吟仗信，亦以難私躬。","實怪賞不足，異鮮悅多叢。","安危所繫重，征役誰能窮。","彼俗媚文史，聖朝富才雄。","送行數百首，各以鏗奇工。","宂隸竊抽韻，孤屬思將同。"]', '["淼淼望远国，一萍秋海中。","恩傳日月外，梦在波濤东。","浪兴豁胸臆，泛程舟虛空。","既茲吟仗信，亦以难私躬。","實怪賞不足，異鲜悅多叢。","安危所繫重，征役誰能窮。","彼俗媚文史，聖朝富才雄。","送行數百首，各以鏗奇工。","宂隸竊抽韻，孤屬思將同。"]', '诗', 'shi', '', NULL, '奉同朝賢送新羅使 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0997f50b-783b-4efc-a4ec-f2b949a06808', '留弟郢不得送之江南', '留弟郢不得送之江南', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["剛有下水船，白日留不得。","老人獨自歸，苦淚滿眼黑。"]', '["剛有下水船，白日留不得。","老人独自归，苦泪满眼黑。"]', '诗', 'shi', '', NULL, '留弟郢不得送之江南 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd692f85-49ad-4f35-a8f2-a7977ab14dc1', '送陸暢歸湖州因憑題故人皎然塔陸羽墳', '送陸暢归湖州因憑題故人皎然塔陸羽墳', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["淼淼霅寺前，白蘋多清風。","昔游詩會滿，今游詩會空。","孤吟玉淒惻，遠思景蒙籠。","杼山塼塔禪，竟陵廣宵翁。","饒彼草木聲，髣髴聞餘聰。","因君寄數句，遍爲書其藂。","追吟當時說，來者實不窮。","江調難再得，京塵徒滿躬。","送君溪鴛鴦，彩色雙飛東。","東多高靜鄉，芳宅冬亦崇。","手自擷甘旨，供養歡沖融。","待我遂前心，收拾使有終。","不然洛岸亭，歸死爲大同。"]', '["淼淼霅寺前，白蘋多清风。","昔游诗會满，今游诗會空。","孤吟玉淒惻，远思景蒙籠。","杼山塼塔禪，竟陵廣宵翁。","饒彼草木声，髣髴闻餘聰。","因君寄數句，遍爲书其藂。","追吟當时说，来者實不窮。","江調难再得，京塵徒满躬。","送君溪鴛鴦，彩色雙飞东。","东多高静乡，芳宅冬亦崇。","手自擷甘旨，供養歡沖融。","待我遂前心，收拾使有終。","不然洛岸亭，归死爲大同。"]', '诗', 'shi', '', NULL, '送陸暢歸湖州因憑題故人皎然塔陸羽墳 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0582cfee-1ad6-484c-8ceb-e9e33d21b4ec', '送淡公 一', '送淡公 一', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["燕本冰雪骨，越淡蓮花風。","五言雙寶刀，聯響高飛鴻。","翰苑錢舍人，詩韻鏗雷公。","識本未識淡，仰詠嗟無窮。","清恨生物表，朗玉傾夢中。","常於冷竹坐，相語道意沖。","嵩洛興不薄，稽江事難同。","明年若不來，我作黃蒿翁。","何以兀其心爲君學虛空。"]', '["燕本冰雪骨，越淡蓮花风。","五言雙寶刀，聯响高飞鴻。","翰苑錢舍人，诗韻鏗雷公。","識本未識淡，仰詠嗟無窮。","清恨生物表，朗玉傾梦中。","常於冷竹坐，相語道意沖。","嵩洛兴不薄，稽江事难同。","明年若不来，我作黄蒿翁。","何以兀其心爲君学虛空。"]', '诗', 'shi', '', NULL, '送淡公 一 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36d5b37a-fcc1-4f31-9234-0ff7fba0036b', '送淡公 二', '送淡公 二', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["坐愛青草上，意含滄海濱。","渺渺獨見水，悠悠不問人。","鏡浪洗手綠，剡花入心春。","雖然防外觸，無奈饒衣新。","行當譯文字，慰此吟殷勤。"]', '["坐愛青草上，意含滄海濱。","渺渺独见水，悠悠不问人。","镜浪洗手綠，剡花入心春。","雖然防外觸，無奈饒衣新。","行當譯文字，慰此吟殷勤。"]', '诗', 'shi', '', NULL, '送淡公 二 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b187c5fa-984c-4de9-ac1b-101ca446dbd9', '送淡公 三', '送淡公 三', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["銅斗飲江酒，手拍銅斗歌。","儂是拍浪兒，飲則拜浪婆。","脚踏小船頭，獨速舞短蓑。","笑伊漁陽操，空恃文章多。","閑倚青竹竿，白日奈我何。"]', '["銅斗饮江酒，手拍銅斗歌。","儂是拍浪兒，饮則拜浪婆。","脚踏小船头，独速舞短蓑。","笑伊漁陽操，空恃文章多。","闲倚青竹竿，白日奈我何。"]', '诗', 'shi', '', NULL, '送淡公 三 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b288ca67-9ebe-4b4d-98dd-42bd8a7661a9', '送淡公 四', '送淡公 四', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["短蓑不怕雨，白鷺相爭飛。","短楫畫菰蒲，鬬作豪橫歸。","笑伊水健兒，浪戰求光輝。","不如竹枝弓，射鴨無是非。"]', '["短蓑不怕雨，白鷺相爭飞。","短楫畫菰蒲，鬬作豪橫归。","笑伊水健兒，浪戰求光輝。","不如竹枝弓，射鴨無是非。"]', '诗', 'shi', '', NULL, '送淡公 四 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc7ce201-5142-4de2-8f8b-cb9931e3c7eb', '送淡公 五', '送淡公 五', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["射鴨復射鴨，鴨驚菰蒲頭。","鴛鴦亦零落，彩色難相求。","儂是清浪兒，每踏清浪游。","笑伊鄉貢郎，踏土稱風流。","如何丱角翁，至死不裹頭。"]', '["射鴨复射鴨，鴨驚菰蒲头。","鴛鴦亦零落，彩色难相求。","儂是清浪兒，每踏清浪游。","笑伊乡貢郎，踏土稱风流。","如何丱角翁，至死不裹头。"]', '诗', 'shi', '', NULL, '送淡公 五 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b750cdf2-57bc-4261-a573-dc315ba11cee', '送淡公 六', '送淡公 六', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["師得天文章，所以相知懷。","數年伊雒同，一旦江湖乖。","江湖有故莊，小女啼喈喈。","我憂未相識，乳養難和諧。","幸以片佛衣，誘之令看齋。","齋中百福言，催促西歸來。"]', '["師得天文章，所以相知懷。","數年伊雒同，一旦江湖乖。","江湖有故莊，小女啼喈喈。","我憂未相識，乳養难和諧。","幸以片佛衣，誘之令看斋。","斋中百福言，催促西归来。"]', '诗', 'shi', '', NULL, '送淡公 六 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f3d0a17-9e7d-448b-8be2-a68e77f01b7c', '送淡公 七', '送淡公 七', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["伊洛氣味薄，江湖文章多。","坐緣江湖岸，意識鮮明波。","銅斗短蓑行，新章其奈何。","茲焉激切句，非是等閑歌。","製之附驛迴，勿使餘風訛。","都城第一寺，昭成屹嵯峨。","爲師書廣壁，仰詠時經過。","徘徊相思心，老淚雙滂沱。"]', '["伊洛氣味薄，江湖文章多。","坐緣江湖岸，意識鲜明波。","銅斗短蓑行，新章其奈何。","茲焉激切句，非是等闲歌。","製之附驛迴，勿使餘风訛。","都城第一寺，昭成屹嵯峨。","爲師书廣壁，仰詠时經過。","徘徊相思心，老泪雙滂沱。"]', '诗', 'shi', '', NULL, '送淡公 七 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db947156-32bf-406f-8c75-bb649de3ddd1', '送淡公 八', '送淡公 八', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["江南邑中寺，平地生勝山。","開元吳語僧，律韻高且閑。","妙藥溪岸平，桂榜往復還。","樹石相鬬生，紅綠各異顏。","風味我遙憶，新奇師獨攀。"]', '["江南邑中寺，平地生勝山。","开元吳語僧，律韻高且闲。","妙藥溪岸平，桂榜往复還。","樹石相鬬生，紅綠各異顏。","风味我遙憶，新奇師独攀。"]', '诗', 'shi', '', NULL, '送淡公 八 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b7aa17e-5f9f-428e-adc6-b8f4c8643ab6', '送淡公 九', '送淡公 九', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["報恩兼報德，寺與山爭鮮。","橙橘金蓋檻，竹蕉綠凝禪。","經章音韻細，風磬清泠翩。","離腸繞師足，舊憶隨路延。","不知幾千尺，至死方綿綿。"]', '["報恩兼報德，寺與山爭鲜。","橙橘金蓋檻，竹蕉綠凝禪。","經章音韻細，风磬清泠翩。","離腸繞師足，旧憶隨路延。","不知幾千尺，至死方綿綿。"]', '诗', 'shi', '', NULL, '送淡公 九 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1de9b856-9107-4c02-a7f2-529a838032b2', '送淡公 十', '送淡公 十', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["鄉在越鏡中，分明見歸心。","鏡芳步步綠，鏡水日日深。","異剎碧天上，古香清桂岑。","朗約徒在昔，章句忽盈今。","幸因西飛葉，書作東風吟。","落我病枕上，慰此浮恨侵。"]', '["乡在越镜中，分明见归心。","镜芳步步綠，镜水日日深。","異剎碧天上，古香清桂岑。","朗約徒在昔，章句忽盈今。","幸因西飞葉，书作东风吟。","落我病枕上，慰此浮恨侵。"]', '诗', 'shi', '', NULL, '送淡公 十 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5da13b9-e54d-4b4f-a1e7-cb1723cd2edf', '送淡公 十一', '送淡公 十一', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["牽師袈裟別，師斷袈裟歸。","問師何苦去，感吃言語稀。","意恐被詩餓，欲住將底依。","盧殷劉言史，餓死君已噫。","不忍見別君，哭君他是非。"]', '["牽師袈裟別，師斷袈裟归。","问師何苦去，感吃言語稀。","意恐被诗餓，欲住將底依。","盧殷劉言史，餓死君已噫。","不忍见別君，哭君他是非。"]', '诗', 'shi', '', NULL, '送淡公 十一 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8c98c12-b0a8-40e5-ba7f-df92345024d5', '送淡公 十二', '送淡公 十二', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["詩人苦爲詩，不如脫空飛。","一生空鷕氣，非諫復非譏。","脫枯挂寒枝，棄如一唾微。","一步一步乞，半片半片衣。","倚詩爲活計，從古多無肥。","詩饑老不怨，勞師淚霏霏。"]', '["诗人苦爲诗，不如脫空飞。","一生空鷕氣，非諫复非譏。","脫枯挂寒枝，棄如一唾微。","一步一步乞，半片半片衣。","倚诗爲活計，從古多無肥。","诗饑老不怨，勞師泪霏霏。"]', '诗', 'shi', '', NULL, '送淡公 十二 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac0730d6-7a27-4321-83bd-f10fb7eda52c', '送魏端公入朝', '送魏端公入朝', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["東洛尚淹翫，西京足芳妍。","大賓威儀肅，上客冠劒鮮。","豈惟空戀闕，亦以將朝天。","局促塵末吏，幽老病中弦。","徒懷青雲價，忽至白髮年。","何當補風教，爲薦三百篇。"]', '["东洛尚淹翫，西京足芳妍。","大賓威儀肅，上客冠劒鲜。","豈惟空戀闕，亦以將朝天。","局促塵末吏，幽老病中弦。","徒懷青云價，忽至白髮年。","何當補风教，爲薦三百篇。"]', '诗', 'shi', '', NULL, '送魏端公入朝 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c24e27a-86a3-4556-be9f-06d67d646501', '送盧郎中汀', '送盧郎中汀', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["洛水春渡闊，別離心悠悠。","一生空吟詩，不覺成白頭。","向事每計較，與山實綢繆。","太華天上開，其下車轍流。","縣街無塵土，過客多淹留。","坐飲孤驛酒，行思獨山遊。","逸關嵐氣明，照渭空漪浮。","玉珂擺新歡，聲與鸞鳳儔。","朝謁大家事，唯余去無由。"]', '["洛水春渡闊，別離心悠悠。","一生空吟诗，不覺成白头。","向事每計較，與山實綢繆。","太华天上开，其下车轍流。","縣街無塵土，過客多淹留。","坐饮孤驛酒，行思独山游。","逸关嵐氣明，照渭空漪浮。","玉珂擺新歡，声與鸾鳳儔。","朝謁大家事，唯余去無由。"]', '诗', 'shi', '', NULL, '送盧郎中汀 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ca3f4cf-327b-4bd2-80d9-799436f906fb', '送鄭僕射出節山南', '送鄭僕射出節山南', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["國老出爲將，紅旗入青山。","再招門下生，結束餘病孱。","自笑騎馬醜，強從驅馳間。","顧顧磨天路，褭褭鏡下顏。","文魄既飛越，宦情唯等閑。","羨他白面少，多是清朝班。","惜命非所報，慎行誠獨艱。","悠悠去住心，兩說何能刪。"]', '["国老出爲將，紅旗入青山。","再招门下生，結束餘病孱。","自笑騎马醜，強從驱驰间。","顧顧磨天路，褭褭镜下顏。","文魄既飞越，宦情唯等闲。","羨他白面少，多是清朝班。","惜命非所報，慎行誠独艱。","悠悠去住心，兩说何能刪。"]', '诗', 'shi', '', NULL, '送鄭僕射出節山南 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1af8b69-d249-451a-9635-cddfc113929b', '別妻家', '別妻家', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["芙蓉濕曉露，秋別南浦中。","鴛鴦卷新贈，遙戀東牀空。","碧水不息浪，清溪易生風。","參差坐成阻，飄颻去無窮。","孤雲目雖斷，明月心相通。","私情詎銷鑠，積芳在春藂。"]', '["芙蓉濕晓露，秋別南浦中。","鴛鴦卷新贈，遙戀东牀空。","碧水不息浪，清溪易生风。","參差坐成阻，飄颻去無窮。","孤云目雖斷，明月心相通。","私情詎銷鑠，積芳在春藂。"]', '诗', 'shi', '', NULL, '別妻家 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afc850df-124d-4fe7-97c1-b141eeee219c', '贈姚怤別', '贈姚怤別', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["美人廢琴瑟，不是無巧彈。","聞君郢中唱，始覺知音難。","驚蓬無還根，馳水多分瀾。","倦客厭出門，疲馬思解鞍。","何以寫此心，贈君握中丹。"]', '["美人廢琴瑟，不是無巧彈。","闻君郢中唱，始覺知音难。","驚蓬無還根，驰水多分瀾。","倦客厭出门，疲马思解鞍。","何以寫此心，贈君握中丹。"]', '诗', 'shi', '', NULL, '贈姚怤別 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9620d374-59b6-46ea-b49b-1984fd2bf41c', '贈竟陵盧使君虔別', '贈竟陵盧使君虔別', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["赤日千里火，火中行子心。","孰不苦焦灼，所行爲貧侵。","山木豈無涼，猛獸蹲清陰。","歸人憶平坦，別路多嶇嶔。","賴得竟陵守，時聞建安吟。","贈別折楚芳，楚芳搖衣襟。"]', '["赤日千里火，火中行子心。","孰不苦焦灼，所行爲貧侵。","山木豈無涼，猛獸蹲清陰。","归人憶平坦，別路多嶇嶔。","賴得竟陵守，时闻建安吟。","贈別折楚芳，楚芳搖衣襟。"]', '诗', 'shi', '', NULL, '贈竟陵盧使君虔別 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c52da8e-5d6b-48bf-baf3-6d0c5851907e', '與韓愈李翺張籍話別', '與韓愈李翺張籍話別', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["朱弦奏離別，華燈少光輝。","物色豈有異，人心顧將違。","客程殊未已，歲華忽然微。","秋桐故葉下，寒露新雁飛。","遠遊起重恨，送人念先歸。","夜集類飢鳥，晨光失相依。","馬跡遶川水，雁書還閨闈。","常恐親朋阻，獨行知慮非。"]', '["朱弦奏離別，华灯少光輝。","物色豈有異，人心顧將違。","客程殊未已，歲华忽然微。","秋桐故葉下，寒露新雁飞。","远游起重恨，送人念先归。","夜集類飢鸟，晨光失相依。","马跡遶川水，雁书還閨闈。","常恐親朋阻，独行知慮非。"]', '诗', 'shi', '', NULL, '與韓愈李翺張籍話別 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a30db985-c13a-40e8-b1f6-da88559f78aa', '監察十五叔東齋招李益端公會別', '監察十五叔东斋招李益端公會別', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["欲知惜別情，瀉水還清池。","此地有君子，芳蘭步葳蕤。","手掇雜英珮，意搖春夜思。","莫作遶山雲，循環無定期。"]', '["欲知惜別情，瀉水還清池。","此地有君子，芳蘭步葳蕤。","手掇杂英珮，意搖春夜思。","莫作遶山云，循环無定期。"]', '诗', 'shi', '', NULL, '監察十五叔東齋招李益端公會別 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e87073d6-8089-481f-bc0b-32dde82eb4f8', '汴州留別韓愈', '汴州留別韓愈', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["不飲濁水瀾，空滯此汴河。","坐見遶岸水，盡爲還海波。","四時不在家，弊服斷線多。","遠客獨顦顇，春英落婆娑。","汴水饒曲流，野桑無直柯。","但爲君子心，歎息終靡他。"]', '["不饮濁水瀾，空滯此汴河。","坐见遶岸水，尽爲還海波。","四时不在家，弊服斷線多。","远客独顦顇，春英落婆娑。","汴水饒曲流，野桑無直柯。","但爲君子心，歎息終靡他。"]', '诗', 'shi', '', NULL, '汴州留別韓愈 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a64e0de-e550-498b-af8c-5cd631190b69', '贈別殷山人說易後歸幽墅', '贈別殷山人说易後归幽墅', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["夫子說天地，若與靈龜言。","幽幽人不知，一一予所敦。","秋月吐白夜，涼風韻清源。","旁通忽已遠，神感寂不喧。","一悟祛萬結，夕懷傾朝煩。","旅輈無停波，別馬嘶去轅。","殷勤荒草士，會有知己論。"]', '["夫子说天地，若與靈龟言。","幽幽人不知，一一予所敦。","秋月吐白夜，涼风韻清源。","旁通忽已远，神感寂不喧。","一悟祛万結，夕懷傾朝煩。","旅輈無停波，別马嘶去轅。","殷勤荒草士，會有知己論。"]', '诗', 'shi', '', NULL, '贈別殷山人說易後歸幽墅 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d99384d0-666c-44c7-b87f-775e35a606e4', '壽安西渡奉別鄭相公 一', '壽安西渡奉別鄭相公 一', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["洛河向西道，石波橫磷磷。","清風送君子，車遠無還塵。","春別亦蕭索，況茲冰霜晨。","零落景易入，鬱抑抱難申。","百宵華燈宴，一旦星散人。","歲去弦吐箭，憂來蠶抽綸。","綿綿無窮事，各各馳遶身。","徘徊黃縹緲，倏忽春霜賓。","相爲物表物，永謝區中姻。","日嗟來教士，仰望無由親。"]', '["洛河向西道，石波橫磷磷。","清风送君子，车远無還塵。","春別亦蕭索，況茲冰霜晨。","零落景易入，鬱抑抱难申。","百宵华灯宴，一旦星散人。","歲去弦吐箭，憂来蠶抽綸。","綿綿無窮事，各各驰遶身。","徘徊黄縹緲，倏忽春霜賓。","相爲物表物，永謝區中姻。","日嗟来教士，仰望無由親。"]', '诗', 'shi', '', NULL, '壽安西渡奉別鄭相公 一 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fda6f87b-62dd-4806-ad1e-857856352d36', '壽安西渡奉別鄭相公 二', '壽安西渡奉別鄭相公 二', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["東都清風減，君子西歸朝。","獨抱歲晏恨，泗吟不成謠。","貴遊意多味，賤別情易消。","迴鴈憶前叫，浪鳧念後漂。","悠悠孤飛景，聳聳銜霜條。","昧趣多滯澀，嬾朋寡新僚。","病深理方悟，悔至心自燒。","寂靜道何在，憂勤學空饒。","乃知減聞見，始遂情逍遙。","文字徒營織，聲華諒疑驕。","顧慙耕稼士，朴略氣韻調。","善士有餘食，佳畦冬生苗。","養人在養身，此旨清如韶。","願貢高古言，敢望錫類招。"]', '["东都清风減，君子西归朝。","独抱歲晏恨，泗吟不成謠。","貴游意多味，賤別情易消。","迴鴈憶前叫，浪鳧念後漂。","悠悠孤飞景，聳聳銜霜條。","昧趣多滯澀，嬾朋寡新僚。","病深理方悟，悔至心自燒。","寂静道何在，憂勤学空饒。","乃知減闻见，始遂情逍遙。","文字徒營织，声华諒疑驕。","顧慙耕稼士，朴略氣韻調。","善士有餘食，佳畦冬生苗。","養人在養身，此旨清如韶。","願貢高古言，敢望錫類招。"]', '诗', 'shi', '', NULL, '壽安西渡奉別鄭相公 二 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('942d1b0c-771a-46c9-b66a-bf00da520b83', '宇文秀才齋中海柳詠', '宇文秀才斋中海柳詠', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["玉縷青葳蕤，結爲芳樹姿。","忽驚明月鉤，鉤出珊瑚枝。","灼灼不死花，蒙蒙長生絲。","飲栢泛仙味，詠蘭擬古詞。","霜風清颼颼，與君長相思。"]', '["玉縷青葳蕤，結爲芳樹姿。","忽驚明月鉤，鉤出珊瑚枝。","灼灼不死花，蒙蒙长生絲。","饮栢泛仙味，詠蘭擬古词。","霜风清颼颼，與君长相思。"]', '诗', 'shi', '', NULL, '宇文秀才齋中海柳詠 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a00bc423-d9df-47a9-9ac1-cabcaeb5d5bb', '搖柳', '搖柳', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["弱弱本易驚，看看勢難定。","因風似醉舞，盡日不能正。","時邀詠花女，笑輟春妝鏡。"]', '["弱弱本易驚，看看勢难定。","因风似醉舞，尽日不能正。","时邀詠花女，笑輟春妝镜。"]', '诗', 'shi', '', NULL, '搖柳 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d367dabb-1d6d-4392-aa3a-a1d945cad8de', '曉鶴', '晓鹤', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["曉鶴彈古舌，婆羅門叫音。","應吹天上律，不使塵中尋。","虛空夢皆斷，歆唏安能禁。","如開孤月口，似說明星心。","既非人間韻，枉作人間禽。","不如相將去，碧落窠巢深。"]', '["晓鹤彈古舌，婆羅门叫音。","應吹天上律，不使塵中尋。","虛空梦皆斷，歆唏安能禁。","如开孤月口，似说明星心。","既非人间韻，枉作人间禽。","不如相將去，碧落窠巢深。"]', '诗', 'shi', '', NULL, '曉鶴 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e663ebd5-d2ce-4ef7-a278-1abca072f68c', '和薔薇花歌', '和薔薇花歌', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["仙機札札織鳳皇，花開七十有二行。","天霞落地攢紅光，風枝嫋嫋時一颺。","飛散葩馥遶空王，忽驚錦浪洗新色。","又似宮娃逞妝飾，終當一使移花根，還比蒲桃天上植。"]', '["仙機札札织鳳皇，花开七十有二行。","天霞落地攢紅光，风枝嫋嫋时一颺。","飞散葩馥遶空王，忽驚錦浪洗新色。","又似宮娃逞妝飾，終當一使移花根，還比蒲桃天上植。"]', '诗', 'shi', '', NULL, '和薔薇花歌 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbe6ccc7-beb7-4578-8203-4891f37e203b', '邀人賞薔薇', '邀人賞薔薇', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["蜀色庶可比，楚叢亦應無。","醉紅不自力，狂豔如索扶。","麗蘂惜未埽，宛枝長更紆。","何人是花侯，詩老強相呼。"]', '["蜀色庶可比，楚叢亦應無。","醉紅不自力，狂豔如索扶。","丽蘂惜未埽，宛枝长更紆。","何人是花侯，诗老強相呼。"]', '诗', 'shi', '', NULL, '邀人賞薔薇 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2be0d75-9a58-48a4-99d8-c73f3ea0e2ed', '和宣州錢判官使院廳前石楠樹', '和宣州錢判官使院廳前石楠樹', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["大朴既一剖，衆材爭萬殊。","懿茲南海華，來與北壤俱。","生長如自惜，雪霜無凋渝。","籠籠抱靈秀，簇簇抽芳膚。","寒日吐丹豔，頳子流細珠。","鴛鴦花數重，翡翠葉四鋪。","雨洗新妝色，一枝如一姝。","聳異敷庭際，傾妍來坐隅。","散彩飾机案，餘輝盈盤盂。","高意因造化，常情逐榮枯。","主公方寸中，陶植在須臾。","養此奉君子，賞覿日爲娛。","始覺石楠詠，價傾賦兩都。","棠頌庶可比，桂詞難以踰。","因謝丘墟木，空采落泥塗。","時來開佳姿，道去臥枯株。","爭芳無由緣，受氣如鬱紆。","抽肝在郢匠，歎息何踟躕。"]', '["大朴既一剖，衆材爭万殊。","懿茲南海华，来與北壤俱。","生长如自惜，雪霜無凋渝。","籠籠抱靈秀，簇簇抽芳膚。","寒日吐丹豔，頳子流細珠。","鴛鴦花數重，翡翠葉四鋪。","雨洗新妝色，一枝如一姝。","聳異敷庭際，傾妍来坐隅。","散彩飾机案，餘輝盈盤盂。","高意因造化，常情逐榮枯。","主公方寸中，陶植在須臾。","養此奉君子，賞覿日爲娛。","始覺石楠詠，價傾賦兩都。","棠頌庶可比，桂词难以踰。","因謝丘墟木，空采落泥塗。","时来开佳姿，道去臥枯株。","爭芳無由緣，受氣如鬱紆。","抽肝在郢匠，歎息何踟躕。"]', '诗', 'shi', '', NULL, '和宣州錢判官使院廳前石楠樹 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e56dba0-eb4e-4785-9f20-7d5a290cc1c1', '酬鄭毗躑躅詠', '酬鄭毗躑躅詠', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["不似人手致，豈關地勢偏。","孤光褭餘翠，獨影舞多妍。","迸火燒閑地，紅星墮青天。","忽驚物表物，嘉客爲留連。"]', '["不似人手致，豈关地勢偏。","孤光褭餘翠，独影舞多妍。","迸火燒闲地，紅星墮青天。","忽驚物表物，嘉客爲留連。"]', '诗', 'shi', '', NULL, '酬鄭毗躑躅詠 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3b8f1f1-c715-48d9-8b16-31af8a4cb151', '品松', '品松', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["追悲謝靈運，不得殊常封。","縱然孔與顏，亦莫及此松。","此松天格高，聳異千萬重。","抓拏巨靈手，擘裂少室峰。","擘裂風雨獰，抓拏指爪𦟛。","道入難抱心，學生易墮蹤。","時時數點仙，嫋嫋一線龍。","霏微嵐浪際，遊戲顥興濃。","品松徒高高，雌鳴詎噰噰。","賞異尚可貴，賞潛誰能容。","名華非典實，翦棄徒纖茸。","刻削大雅文，所以不敢慵。"]', '["追悲謝靈運，不得殊常封。","縱然孔與顏，亦莫及此松。","此松天格高，聳異千万重。","抓拏巨靈手，擘裂少室峰。","擘裂风雨獰，抓拏指爪𦟛。","道入难抱心，学生易墮蹤。","时时數点仙，嫋嫋一線龙。","霏微嵐浪際，游戲顥兴濃。","品松徒高高，雌鳴詎噰噰。","賞異尚可貴，賞潛誰能容。","名华非典實，翦棄徒纖茸。","刻削大雅文，所以不敢慵。"]', '诗', 'shi', '', NULL, '品松 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71616d4c-bb23-433e-a28e-4c79b44441af', '答李員外小榼味', '答李員外小榼味', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["一拳芙蓉水，傾玉何泠泠。","仙情夙已高，詩味今更馨。","試啜月入骨，再銜愁盡醒。","荷君道古誠，使我善飛翎。"]', '["一拳芙蓉水，傾玉何泠泠。","仙情夙已高，诗味今更馨。","試啜月入骨，再銜愁尽醒。","荷君道古誠，使我善飞翎。"]', '诗', 'shi', '', NULL, '答李員外小榼味 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3216fdc8-9d92-43d6-ad09-7c0f6c46bb45', '井上枸杞架', '井上枸杞架', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["深鎖銀泉甃，高葉架雲空。","不與凡木並，自將仙蓋同。","影疎千點月，聲細萬條風。","迸子鄰溝外，飄香客位中。","花杯承此飲，椿歲小無窮。"]', '["深鎖銀泉甃，高葉架云空。","不與凡木並，自將仙蓋同。","影疎千点月，声細万條风。","迸子鄰溝外，飄香客位中。","花杯承此饮，椿歲小無窮。"]', '诗', 'shi', '', NULL, '井上枸杞架 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a2c04d4-88ec-4029-ac1b-96a2c4d41a42', '蜘蛛諷', '蜘蛛諷', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["萬類皆有性，各各稟天和。","蠶身與汝身，汝身何太訛。","蠶身不爲己，汝身不爲佗。","蠶絲爲衣裳，汝絲爲網羅。","濟物幾無功，害物日已多。","百蟲雖切恨，其將奈爾何。"]', '["万類皆有性，各各稟天和。","蠶身與汝身，汝身何太訛。","蠶身不爲己，汝身不爲佗。","蠶絲爲衣裳，汝絲爲網羅。","濟物幾無功，害物日已多。","百蟲雖切恨，其將奈爾何。"]', '诗', 'shi', '', NULL, '蜘蛛諷 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e938786e-9471-4c27-856a-07df08b4128b', '蚊', '蚊', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["五月中夜息，飢蚊尚營營。","但將膏血求，豈覺性命輕。","顧己寧自愧，飲人以偷生。","願爲天下幮，一使夜景清。"]', '["五月中夜息，飢蚊尚營營。","但將膏血求，豈覺性命轻。","顧己寧自愧，饮人以偷生。","願爲天下幮，一使夜景清。"]', '诗', 'shi', '', NULL, '蚊 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45f7a43e-f6f9-453f-87ab-8d0be976440b', '燭蛾', '燭蛾', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["燈前雙舞蛾，厭生何太切。","想爾飛來心，惡明不惡滅。","天若百尺高，應去掩明月。"]', '["灯前雙舞蛾，厭生何太切。","想爾飞来心，惡明不惡滅。","天若百尺高，應去掩明月。"]', '诗', 'shi', '', NULL, '燭蛾 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2563d416-de47-440e-a4ae-30ffaa438e29', '和錢侍郎甘露', '和錢侍郎甘露', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["玄天何以言，瑞露青松繁。","忽見垂書跡，還驚涌澧源。","春枝晨嫋嫋，香味曉翻翻。","子禮忽來獻，臣心固易敦。","清風惜不動，薄霧肯蒙昏。","嘉晝色更晶，仁慈久乃存。","一方難獨占，天下恐爭論。","側聽飛中使，重榮華德門。","從公樂萬壽，餘慶及兒孫。"]', '["玄天何以言，瑞露青松繁。","忽见垂书跡，還驚涌澧源。","春枝晨嫋嫋，香味晓翻翻。","子禮忽来獻，臣心固易敦。","清风惜不动，薄霧肯蒙昏。","嘉晝色更晶，仁慈久乃存。","一方难独占，天下恐爭論。","側听飞中使，重榮华德门。","從公乐万壽，餘慶及兒孫。"]', '诗', 'shi', '', NULL, '和錢侍郎甘露 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92c87b6b-ce3d-4207-9182-c8b60acae2f6', '和令狐侍郎郭郎中題項羽廟', '和令狐侍郎郭郎中題項羽廟', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["碧草凌古廟，清塵鎖秋窗。","當時獨宰割，猛志誰能降。","鼓氣雷作敵，劒光電爲雙。","新悲徒自起，舊恨空浮江。"]', '["碧草凌古廟，清塵鎖秋窗。","當时独宰割，猛志誰能降。","鼓氣雷作敵，劒光電爲雙。","新悲徒自起，旧恨空浮江。"]', '诗', 'shi', '', NULL, '和令狐侍郎郭郎中題項羽廟 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47f7971f-e137-402d-9450-2b6f366ee035', '讀張碧集', '读張碧集', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["天寶太白歿，六藝已消歇。","大哉國風本，喪而王澤竭。","先生今復生，斯文信難缺。","下筆證興亡，陳詞備風骨。","高秋數奏琴，澄潭一輪月。","誰作采詩官，忍之不揮發。"]', '["天寶太白歿，六藝已消歇。","大哉国风本，喪而王澤竭。","先生今复生，斯文信难缺。","下笔證兴亡，陳词備风骨。","高秋數奏琴，澄潭一輪月。","誰作采诗官，忍之不揮發。"]', '诗', 'shi', '', NULL, '讀張碧集 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3549a7b4-8816-47cc-ada9-a6472ac82265', '聽琴', '听琴', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["颯颯微雨收，翻翻橡葉鳴。","月沈亂峰西，寥落三四星。","前溪忽調琴，隔林寒琤琤。","聞彈正弄聲，不敢枕上聽。","迴燭整頭簪，漱泉立中庭。","定步屐齒深，貌禪目冥冥。","微風吹衣襟，亦認宮徵聲。","學道三十年，未免憂死生。","聞彈一夜中，會盡天地情。"]', '["颯颯微雨收，翻翻橡葉鳴。","月沈亂峰西，寥落三四星。","前溪忽調琴，隔林寒琤琤。","闻彈正弄声，不敢枕上听。","迴燭整头簪，漱泉立中庭。","定步屐齒深，貌禪目冥冥。","微风吹衣襟，亦認宮徵声。","学道三十年，未免憂死生。","闻彈一夜中，會尽天地情。"]', '诗', 'shi', '', NULL, '聽琴 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0682ba7e-6308-42cc-87af-b17e138138cd', '聞夜啼贈劉正元', '闻夜啼贈劉正元', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["寄泣須寄黃河泉，此中怨聲流徹天。","愁人獨有夜燈見，一紙鄉書淚滴穿。"]', '["寄泣須寄黄河泉，此中怨声流徹天。","愁人独有夜灯见，一紙乡书泪滴穿。"]', '诗', 'shi', '', NULL, '聞夜啼贈劉正元 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75292265-6590-4f1b-891b-4cd65dd63024', '喜雨', '喜雨', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["朝見一片雲，暮成千里雨。","淒清濕高枝，散漫沾荒土。"]', '["朝见一片云，暮成千里雨。","淒清濕高枝，散漫沾荒土。"]', '诗', 'shi', '', NULL, '喜雨 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecba6e81-8714-4d86-bb31-62e040169ad9', '終南山下作', '終南山下作', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["見此原野秀，始知造化偏。","山村不假陰，流水自雨田。","家家梯碧峰，門門鎖青煙。","因思蛻骨人，化作飛桂仙。"]', '["见此原野秀，始知造化偏。","山村不假陰，流水自雨田。","家家梯碧峰，门门鎖青煙。","因思蛻骨人，化作飞桂仙。"]', '诗', 'shi', '', NULL, '終南山下作 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52a343e8-cf12-4e7a-ae94-dbb160eb6dc2', '觀種樹', '观種樹', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["種樹皆待春，春至難久留。","君看朝夕花，誰免離別愁。","心意已零落，種之仍未休。","胡爲好奇者，無事自買憂。"]', '["種樹皆待春，春至难久留。","君看朝夕花，誰免離別愁。","心意已零落，種之仍未休。","胡爲好奇者，無事自買憂。"]', '诗', 'shi', '', NULL, '觀種樹 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3d74201-40bc-4b6e-a5b2-dbcfdd1abda4', '春雨後', '春雨後', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["昨夜一霎雨，天意蘇羣物。","何物最先知，虛庭草爭出。"]', '["昨夜一霎雨，天意蘇羣物。","何物最先知，虛庭草爭出。"]', '诗', 'shi', '', NULL, '春雨後 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f910ce3e-e040-4e37-9b99-84f5f7e250d4', '答友人贈炭', '答友人贈炭', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["青山白屋有仁人，贈炭價重雙烏銀。","驅却坐上千重寒，燒出爐中一片春。","吹霞弄日光不定，暖得曲身成直身。"]', '["青山白屋有仁人，贈炭價重雙烏銀。","驱却坐上千重寒，燒出爐中一片春。","吹霞弄日光不定，暖得曲身成直身。"]', '诗', 'shi', '', NULL, '答友人贈炭 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f003b53-2c93-459b-85f9-01f80a427980', '爛柯石', '爛柯石', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["仙界一日內，人間千載窮。","雙碁未徧局，萬物皆爲空。","樵客返歸路，斧柯爛從風。","唯餘石橋在，猶自凌丹虹。"]', '["仙界一日內，人间千載窮。","雙碁未徧局，万物皆爲空。","樵客返归路，斧柯爛從风。","唯餘石橋在，猶自凌丹虹。"]', '诗', 'shi', '', NULL, '爛柯石 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6d1ccc7-7a37-4fec-99d6-a88b10300b25', '尋言上人', '尋言上人', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["萬里莓苔地，不見驅馳蹤。","唯開文字窗，時寫日月容。","竹韻漫蕭屑，草花徒蒙茸。","披霜入衆木，獨自識青松。"]', '["万里莓苔地，不见驱驰蹤。","唯开文字窗，时寫日月容。","竹韻漫蕭屑，草花徒蒙茸。","披霜入衆木，独自識青松。"]', '诗', 'shi', '', NULL, '尋言上人 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7cf6818-7ac0-4e54-abad-3ad2e4a9acf2', '噴玉布', '噴玉布', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["去塵咫尺步，山笑康樂巖。","天開紫石屏，泉縷明月簾。","仙凝刻削跡，靈綻雲霞纖。","悅聞若有待，瞥見終無厭。","俗玩詎能近，道嬉方可淹。","踏着不死機，欲歸多浮嫌。","古醉今忽醒，今求古仍潛。","古今相共失，語默兩難恬。","贈君噴玉布，一濯高嶄嶄。"]', '["去塵咫尺步，山笑康乐巖。","天开紫石屏，泉縷明月簾。","仙凝刻削跡，靈綻云霞纖。","悅闻若有待，瞥见終無厭。","俗玩詎能近，道嬉方可淹。","踏着不死機，欲归多浮嫌。","古醉今忽醒，今求古仍潛。","古今相共失，語默兩难恬。","贈君噴玉布，一濯高嶄嶄。"]', '诗', 'shi', '', NULL, '噴玉布 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2168ed2-e658-4ead-9711-b3f98026e41b', '姑蔑城', '姑蔑城', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["勁越既成土，強吳亦爲墟。","皇風一已被，茲邑信平居。","撫俗觀舊跡，行春布新書。","興亡意何在，綿歎空躊躕。"]', '["勁越既成土，強吳亦爲墟。","皇风一已被，茲邑信平居。","撫俗观旧跡，行春布新书。","兴亡意何在，綿歎空躊躕。"]', '诗', 'shi', '', NULL, '姑蔑城 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3397817-5ef2-43e9-9b0f-cb96e8bab224', '崢嶸嶺', '崢嶸嶺', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["疏鑿順高下，結構橫煙霞。","坐嘯郡齋肅，玩奇石路斜。","古樹浮綠氣，高門結朱華。","始見崢嶸狀，仰止逾可嘉。"]', '["疏鑿順高下，結構橫煙霞。","坐嘯郡斋肅，玩奇石路斜。","古樹浮綠氣，高门結朱华。","始见崢嶸狀，仰止逾可嘉。"]', '诗', 'shi', '', NULL, '崢嶸嶺 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e14f3acb-c22f-42cb-93ec-d2550512ecb7', '尋裴處士', '尋裴处士', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["涉水更登陸，所向皆清真。","寒草不藏徑，靈峰知有人。","悠哉鍊金客，獨與煙霞親。","曾是欲輕舉，誰言空隱淪。","遠心寄白月，華髮迴青春。","對此欽勝事，胡爲勞我身。"]', '["涉水更登陸，所向皆清真。","寒草不藏徑，靈峰知有人。","悠哉鍊金客，独與煙霞親。","曾是欲轻舉，誰言空隐淪。","远心寄白月，华髮迴青春。","对此欽勝事，胡爲勞我身。"]', '诗', 'shi', '', NULL, '尋裴處士 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6062777-a23a-4e6f-8362-843f251c4a0e', '子慶詩', '子慶诗', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["王家事已奇，孟氏慶無涯。","獻子還生子，羲之又有之。","鳳兮且莫歎，鯉也會聞詩。","小小豫章甲，纖纖玉樹姿。","人來唯仰乳，母抱未知慈。","我欲揀其養，放麛者是誰。"]', '["王家事已奇，孟氏慶無涯。","獻子還生子，羲之又有之。","鳳兮且莫歎，鯉也會闻诗。","小小豫章甲，纖纖玉樹姿。","人来唯仰乳，母抱未知慈。","我欲揀其養，放麛者是誰。"]', '诗', 'shi', '', NULL, '子慶詩 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f54b64f-43c0-4016-a7b7-f880af34b8ce', '憩淮上觀公法堂', '憩淮上观公法堂', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["動覺日月短，靜知時歲長。","自悲道路人，暫宿空閑堂。","孤燭讓清晝，紗巾歛輝光。","高僧積素行，事外無剛強。","我有巖下桂，願爲爐中香。","不惜青翠姿，爲君揚芬芳。","淮水色不汙，汴流徒渾黃。","且將琉璃意，淨綴芙蓉章。","明日還獨行，羇愁來舊腸。"]', '["动覺日月短，静知时歲长。","自悲道路人，暫宿空闲堂。","孤燭讓清晝，紗巾歛輝光。","高僧積素行，事外無剛強。","我有巖下桂，願爲爐中香。","不惜青翠姿，爲君揚芬芳。","淮水色不汙，汴流徒渾黄。","且將琉璃意，淨綴芙蓉章。","明日還独行，羇愁来旧腸。"]', '诗', 'shi', '', NULL, '憩淮上觀公法堂 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2c0bb64-7033-421a-8f30-069251c9b9fc', '江邑春霖奉贈陳侍御', '江邑春霖奉贈陳侍御', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["江上花木凍，雨中零落春。","應由放忠直，在此成漂淪。","嘉豔皆損汙，好音難殷勤。","天涯多遠恨，雪涕盈芳辰。","坐哭青草上，臥吟幽水濱。","興言念風俗，得意唯波鱗。","枕席病流濕，簷楹若飛津。","始知吳楚水，不及京洛塵。","風浦蕩歸棹，泥陂陷征輪。","兩途日無遂，相贈唯沾巾。"]', '["江上花木凍，雨中零落春。","應由放忠直，在此成漂淪。","嘉豔皆損汙，好音难殷勤。","天涯多远恨，雪涕盈芳辰。","坐哭青草上，臥吟幽水濱。","兴言念风俗，得意唯波鱗。","枕席病流濕，簷楹若飞津。","始知吳楚水，不及京洛塵。","风浦蕩归棹，泥陂陷征輪。","兩途日無遂，相贈唯沾巾。"]', '诗', 'shi', '', NULL, '江邑春霖奉贈陳侍御 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf4a63aa-cc43-4428-98df-e59ef6392469', '溧陽秋霽', '溧陽秋霽', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["晚雨曉猶在，蕭寥激前階。","星星滿衰鬢，耿耿入秋懷。","舊識半零落，前心驟相乖。","飽泉亦恐醉，惕宦肅如齋。","上客處華池，下寮宅枯崖。","叩高占生物，齟齬回難諧。"]', '["晚雨晓猶在，蕭寥激前階。","星星满衰鬢，耿耿入秋懷。","旧識半零落，前心驟相乖。","飽泉亦恐醉，惕宦肅如斋。","上客处华池，下寮宅枯崖。","叩高占生物，齟齬回难諧。"]', '诗', 'shi', '', NULL, '溧陽秋霽 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5457764e-720b-4ab3-89ae-422fb9687a4a', '列仙文 方諸青童君', '列仙文 方諸青童君', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["大霞霏晨暉，元氣無常形。","玄轡飛霄外，八景乘高清。","手把玉皇袂，攜我晨中生。","玄庭自嘉會，金書拆華名。","賢女密所妍，相期洛水軿。"]', '["大霞霏晨暉，元氣無常形。","玄轡飞霄外，八景乘高清。","手把玉皇袂，携我晨中生。","玄庭自嘉會，金书拆华名。","賢女密所妍，相期洛水軿。"]', '诗', 'shi', '', NULL, '列仙文 方諸青童君 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04dcf756-3aa4-4c24-a727-b262ba1ad46b', '列仙文 清虛真人', '列仙文 清虛真人', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["歘駕空清虛，徘徊西華館。","瓊輪暨晨抄，虎騎逐煙散。","惠風振丹旌，明燭朗八煥。","解襟墉房內，神鈴鳴璀璨。","棲景若林柯，九弦空中彈。","遺我積世憂，釋此千載歎。","怡眄無極已，終夜復待旦。"]', '["歘駕空清虛，徘徊西华館。","瓊輪暨晨抄，虎騎逐煙散。","惠风振丹旌，明燭朗八煥。","解襟墉房內，神鈴鳴璀璨。","棲景若林柯，九弦空中彈。","遺我積世憂，釋此千載歎。","怡眄無極已，終夜复待旦。"]', '诗', 'shi', '', NULL, '列仙文 清虛真人 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4628c2c7-4349-42b8-92ab-e6a1bf0f6e7e', '列仙文 金母飛空歌', '列仙文 金母飞空歌', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["駕我八景輿，歘然入玉清。","龍羣拂霄上，虎旗攝朱兵。","逍遙三弦際，萬流無暫停。","哀此去留會，劫盡天地傾。","當尋無中景，不死亦不生。","體彼自然道，寂觀合大冥。","南嶽挺直幹，玉英曜頴精。","有任靡期事，無心自虛靈。","嘉會絳河內，相與樂未英。"]', '["駕我八景輿，歘然入玉清。","龙羣拂霄上，虎旗攝朱兵。","逍遙三弦際，万流無暫停。","哀此去留會，劫尽天地傾。","當尋無中景，不死亦不生。","體彼自然道，寂观合大冥。","南嶽挺直幹，玉英曜頴精。","有任靡期事，無心自虛靈。","嘉會絳河內，相與乐未英。"]', '诗', 'shi', '', NULL, '列仙文 金母飛空歌 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5bb5bbd-2637-48e7-bc03-c0a9766be04f', '列仙文 安度明', '列仙文 安度明', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["丹霞煥上清，八風鼓太和。","迴我神霄輦，遂造嶺玉阿。","咄嗟天地外，九圍皆我家。","上采白日精，下飲黃月華。","靈觀空無中，鵬路無間邪。","顧見魏賢安，濁氣傷汝和。","勤研玄中思，道成更相過。"]', '["丹霞煥上清，八风鼓太和。","迴我神霄輦，遂造嶺玉阿。","咄嗟天地外，九圍皆我家。","上采白日精，下饮黄月华。","靈观空無中，鵬路無间邪。","顧见魏賢安，濁氣傷汝和。","勤研玄中思，道成更相過。"]', '诗', 'shi', '', NULL, '列仙文 安度明 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bf72d4e-3c82-4c98-9966-321f5014d594', '夏日謁智遠禪師', '夏日謁智远禪師', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["吾師當幾祖，說法云無空。","禪心三界外，宴坐天地中。","院靜鬼神去，身與草木同。","因知護王國，滿鉢盛毒龍。","抖擻塵埃衣，謁師見真宗。","何必千萬劫，瞬息去樊籠。","盛夏火爲日，一堂十月風。","不得爲弟子，名姓挂儒宮。"]', '["吾師當幾祖，说法云無空。","禪心三界外，宴坐天地中。","院静鬼神去，身與草木同。","因知護王国，满鉢盛毒龙。","抖擻塵埃衣，謁師见真宗。","何必千万劫，瞬息去樊籠。","盛夏火爲日，一堂十月风。","不得爲弟子，名姓挂儒宮。"]', '诗', 'shi', '', NULL, '夏日謁智遠禪師 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f77593ab-6de7-4aea-b313-cd8ae8aa0799', '訪嵩陽道士不遇', '訪嵩陽道士不遇', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["先生五兵遊，文焰藏金鼎。","日下鶴過時，人間空落影。","常言一粒藥，不墮生死境。","何當列禦寇，去問仙人請。"]', '["先生五兵游，文焰藏金鼎。","日下鹤過时，人间空落影。","常言一粒藥，不墮生死境。","何當列禦寇，去问仙人請。"]', '诗', 'shi', '', NULL, '訪嵩陽道士不遇 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('970ae8a8-5142-493f-9e67-40c8b12c577c', '聽藍溪僧爲元居士說維摩經', '听藍溪僧爲元居士说維摩經', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["古樹少枝葉，真僧亦相依。","山木自曲直，道人無是非。","手持維摩偈，心向居士歸。","空景忽開霽，雪花猶在衣。","洗然水溪晝，寒物生光輝。"]', '["古樹少枝葉，真僧亦相依。","山木自曲直，道人無是非。","手持維摩偈，心向居士归。","空景忽开霽，雪花猶在衣。","洗然水溪晝，寒物生光輝。"]', '诗', 'shi', '', NULL, '聽藍溪僧爲元居士說維摩經 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('638d5260-6bc2-4256-9d58-725fa76e2576', '借車', '借车', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["借車載家具，家具少於車。","借者莫彈指，貧窮何足嗟。","百年徒役走，萬事盡隨花。"]', '["借车載家具，家具少於车。","借者莫彈指，貧窮何足嗟。","百年徒役走，万事尽隨花。"]', '诗', 'shi', '', NULL, '借車 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d6ea2ab-68b3-4172-ac6c-a13c375067c6', '喜符郎詩有天縱', '喜符郎诗有天縱', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["念符不由級，屹得文章階。","白玉抽一毫，綠珉已難排。","偷筆作文章，乞墨潛磨揩。","海鯨始生尾，試擺蓬壺渦。","幸當禁止之，勿使恣狂懷。","自悲無子嗟，喜妬雙喈喈。"]', '["念符不由級，屹得文章階。","白玉抽一毫，綠珉已难排。","偷笔作文章，乞墨潛磨揩。","海鯨始生尾，試擺蓬壺渦。","幸當禁止之，勿使恣狂懷。","自悲無子嗟，喜妬雙喈喈。"]', '诗', 'shi', '', NULL, '喜符郎詩有天縱 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95c9711d-cc5d-46f6-9d05-f0e27cd337b5', '憑周況先輩於朝賢乞茶', '憑周況先輩於朝賢乞茶', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["道意勿乏味，心緒病無悰。","蒙茗玉花盡，越甌荷葉空。","錦水有鮮色，蜀山饒芳藂。","雲根纔翦綠，印縫已霏紅。","曾向貴人得，最將詩叟同。","幸爲乞寄來，救此病劣躬。"]', '["道意勿乏味，心緒病無悰。","蒙茗玉花尽，越甌荷葉空。","錦水有鲜色，蜀山饒芳藂。","云根纔翦綠，印縫已霏紅。","曾向貴人得，最將诗叟同。","幸爲乞寄来，救此病劣躬。"]', '诗', 'shi', '', NULL, '憑周況先輩於朝賢乞茶 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3066753-cfc3-4aea-a36e-6d3fec1f3ab0', '上昭成閣不得於從姪僧悟空院歎嗟', '上昭成閣不得於從姪僧悟空院歎嗟', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["欲上千級閣，問天三四言。","未盡數十登，心目風浪翻。","手手把驚魄，脚脚踏墜魂。","却流至舊手，傍掣猶欲奔。","老病但自悲，古蠹木萬痕。","老力安可誇，秋海萍一根。","孤叟何所歸，晝眼如黃昏。","常恐失好步，入彼市井門。","結僧爲親情，策竹爲子孫。","此誠徒切切，此意空存存。","一寸地上語，高天何由聞。"]', '["欲上千級閣，问天三四言。","未尽數十登，心目风浪翻。","手手把驚魄，脚脚踏墜魂。","却流至旧手，傍掣猶欲奔。","老病但自悲，古蠹木万痕。","老力安可誇，秋海萍一根。","孤叟何所归，晝眼如黄昏。","常恐失好步，入彼市井门。","結僧爲親情，策竹爲子孫。","此誠徒切切，此意空存存。","一寸地上語，高天何由闻。"]', '诗', 'shi', '', NULL, '上昭成閣不得於從姪僧悟空院歎嗟 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fd71b2c-69b7-43db-84aa-7b9b95f067e3', '魏博田興尚書聽嫂命不立非夫人詩', '魏博田兴尚书听嫂命不立非夫人诗', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["君子躭古禮，如饞魚吞鉤。","昨聞敬嫂言，掣心東北流。","魏博田尚書，與禮相綢繆。","善詞聞天下，一日一再周。"]', '["君子躭古禮，如饞鱼吞鉤。","昨闻敬嫂言，掣心东北流。","魏博田尚书，與禮相綢繆。","善词闻天下，一日一再周。"]', '诗', 'shi', '', NULL, '魏博田興尚書聽嫂命不立非夫人詩 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba1c1ea7-01bf-40cb-b6a1-78b8188df5b3', '讀經', '读經', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["垂老抱佛脚，教妻讀黃經。","經黃名小品，一紙千明星。","曾讀大般若，細感肸蠁聽。","當時把齋中，方寸抱萬靈。","忽復入長安，蹴踏日月寧。","老方却歸來，收拾可丁丁。","拂拭塵几案，開函就孤亭。","儒書難借索，僧籤饒芳馨。","驛驛不開手，鏗鏗聞異鈴。","得善如焚香，去惡如脫腥。","安得顏子耳，曾未如此聽。","聽之何有言，德教貴有形。","何言中國外，有國如海萍。","海萍國教異，天聲各泠泠。","安排未定時，心火競熒熒。","將如庶幾者，聲盡形元冥。"]', '["垂老抱佛脚，教妻读黄經。","經黄名小品，一紙千明星。","曾读大般若，細感肸蠁听。","當时把斋中，方寸抱万靈。","忽复入长安，蹴踏日月寧。","老方却归来，收拾可丁丁。","拂拭塵几案，开函就孤亭。","儒书难借索，僧籤饒芳馨。","驛驛不开手，鏗鏗闻異鈴。","得善如焚香，去惡如脫腥。","安得顏子耳，曾未如此听。","听之何有言，德教貴有形。","何言中国外，有国如海萍。","海萍国教異，天声各泠泠。","安排未定时，心火競熒熒。","將如庶幾者，声尽形元冥。"]', '诗', 'shi', '', NULL, '讀經 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17678211-6bd8-4c2c-9ed9-cec4de707be0', '謝李輈再到', '謝李輈再到', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["等閑拜日晚，夫妻獨相瘡。","況是賢人冤，何必哭飛楊。","昨夜夢得劒，爲君藏中腸。","會將當風烹，血染布衣裳。","勞君又扣門，詞句失尋常。","我不忍出廳，血字濕土牆。","血字耿不滅，我心懼惶惶。","會有鏗鏘夫，見之目生光。","生光非等閑，君其且安祥。"]', '["等闲拜日晚，夫妻独相瘡。","況是賢人冤，何必哭飞楊。","昨夜梦得劒，爲君藏中腸。","會將當风烹，血染布衣裳。","勞君又扣门，词句失尋常。","我不忍出廳，血字濕土牆。","血字耿不滅，我心懼惶惶。","會有鏗鏘夫，见之目生光。","生光非等闲，君其且安祥。"]', '诗', 'shi', '', NULL, '謝李輈再到 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd77b4e7-0f9f-478f-a2cc-7da99c6b9827', '忽不貧喜盧仝書船歸洛', '忽不貧喜盧仝书船归洛', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["貧孟忽不貧，請問孟何如。","盧仝歸洛船，崔嵬但載書。","江潮清翻翻，淮潮碧徐徐。","夜信爲朝信，朝信良卷舒。","江淮君子水，相送仁有餘。","我去官色衫，肩經入君廬。","喃喃肩經郎，言語傾琪琚。","琪琚鏗好詞，鳥鵲躍庭除。","書船平安歸，喜報鄉里閭。","我願拾遺柴，巢經於空虛。","下免塵土侵，上爲雲霞居。","日月更相鎖，道義分明儲。","不願空岧嶢，但願實工夫。","實空二理微，分別相起予。","經書荒蕪多，爲君勉勉鋤。","勉勉不敢專，傳之方在諸。"]', '["貧孟忽不貧，請问孟何如。","盧仝归洛船，崔嵬但載书。","江潮清翻翻，淮潮碧徐徐。","夜信爲朝信，朝信良卷舒。","江淮君子水，相送仁有餘。","我去官色衫，肩經入君廬。","喃喃肩經郎，言語傾琪琚。","琪琚鏗好词，鸟鵲躍庭除。","书船平安归，喜報乡里閭。","我願拾遺柴，巢經於空虛。","下免塵土侵，上爲云霞居。","日月更相鎖，道義分明儲。","不願空岧嶢，但願實工夫。","實空二理微，分別相起予。","經书荒蕪多，爲君勉勉鋤。","勉勉不敢專，傳之方在諸。"]', '诗', 'shi', '', NULL, '忽不貧喜盧仝書船歸洛 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6e3083b-091c-4cb1-9a2a-170b869f0e31', '弔國殤', '弔国殤', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["徒言人最靈，白骨亂縱橫。","如何當春死，不及羣草生。","堯舜宰乾坤，器農不器兵。","秦漢盜山岳，鑄殺不鑄畊。","天地莫生金，生金人競爭。"]', '["徒言人最靈，白骨亂縱橫。","如何當春死，不及羣草生。","堯舜宰乾坤，器農不器兵。","秦漢盜山岳，鑄殺不鑄畊。","天地莫生金，生金人競爭。"]', '诗', 'shi', '', NULL, '弔國殤 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e6a00ad-c167-4256-bfa3-a4b25d19b978', '弔比干墓', '弔比干墓', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["殷辛帝天下，厭爲天下尊。","乾剛既一斷，賢愚無二門。","佞是福身本，忠是喪己源。","餓虎不食子，人無骨肉恩。","日影不入地，下埋冤死魂。","有骨不爲土，應作直木根。","今來過此鄉，下馬弔此墳。","靜念君臣間，有道誰敢論。"]', '["殷辛帝天下，厭爲天下尊。","乾剛既一斷，賢愚無二门。","佞是福身本，忠是喪己源。","餓虎不食子，人無骨肉恩。","日影不入地，下埋冤死魂。","有骨不爲土，應作直木根。","今来過此乡，下马弔此墳。","静念君臣间，有道誰敢論。"]', '诗', 'shi', '', NULL, '弔比干墓 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cff79683-5f8c-4939-97cd-5f98fdcd8fb6', '弔元魯山 一', '弔元魯山 一', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["[搏]鷙有餘飽，魯山長飢空。","豪人飫鮮肥，魯山飯蒿蓬。","食名皆霸官，食力乃堯農。","君子恥新態，魯山與古終。","天璞本平一，人巧生異同。","魯山不自剖，全璞竟沒躬。"]', '["[搏]鷙有餘飽，魯山长飢空。","豪人飫鲜肥，魯山飯蒿蓬。","食名皆霸官，食力乃堯農。","君子恥新態，魯山與古終。","天璞本平一，人巧生異同。","魯山不自剖，全璞竟沒躬。"]', '诗', 'shi', '', NULL, '弔元魯山 一 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6107697e-3474-46de-8e3e-7b5f9534a921', '弔元魯山 二', '弔元魯山 二', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["自剖多是非，流濫將何歸。","奔競立詭節，凌侮爭怪輝。","五常坐銷鑠，萬類隨衰微。","以茲見魯山，道蹇無所依。"]', '["自剖多是非，流濫將何归。","奔競立詭節，凌侮爭怪輝。","五常坐銷鑠，万類隨衰微。","以茲见魯山，道蹇無所依。"]', '诗', 'shi', '', NULL, '弔元魯山 二 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5639382-92ac-4d40-a3cd-2196c3843182', '弔元魯山 三', '弔元魯山 三', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["君子不自蹇，魯山蹇有因。","苟含天地秀，皆是天地身。","天地蹇既甚，魯山道莫伸。","天地氣不足，魯山食更貧。","始知補元化，竟須得賢人。"]', '["君子不自蹇，魯山蹇有因。","苟含天地秀，皆是天地身。","天地蹇既甚，魯山道莫伸。","天地氣不足，魯山食更貧。","始知補元化，竟須得賢人。"]', '诗', 'shi', '', NULL, '弔元魯山 三 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('995c073b-9f1b-4bc0-9f00-d2414159428a', '弔元魯山 四', '弔元魯山 四', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["賢人多自霾，道理與俗乖。","細功不敢言，遠韻方始諧。","萬物飽爲飽，萬人懷爲懷。","一聲苟失所，衆憾來相排。","所以元魯山，飢衰難與偕。"]', '["賢人多自霾，道理與俗乖。","細功不敢言，远韻方始諧。","万物飽爲飽，万人懷爲懷。","一声苟失所，衆憾来相排。","所以元魯山，飢衰难與偕。"]', '诗', 'shi', '', NULL, '弔元魯山 四 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab391671-fb2a-4d82-adee-1874536c85ee', '弔元魯山 五', '弔元魯山 五', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["遠階無近級，造次不可升。","賢人潔腸胃，寒日空澄凝。","血誓竟訛謬，膏明易煎蒸。","以之驅魯山，疎迹去莫乘。"]', '["远階無近級，造次不可升。","賢人潔腸胃，寒日空澄凝。","血誓竟訛謬，膏明易煎蒸。","以之驱魯山，疎迹去莫乘。"]', '诗', 'shi', '', NULL, '弔元魯山 五 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31ccc74f-fcdc-4ff9-a842-3380efbaaab2', '弔元魯山 六', '弔元魯山 六', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["言從魯山宦，盡化堯時心。","豺狼恥狂噬，齒牙閉霜金。","競來闢田土，相與畊嶔岑。","當宵無關鎖，竟歲饒歌吟。","善教復天術，美詞非俗箴。","精微自然事，視聽不可尋。","因書魯山績，庶合簫韶音。"]', '["言從魯山宦，尽化堯时心。","豺狼恥狂噬，齒牙閉霜金。","競来闢田土，相與畊嶔岑。","當宵無关鎖，竟歲饒歌吟。","善教复天術，美词非俗箴。","精微自然事，視听不可尋。","因书魯山績，庶合簫韶音。"]', '诗', 'shi', '', NULL, '弔元魯山 六 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76b6053e-67dd-47eb-8bbd-057fb717e01d', '弔元魯山 七', '弔元魯山 七', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["簫韶太平樂，魯山不虛作。","千古若有知，百年幸如昨。","誰能嗣教化，以此洗浮薄。","君臣貴深遇，天地有靈橐。","力運既艱難，德符方合漠。","名位苟虛曠，聲明自銷鑠。","禮法雖相救，貞濃易糟粕。","哀哀元魯山，畢竟誰能度。"]', '["簫韶太平乐，魯山不虛作。","千古若有知，百年幸如昨。","誰能嗣教化，以此洗浮薄。","君臣貴深遇，天地有靈橐。","力運既艱难，德符方合漠。","名位苟虛曠，声明自銷鑠。","禮法雖相救，貞濃易糟粕。","哀哀元魯山，畢竟誰能度。"]', '诗', 'shi', '', NULL, '弔元魯山 七 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('684108f3-6a6e-4052-a45f-12ad2f72b64c', '弔元魯山 八', '弔元魯山 八', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["當今富教化，元后得賢相。","冰心鏡衰古，霜議清遐障。","幽埋盡洸洗，滯旅免流浪。","唯餘魯山名，未獲旌廉讓。","二三貞苦士，刷視聳危望。","髮秋青山夜，目斷丹闕亮。","誘類幸從茲，嘉招固非妄。","小生奏狂狷，感惕增萬狀。"]', '["當今富教化，元后得賢相。","冰心镜衰古，霜議清遐障。","幽埋尽洸洗，滯旅免流浪。","唯餘魯山名，未獲旌廉讓。","二三貞苦士，刷視聳危望。","髮秋青山夜，目斷丹闕亮。","誘類幸從茲，嘉招固非妄。","小生奏狂狷，感惕增万狀。"]', '诗', 'shi', '', NULL, '弔元魯山 八 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2ac09ac-7ef7-4f31-b0a4-7a6732bd18e7', '弔元魯山 九', '弔元魯山 九', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["黃犢不知孝，魯山自駕車。","非賢不可妻，魯山竟無家。","供養恥佗力，言詞豈纖瑕。","將謠魯山德，賾海誰能涯。"]', '["黄犢不知孝，魯山自駕车。","非賢不可妻，魯山竟無家。","供養恥佗力，言词豈纖瑕。","將謠魯山德，賾海誰能涯。"]', '诗', 'shi', '', NULL, '弔元魯山 九 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('390cd0ff-b216-4913-bb04-fa2efa555ba6', '弔元魯山 十', '弔元魯山 十', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["遺嬰盡雛乳，何況骨肉枝。","心腸結苦誠，胸臆垂甘滋。","事已出古表，誰言獨今奇。","賢人母萬物，豈弟流前詩。"]', '["遺嬰尽雛乳，何況骨肉枝。","心腸結苦誠，胸臆垂甘滋。","事已出古表，誰言独今奇。","賢人母万物，豈弟流前诗。"]', '诗', 'shi', '', NULL, '弔元魯山 十 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7963fe91-fbbc-434e-b7f1-cdfef0af961c', '哭李觀', '哭李观', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["志士不得老，多爲直氣傷。","阮公終日哭，壽命固難長。","顏子既殂謝，孔門無輝光。","文星落奇曜，寶劒摧修鋩。","常作金應石，忽爲宮別商。","爲爾弔琴瑟，斷弦難再張。","偏轂不可轉，隻翼不可翔。","清塵無吹噓，委地難飛揚。","此義古所重，此風今則亡。","自聞喪元賓，一日八九狂。","沈痛此丈夫，驚呼彼穹蒼。","我有出俗韻，勞君疾惡腸。","知音既已矣，微言誰能彰。","旅葬無高墳，栽松不成行。","哀歌動寒日，贈淚沾晨霜。","神理本窅窅，今來更茫茫。","何以蕩悲懷，萬事付一觴。"]', '["志士不得老，多爲直氣傷。","阮公終日哭，壽命固难长。","顏子既殂謝，孔门無輝光。","文星落奇曜，寶劒摧修鋩。","常作金應石，忽爲宮別商。","爲爾弔琴瑟，斷弦难再張。","偏轂不可轉，隻翼不可翔。","清塵無吹噓，委地难飞揚。","此義古所重，此风今則亡。","自闻喪元賓，一日八九狂。","沈痛此丈夫，驚呼彼穹蒼。","我有出俗韻，勞君疾惡腸。","知音既已矣，微言誰能彰。","旅葬無高墳，栽松不成行。","哀歌动寒日，贈泪沾晨霜。","神理本窅窅，今来更茫茫。","何以蕩悲懷，万事付一觴。"]', '诗', 'shi', '', NULL, '哭李觀 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('343c0edb-c884-4346-a767-d2e449c41915', '李少府廳弔李元賓遺字', '李少府廳弔李元賓遺字', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["零落三四字，忽成千萬年。","那知冥寞客，不有補亡篇。","斜月弔空壁，旅人難獨眠。","一生能幾時，百慮來相煎。","戚戚故交淚，幽幽長夜泉。","已矣難重言，一言一潸然。"]', '["零落三四字，忽成千万年。","那知冥寞客，不有補亡篇。","斜月弔空壁，旅人难独眠。","一生能幾时，百慮来相煎。","戚戚故交泪，幽幽长夜泉。","已矣难重言，一言一潸然。"]', '诗', 'shi', '', NULL, '李少府廳弔李元賓遺字 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0506b846-9565-44ae-b41c-02e3c6879a8c', '悼吳興湯衡評事', '悼吳兴湯衡評事', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["君生霅水清，君歿霅水渾。","空令骨肉情，哭得白日昏。","大夜不復曉，古松長閉門。","琴弦綠水絕，詩句青山存。","昔爲芳春顏，今爲荒草根。","獨問冥冥理，先儒未曾言。"]', '["君生霅水清，君歿霅水渾。","空令骨肉情，哭得白日昏。","大夜不复晓，古松长閉门。","琴弦綠水絕，诗句青山存。","昔爲芳春顏，今爲荒草根。","独问冥冥理，先儒未曾言。"]', '诗', 'shi', '', NULL, '悼吳興湯衡評事 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe15afa3-dd50-4092-bfef-475f0e97d78c', '哀孟雲卿嵩陽荒居', '哀孟云卿嵩陽荒居', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["戚戚抱幽獨，宴宴沈荒居。","不聞新歡笑，但覩舊詩書。","藝蘗意彌苦，耕山食無餘。","定交昔何在，至戚今或疎。","薄俗易銷歇，淳風難久舒。","秋蕪上空堂，寒槿落枯渠。","薙草恐傷蕙，攝衣自理鋤。","殘芳亦可餌，遺秀誰忍除。","徘徊未能去，爲爾涕漣如。"]', '["戚戚抱幽独，宴宴沈荒居。","不闻新歡笑，但覩旧诗书。","藝蘗意彌苦，耕山食無餘。","定交昔何在，至戚今或疎。","薄俗易銷歇，淳风难久舒。","秋蕪上空堂，寒槿落枯渠。","薙草恐傷蕙，攝衣自理鋤。","殘芳亦可餌，遺秀誰忍除。","徘徊未能去，爲爾涕漣如。"]', '诗', 'shi', '', NULL, '哀孟雲卿嵩陽荒居 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fb51888-5d7c-4ee0-8284-a9e8b1adab5f', '哭盧貞國', '哭盧貞国', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["一別難與期，存亡易寒燠。","下馬入君門，聲悲不成哭。","自能富才藝，當冀深榮祿。","皇天負我賢，遺恨至兩目。","平生嘆無子，家家親相囑。"]', '["一別难與期，存亡易寒燠。","下马入君门，声悲不成哭。","自能富才藝，當冀深榮祿。","皇天負我賢，遺恨至兩目。","平生嘆無子，家家親相囑。"]', '诗', 'shi', '', NULL, '哭盧貞國 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8fbc419-4322-4e87-9cf1-362b17c194c0', '傷舊遊', '傷旧游', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["去春會處今春歸，花數不減人數稀。","朝笑片時暮成泣，東風一向還西輝。"]', '["去春會处今春归，花數不減人數稀。","朝笑片时暮成泣，东风一向還西輝。"]', '诗', 'shi', '', NULL, '傷舊遊 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93f7cf37-7d72-4951-a0d8-1b74a478727b', '弔房十五次卿少府', '弔房十五次卿少府', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["日高方得起，獨賞些些春。","可惜宛轉鸎，好音與佗人。","昔年此氣味，還走曲江濱。","逢著韓退之，結交方殷勤。","蜀客骨目高，聰辯劒戟新。","如何昨日歡，今日見無因。","英奇一謝世，視聽一爲塵。","誰言老淚短，淚短沾衣巾。"]', '["日高方得起，独賞些些春。","可惜宛轉鸎，好音與佗人。","昔年此氣味，還走曲江濱。","逢著韓退之，結交方殷勤。","蜀客骨目高，聰辯劒戟新。","如何昨日歡，今日见無因。","英奇一謝世，視听一爲塵。","誰言老泪短，泪短沾衣巾。"]', '诗', 'shi', '', NULL, '弔房十五次卿少府 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7815179b-c4d1-4365-a169-b4dabe1caaf3', '逢江南故晝上人會中鄭方回', '逢江南故晝上人會中鄭方回', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["相逢失意中，萬感因語至。","追思東林日，掩抑北邙淚。","筐篋有遺文，江山舊清氣。","塵生逍遙注，墨故飛動字。","荒毀碧澗居，虛無青松位。","珠沈百泉暗，月死羣象閉。","永謝平生言，知音豈容易。"]', '["相逢失意中，万感因語至。","追思东林日，掩抑北邙泪。","筐篋有遺文，江山旧清氣。","塵生逍遙注，墨故飞动字。","荒毀碧澗居，虛無青松位。","珠沈百泉暗，月死羣象閉。","永謝平生言，知音豈容易。"]', '诗', 'shi', '', NULL, '逢江南故晝上人會中鄭方回 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('983d12ef-7554-4fcc-8bdb-3a5f18e57932', '哭祕書包大監', '哭祕书包大監', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["哲人臥病日，賤子泣玉年。","常恐寶鏡破，明月難再圓。","文字未改素，聲容忽歸玄。","始知知音稀，千載一絕弦。","舊館有遺琴，清風那復傳。"]', '["哲人臥病日，賤子泣玉年。","常恐寶镜破，明月难再圓。","文字未改素，声容忽归玄。","始知知音稀，千載一絕弦。","旧館有遺琴，清风那复傳。"]', '诗', 'shi', '', NULL, '哭祕書包大監 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2262e5e7-f10e-47f6-a85e-b769ef289beb', '悼幼子', '悼幼子', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["一閉黃蒿門，不聞白日事。","生氣散成風，枯骸化爲地。","負我十年恩，欠爾千行淚。","灑之北原上，不待秋風至。"]', '["一閉黄蒿门，不闻白日事。","生氣散成风，枯骸化爲地。","負我十年恩，欠爾千行泪。","灑之北原上，不待秋风至。"]', '诗', 'shi', '', NULL, '悼幼子 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21985c1e-ae70-4e0c-8218-e934d407bb93', '悼亡', '悼亡', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["山頭明月夜增輝，增輝不照重泉下。","泉下雙龍無再期，金蠶玉燕空銷化。","朝雲暮雨成古墟，蕭蕭野竹風吹亞。"]', '["山头明月夜增輝，增輝不照重泉下。","泉下雙龙無再期，金蠶玉燕空銷化。","朝云暮雨成古墟，蕭蕭野竹风吹亞。"]', '诗', 'shi', '', NULL, '悼亡 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f07e39fe-5dd8-4940-a589-07af5f2db4ec', '弔李元賓墳', '弔李元賓墳', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["曉上荒涼原，弔彼寂寥魂。","眼咽此時淚，耳悽在日言。","冥冥千萬年，墳鎖孤松根。"]', '["晓上荒涼原，弔彼寂寥魂。","眼咽此时泪，耳悽在日言。","冥冥千万年，墳鎖孤松根。"]', '诗', 'shi', '', NULL, '弔李元賓墳 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c68201f-53b9-471b-9cf0-824b23481fb5', '覽崔爽遺文因紓幽懷', '覽崔爽遺文因紓幽懷', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["墮淚數首文，悲結千里墳。","蒼旻且留我，白日空遺君。","仙鶴未巢月，衰鳳先墜雲。","清風獨起時，舊語如再聞。","瑤草罷葳蕤，桂花休氛氳。","萬物與我心，相感吳江濆。"]', '["墮泪數首文，悲結千里墳。","蒼旻且留我，白日空遺君。","仙鹤未巢月，衰鳳先墜云。","清风独起时，旧語如再闻。","瑤草罷葳蕤，桂花休氛氳。","万物與我心，相感吳江濆。"]', '诗', 'shi', '', NULL, '覽崔爽遺文因紓幽懷 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31d023e0-e562-452d-8812-e3b7e88e73c5', '峽哀 一', '峽哀 一', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["昔多相與笑，今誰相與哀。","峽哀哭幽魂，噭噭風吹來。","墮魄抱空月，出沒難自裁。","齏粉一閃間，春濤百丈雷。","峽水聲不平，碧沲牽清洄。","沙稜箭箭急，波齒齗齗開。","呀彼無底吮，待此不測災。","谷號相噴激，石怒爭旋迴。","古醉有復鄉，今縲多爲能。","字孤徒髣髴，銜雪猶驚猜。","薄俗少直腸，交結須橫財。","黃金買相弔，幽泣無餘漼。","我有古心意，爲君空摧頹。"]', '["昔多相與笑，今誰相與哀。","峽哀哭幽魂，噭噭风吹来。","墮魄抱空月，出沒难自裁。","齏粉一閃间，春濤百丈雷。","峽水声不平，碧沲牽清洄。","沙稜箭箭急，波齒齗齗开。","呀彼無底吮，待此不測災。","谷號相噴激，石怒爭旋迴。","古醉有复乡，今縲多爲能。","字孤徒髣髴，銜雪猶驚猜。","薄俗少直腸，交結須橫財。","黄金買相弔，幽泣無餘漼。","我有古心意，爲君空摧頹。"]', '诗', 'shi', '', NULL, '峽哀 一 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c740e0f-b75f-4d19-abee-2c5a51e7f96f', '峽哀 二', '峽哀 二', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["上天下天水，出地入地舟。","石劒相劈斫，石波怒蛟虯。","花木疊宿春，風飆凝古秋。","幽怪窟穴語，飛聞肸蠁流。","沈哀日已深，銜訴將何求。"]', '["上天下天水，出地入地舟。","石劒相劈斫，石波怒蛟虯。","花木叠宿春，风飆凝古秋。","幽怪窟穴語，飞闻肸蠁流。","沈哀日已深，銜訴將何求。"]', '诗', 'shi', '', NULL, '峽哀 二 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae57e200-b1b8-4773-8779-96766948a8e8', '峽哀 三', '峽哀 三', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["三峽一線天，三峽萬繩泉。","上仄碎日月，下掣狂漪漣。","破魂一兩點，凝幽數百年。","峽暉不停午，峽險多飢涎。","樹根鎖枯棺，孤骨褭褭懸。","樹枝哭霜棲，哀韻杳杳鮮。","逐客零落腸，到此湯火煎。","性命如紡績，道路隨索緣。","奠淚弔波靈，波靈將閃然。"]', '["三峽一線天，三峽万繩泉。","上仄碎日月，下掣狂漪漣。","破魂一兩点，凝幽數百年。","峽暉不停午，峽險多飢涎。","樹根鎖枯棺，孤骨褭褭懸。","樹枝哭霜棲，哀韻杳杳鲜。","逐客零落腸，到此湯火煎。","性命如紡績，道路隨索緣。","奠泪弔波靈，波靈將閃然。"]', '诗', 'shi', '', NULL, '峽哀 三 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ed92763-9ec1-4a40-a4fc-13fd46f584c4', '峽哀 四', '峽哀 四', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["峽亂鳴清磬，產石爲鮮鱗。","噴爲腥雨涎，吹作黑井身。","怪光閃衆異，餓劒唯待人。","老腸未曾飽，古齒嶄巖嗔。","嚼齒三峽泉，三峽聲齗齗。"]', '["峽亂鳴清磬，產石爲鲜鱗。","噴爲腥雨涎，吹作黑井身。","怪光閃衆異，餓劒唯待人。","老腸未曾飽，古齒嶄巖嗔。","嚼齒三峽泉，三峽声齗齗。"]', '诗', 'shi', '', NULL, '峽哀 四 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d66406d-4f78-418f-8338-c541eb127321', '峽哀 五', '峽哀 五', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["峽螭老解語，百丈潭底聞。","毒波爲計校，飲血養子孫。","既非臯陶吏，空食沈獄魂。","潛怪何幽幽，魄說徒云云。","峽聽哀哭泉，峽弔鰥寡猿。","峽聲非人聲，劒水相劈翻。","斯誰士諸謝，奏此沉苦言。"]', '["峽螭老解語，百丈潭底闻。","毒波爲計校，饮血養子孫。","既非臯陶吏，空食沈獄魂。","潛怪何幽幽，魄说徒云云。","峽听哀哭泉，峽弔鰥寡猿。","峽声非人声，劒水相劈翻。","斯誰士諸謝，奏此沉苦言。"]', '诗', 'shi', '', NULL, '峽哀 五 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06de6be3-0257-4ee5-9fde-2e2fef90ad9b', '峽哀 六', '峽哀 六', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["讒人峽虯心，渴罪呀然潯。","所食無直腸，所語饒梟音。","石齒嚼百泉，石風號千琴。","幽哀莫能遠，分雪何由尋。","月魄高卓卓，峽窟清沉沉。","銜訴何時明，抱痛已不禁。","犀飛空波濤，裂石千嶔岑。"]', '["讒人峽虯心，渴罪呀然潯。","所食無直腸，所語饒梟音。","石齒嚼百泉，石风號千琴。","幽哀莫能远，分雪何由尋。","月魄高卓卓，峽窟清沉沉。","銜訴何时明，抱痛已不禁。","犀飞空波濤，裂石千嶔岑。"]', '诗', 'shi', '', NULL, '峽哀 六 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('637d8858-d5ab-4ba0-b687-a72be1f55bec', '峽哀 七', '峽哀 七', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["峽稜剸日月，日月多摧輝。","物皆斜仄生，鳥亦斜仄飛。","潛石齒相鎖，沉魂招莫歸。","恍惚清泉甲，斑斕碧石衣。","餓嚥潺湲號，涎似泓浤肥。","峽青不可遊，腥草生微微。"]', '["峽稜剸日月，日月多摧輝。","物皆斜仄生，鸟亦斜仄飞。","潛石齒相鎖，沉魂招莫归。","恍惚清泉甲，斑斕碧石衣。","餓嚥潺湲號，涎似泓浤肥。","峽青不可游，腥草生微微。"]', '诗', 'shi', '', NULL, '峽哀 七 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8d89175-a6e3-493b-84f7-86eb548a0ce6', '峽哀 八', '峽哀 八', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["峽景滑易墮，峽花怪非春。","紅光根潛涎，碧雨飛沃津。","巴谷蛟螭心，巴鄉魍魎親。","噉生不問賢，至死獨養身。","腥語信者誰，拗歌歡非真。","仄田無異稼，毒水多獰鱗。","異類不可友，峽哀哀難伸。"]', '["峽景滑易墮，峽花怪非春。","紅光根潛涎，碧雨飞沃津。","巴谷蛟螭心，巴乡魍魎親。","噉生不问賢，至死独養身。","腥語信者誰，拗歌歡非真。","仄田無異稼，毒水多獰鱗。","異類不可友，峽哀哀难伸。"]', '诗', 'shi', '', NULL, '峽哀 八 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3be29063-1b83-4ae7-a589-32a9d3182fcb', '峽哀 九', '峽哀 九', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["峽水劒戟獰，峽舟霹靂翔。","因依虺蜴手，起坐風雨忙。","峽旅多竄官，峽氓多非良。","滑心不可求，滑習積已長。","漠漠涎霧起，齗齗涎水光。","渴賢如之何，忽在水中央。"]', '["峽水劒戟獰，峽舟霹靂翔。","因依虺蜴手，起坐风雨忙。","峽旅多竄官，峽氓多非良。","滑心不可求，滑習積已长。","漠漠涎霧起，齗齗涎水光。","渴賢如之何，忽在水中央。"]', '诗', 'shi', '', NULL, '峽哀 九 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3f69401-d5ea-4775-a07d-453ba5d27816', '峽哀 十', '峽哀 十', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["梟鴟作人語，蛟虯吸水波。","能于白日間，諂欲晴風和。","駭智蹶衆命，蘊腥布深蘿。","齒泉無底貧，鋸涎在處多。","仄樹鳥不巢，踔𨃚猿相過。","峽哀不可聽，峽怨其奈何。"]', '["梟鴟作人語，蛟虯吸水波。","能于白日间，諂欲晴风和。","駭智蹶衆命，蘊腥布深蘿。","齒泉無底貧，鋸涎在处多。","仄樹鸟不巢，踔𨃚猿相過。","峽哀不可听，峽怨其奈何。"]', '诗', 'shi', '', NULL, '峽哀 十 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7fe7bae-cf4a-484f-a5c3-726e217a15ce', '杏殤 一', '杏殤 一', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["凍手莫弄珠，弄珠珠易飛。","驚霜莫翦春，翦春無光輝。","零落小花乳，斕斑昔嬰衣。","拾之不盈把，日暮空悲歸。"]', '["凍手莫弄珠，弄珠珠易飞。","驚霜莫翦春，翦春無光輝。","零落小花乳，斕斑昔嬰衣。","拾之不盈把，日暮空悲归。"]', '诗', 'shi', '', NULL, '杏殤 一 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd91cd6c-166f-4f90-bcab-d71b2f6d48bc', '杏殤 二', '杏殤 二', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["地上空拾星，枝上不見花。","哀哀孤老人，戚戚無子家。","豈若沒水鳧，不如拾巢鴉。","浪鷇破便飛，風雛褭相誇。","芳嬰不復生，向物空悲嗟。"]', '["地上空拾星，枝上不见花。","哀哀孤老人，戚戚無子家。","豈若沒水鳧，不如拾巢鴉。","浪鷇破便飞，风雛褭相誇。","芳嬰不复生，向物空悲嗟。"]', '诗', 'shi', '', NULL, '杏殤 二 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cd29e60-6971-4072-8a0e-8d96adefe284', '杏殤 三', '杏殤 三', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["應是一線淚，入此春木心。","枝枝不成花，片片落翦金。","春壽何可長，霜哀亦已深。","常時洗芳泉，此日洗淚襟。"]', '["應是一線泪，入此春木心。","枝枝不成花，片片落翦金。","春壽何可长，霜哀亦已深。","常时洗芳泉，此日洗泪襟。"]', '诗', 'shi', '', NULL, '杏殤 三 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2988fec5-a58f-4310-ae02-d8357b44da0f', '杏殤 四', '杏殤 四', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["兒生月不明，兒死月始光。","兒月兩相奪，兒命果不長。","如何此英英，亦爲弔蒼蒼。","甘爲墮地塵，不爲末世芳。"]', '["兒生月不明，兒死月始光。","兒月兩相奪，兒命果不长。","如何此英英，亦爲弔蒼蒼。","甘爲墮地塵，不爲末世芳。"]', '诗', 'shi', '', NULL, '杏殤 四 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9b9a39b-c5ed-45d1-9641-dec4175814fb', '杏殤 五', '杏殤 五', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["踏地恐土痛，損彼芳樹根。","此誠天不知，翦棄我子孫。","垂枝有千落，芳命無一存。","誰謂生人家，春色不入門。"]', '["踏地恐土痛，損彼芳樹根。","此誠天不知，翦棄我子孫。","垂枝有千落，芳命無一存。","誰謂生人家，春色不入门。"]', '诗', 'shi', '', NULL, '杏殤 五 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3fb12bb-2b1b-4177-8d50-4864bacc7673', '杏殤 六', '杏殤 六', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["冽冽霜殺春，枝枝疑纖刀。","木心既零落，山竅空呼號。","班班落地英，點點如明膏。","始知天地間，萬物皆不牢。"]', '["冽冽霜殺春，枝枝疑纖刀。","木心既零落，山竅空呼號。","班班落地英，点点如明膏。","始知天地间，万物皆不牢。"]', '诗', 'shi', '', NULL, '杏殤 六 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22024e09-ca03-4c28-a9c9-9cc3f7a12281', '杏殤 七', '杏殤 七', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["哭此不成春，淚痕三四斑。","失芳蝶既狂，失子老亦孱。","且無生生力，自有死死顏。","靈鳳不銜訴，誰爲扣天關。"]', '["哭此不成春，泪痕三四斑。","失芳蝶既狂，失子老亦孱。","且無生生力，自有死死顏。","靈鳳不銜訴，誰爲扣天关。"]', '诗', 'shi', '', NULL, '杏殤 七 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6765273-c5ad-43fd-9756-f61ab31cfdb1', '杏殤 八', '杏殤 八', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["此兒自見災，花發多不諧。","窮老收碎心，永夜抱破懷。","聲死更何言，意死不必喈。","病叟無子孫，獨立猶束柴。"]', '["此兒自见災，花發多不諧。","窮老收碎心，永夜抱破懷。","声死更何言，意死不必喈。","病叟無子孫，独立猶束柴。"]', '诗', 'shi', '', NULL, '杏殤 八 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38055e54-5940-46f8-a5f5-5b0e1980fa41', '杏殤 九', '杏殤 九', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["霜似敗紅芳，剪啄十數雙。","參差呻細風，噞喁沸淺江。","泣凝不可消，恨壯難自降。","空遺舊日影，怨彼小書窗。"]', '["霜似敗紅芳，剪啄十數雙。","參差呻細风，噞喁沸淺江。","泣凝不可消，恨壯难自降。","空遺旧日影，怨彼小书窗。"]', '诗', 'shi', '', NULL, '杏殤 九 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4ab0057-6846-46fc-afce-1d641980509f', '弔江南老家人春梅', '弔江南老家人春梅', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["念爾筋力盡，違我衣食恩。","奈何粗獷兒，生鞭見死痕。","舊使常以禮，新怨將誰吞。","胡爲乎泥中，消歇教義源。"]', '["念爾筋力尽，違我衣食恩。","奈何粗獷兒，生鞭见死痕。","旧使常以禮，新怨將誰吞。","胡爲乎泥中，消歇教義源。"]', '诗', 'shi', '', NULL, '弔江南老家人春梅 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6db50b2a-0236-411d-b939-15ff10357a64', '哭李丹員外幷寄杜中丞', '哭李丹員外幷寄杜中丞', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["生死方知交態存，忍將齚齖報幽魂。","十年同在平原客，更遣何人哭寢門。"]', '["生死方知交態存，忍將齚齖報幽魂。","十年同在平原客，更遣何人哭寢门。"]', '诗', 'shi', '', NULL, '哭李丹員外幷寄杜中丞 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('346f34e0-5943-44bb-b4ec-3370c166a187', '哭劉言史', '哭劉言史', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["詩人業孤峭，餓死良已多。","相悲與相笑，累累其奈何。","精異劉言史，詩腸傾珠河。","取次抱置之，飛過東溟波。","可惜大國謠，飄爲四夷歌。","常於衆中會，顏色兩切[磋]。","今日果成死，葬襄之洛河。","洛岸遠相弔，灑淚雙滂沱。"]', '["诗人業孤峭，餓死良已多。","相悲與相笑，累累其奈何。","精異劉言史，诗腸傾珠河。","取次抱置之，飞過东溟波。","可惜大国謠，飄爲四夷歌。","常於衆中會，顏色兩切[磋]。","今日果成死，葬襄之洛河。","洛岸远相弔，灑泪雙滂沱。"]', '诗', 'shi', '', NULL, '哭劉言史 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de14bb60-1d94-446e-afff-0c7d17b454d4', '弔盧殷 一', '弔盧殷 一', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["詩人多清峭，餓死抱空山。","白雲既無主，飛出意等閑。","久病牀席尸，護喪童僕孱。","故書窮鼠嚙，狼藉一室間。","君歸新鬼鄉，我面古玉顏。","羞見入地時，無人叫追攀。","百泉空相吊，日久哀潺潺。"]', '["诗人多清峭，餓死抱空山。","白云既無主，飞出意等闲。","久病牀席尸，護喪童僕孱。","故书窮鼠嚙，狼藉一室间。","君归新鬼乡，我面古玉顏。","羞见入地时，無人叫追攀。","百泉空相吊，日久哀潺潺。"]', '诗', 'shi', '', NULL, '弔盧殷 一 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('008fdabf-1891-4fe5-8851-36318b19224e', '弔盧殷 二', '弔盧殷 二', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["唧唧復唧唧，千古一月色。","新新復新新，千古一花春。","邙風噫孟郊，嵩秋葬盧殷。","北邙前後客，相弔爲埃塵。","北邙棘針草，淚根生苦辛。","煙火不自煖，筋力早已貧。","幽薦一盃泣，瀉之清洛濱。","添爲斷腸聲，愁殺長別人。"]', '["唧唧复唧唧，千古一月色。","新新复新新，千古一花春。","邙风噫孟郊，嵩秋葬盧殷。","北邙前後客，相弔爲埃塵。","北邙棘針草，泪根生苦辛。","煙火不自煖，筋力早已貧。","幽薦一盃泣，瀉之清洛濱。","添爲斷腸声，愁殺长別人。"]', '诗', 'shi', '', NULL, '弔盧殷 二 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ccb9aec-0dc4-4b49-96c3-1c5b720297a0', '弔盧殷 三', '弔盧殷 三', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["棘針風相號，破碎諸苦哀。","苦哀不可聞，掩耳亦入來。","哭弦多煎聲，恨涕有餘摧。","噫貧氣已焚，噫死心更灰。","夢世浮閃閃，淚波深洄洄。","薤歌一以去，蒿閉不復開。"]', '["棘針风相號，破碎諸苦哀。","苦哀不可闻，掩耳亦入来。","哭弦多煎声，恨涕有餘摧。","噫貧氣已焚，噫死心更灰。","梦世浮閃閃，泪波深洄洄。","薤歌一以去，蒿閉不复开。"]', '诗', 'shi', '', NULL, '弔盧殷 三 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b282752-b9a3-49c7-b975-1f65993ea72a', '弔盧殷 四', '弔盧殷 四', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["登封草木深，登封道路微。","日月不與光，莓苔空生衣。","可憐無子翁，蚍蜉緣病肌。","攣臥歲時長，漣漣但幽噫。","幽噫虎豹聞，此外相訪稀。","至親唯有詩，抱心死有歸。","河南韓先生，後君作因依。","磨一片嵌巖，書千古光輝。"]', '["登封草木深，登封道路微。","日月不與光，莓苔空生衣。","可怜無子翁，蚍蜉緣病肌。","攣臥歲时长，漣漣但幽噫。","幽噫虎豹闻，此外相訪稀。","至親唯有诗，抱心死有归。","河南韓先生，後君作因依。","磨一片嵌巖，书千古光輝。"]', '诗', 'shi', '', NULL, '弔盧殷 四 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2370c769-c3fb-4154-a5d4-93b5e50c098a', '弔盧殷 五', '弔盧殷 五', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["賢人無計較，生苦死徒誇。","佗名潤子孫，君名潤泥沙。","可惜千首文，閃如一朝花。","零落難苦言，起坐空驚嗟。"]', '["賢人無計較，生苦死徒誇。","佗名潤子孫，君名潤泥沙。","可惜千首文，閃如一朝花。","零落难苦言，起坐空驚嗟。"]', '诗', 'shi', '', NULL, '弔盧殷 五 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2238859b-ade4-47fc-8684-502f8143f88b', '弔盧殷 六', '弔盧殷 六', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["耳聞陋巷生，眼見魯山君。","餓死始有名，餓名高氛氳。","戇叟老壯氣，感之爲憂雲。","所憂唯一泣，古今相紛紛。","平生與君說，逮此俱云云。"]', '["耳闻陋巷生，眼见魯山君。","餓死始有名，餓名高氛氳。","戇叟老壯氣，感之爲憂云。","所憂唯一泣，古今相紛紛。","平生與君说，逮此俱云云。"]', '诗', 'shi', '', NULL, '弔盧殷 六 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bef6b664-d115-43f8-929d-97bec1b95af4', '弔盧殷 七', '弔盧殷 七', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["初識漆鬢髮，爭爲新文章。","夜踏明月橋，店飲吾曹床。","醉啜二盃釀，名郁一縣香。","寺中摘梅花，園裏翦浮芳。","高嗜綠蔬羹，意輕肥膩羊。","吟哦無滓韻，言語多古腸。","白首忽然至，盛年如偷將。","清濁俱莫追，何須駡滄浪。"]', '["初識漆鬢髮，爭爲新文章。","夜踏明月橋，店饮吾曹床。","醉啜二盃釀，名郁一縣香。","寺中摘梅花，园裏翦浮芳。","高嗜綠蔬羹，意轻肥膩羊。","吟哦無滓韻，言語多古腸。","白首忽然至，盛年如偷將。","清濁俱莫追，何須駡滄浪。"]', '诗', 'shi', '', NULL, '弔盧殷 七 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b738b26-0060-4418-8025-38a133c90064', '弔盧殷 八', '弔盧殷 八', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["前賢多哭酒，哭酒免哭心。","後賢試銜之，哀至無不深。","少年哭酒時，白髮亦已侵。","老年哭酒時，聲韻隨生沈。","寄言哭酒賓，勿作登封音。","登封徒放聲，天地竟難尋。"]', '["前賢多哭酒，哭酒免哭心。","後賢試銜之，哀至無不深。","少年哭酒时，白髮亦已侵。","老年哭酒时，声韻隨生沈。","寄言哭酒賓，勿作登封音。","登封徒放声，天地竟难尋。"]', '诗', 'shi', '', NULL, '弔盧殷 八 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2815a0de-0d56-4a9b-bba9-b0e349b8cad9', '弔盧殷 九', '弔盧殷 九', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["同人少相哭，異類多相號。","始知禽獸癡，却至天然高。","非子病無淚，非父念莫勞。","如何裁親疎，用禮如用刀。","孤喪鮮匍匐，閉哀抱鬱陶。","煩他手中葬，誠信焉能褒。","嗟嗟無子翁，死棄如脫毛。"]', '["同人少相哭，異類多相號。","始知禽獸癡，却至天然高。","非子病無泪，非父念莫勞。","如何裁親疎，用禮如用刀。","孤喪鲜匍匐，閉哀抱鬱陶。","煩他手中葬，誠信焉能褒。","嗟嗟無子翁，死棄如脫毛。"]', '诗', 'shi', '', NULL, '弔盧殷 九 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22f231c5-5f6c-4328-baa0-c9426d921a37', '弔盧殷 十', '弔盧殷 十', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["聖人哭賢人，骨化氣爲星。","文章飛上天，列宿增晶熒。","前古文可數，今人文亦靈。","高名稱謫仙，昇降曾莫停。","有文死更香，無文生亦腥。","爲君鏗好辭，永傳作謐寧。"]', '["聖人哭賢人，骨化氣爲星。","文章飞上天，列宿增晶熒。","前古文可數，今人文亦靈。","高名稱謫仙，昇降曾莫停。","有文死更香，無文生亦腥。","爲君鏗好辞，永傳作謐寧。"]', '诗', 'shi', '', NULL, '弔盧殷 十 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cadff3b7-673c-4865-ae08-07142e12c523', '寄遠曲', '寄远曲', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["美人來去春江暖，江頭無人湘水滿。","浣沙石上水禽栖，江南路長春日短。","蘭舟桂楫常渡江，無因重寄雙瓊璫。"]', '["美人来去春江暖，江头無人湘水满。","浣沙石上水禽栖，江南路长春日短。","蘭舟桂楫常渡江，無因重寄雙瓊璫。"]', '诗', 'shi', '', NULL, '寄遠曲 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d82512d0-4837-4c31-9a00-ba54632af283', '行路難', '行路难', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["湘東行人長歎息，十年離家歸未得。","弊裘羸馬苦難行，僮僕饑寒少筋力。","君不見牀頭黃金盡，壯士無顏色。","龍蟠泥中未有雲，不能生彼升天翼。"]', '["湘东行人长歎息，十年離家归未得。","弊裘羸马苦难行，僮僕饑寒少筋力。","君不见牀头黄金尽，壯士無顏色。","龙蟠泥中未有云，不能生彼升天翼。"]', '诗', 'shi', '', NULL, '行路難 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16f31f24-e417-47b2-8fd8-478d9e10cd23', '征婦怨', '征婦怨', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["九月匈奴殺邊將，漢軍全沒遼水上。","萬里無人收白骨，家家城下招魂葬。","婦人依倚子與夫，同居貧賤心亦舒。","夫死戰場子在腹，妾身雖存如晝燭。"]', '["九月匈奴殺邊將，漢軍全沒遼水上。","万里無人收白骨，家家城下招魂葬。","婦人依倚子與夫，同居貧賤心亦舒。","夫死戰場子在腹，妾身雖存如晝燭。"]', '诗', 'shi', '', NULL, '征婦怨 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('926829c8-5343-499f-ae07-833e3b238f0a', '白紵歌', '白紵歌', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["皎皎白紵白且鮮，將作春衣稱少年。","裁縫長短不能定，自持刀尺向姑前。","復恐蘭膏汙纖指，常遣傍人收墮珥。","衣裳著時寒食下，還把玉鞭鞭白馬。"]', '["皎皎白紵白且鲜，將作春衣稱少年。","裁縫长短不能定，自持刀尺向姑前。","复恐蘭膏汙纖指，常遣傍人收墮珥。","衣裳著时寒食下，還把玉鞭鞭白马。"]', '诗', 'shi', '', NULL, '白紵歌 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0b8c9b0-e68f-444e-b99c-c8733efe43b2', '野老歌', '野老歌', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["老農家貧在山住，耕種山田三四畝。","苗疎稅多不得食，輸入官倉化爲土。","歲暮鋤犂傍空室，呼兒登山收橡實。","西江賈客珠百斛，船中養犬長食肉。"]', '["老農家貧在山住，耕種山田三四畝。","苗疎稅多不得食，輸入官倉化爲土。","歲暮鋤犂傍空室，呼兒登山收橡實。","西江賈客珠百斛，船中養犬长食肉。"]', '诗', 'shi', '', NULL, '野老歌 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c97e43dc-51d8-4d66-b3ff-78e71a23bc51', '寄衣曲', '寄衣曲', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["織素縫衣獨苦辛，遠因回使寄征人。","官家亦自寄衣去，貴從妾手著君身。","高堂姑老無侍子，不得自到邊城裏。","殷勤爲看初著時，征夫身上宜不宜。"]', '["织素縫衣独苦辛，远因回使寄征人。","官家亦自寄衣去，貴從妾手著君身。","高堂姑老無侍子，不得自到邊城裏。","殷勤爲看初著时，征夫身上宜不宜。"]', '诗', 'shi', '', NULL, '寄衣曲 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a91a995-8301-4000-a129-d93c9224852e', '送遠曲', '送远曲', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["戲馬臺南山簇簇，山邊飲酒歌別曲。","行人醉後起登車，席上回尊勸僮僕。","青天漫漫覆長路，遠遊無家安得住。","願君到處自題名，他日知君從此去。"]', '["戲马台南山簇簇，山邊饮酒歌別曲。","行人醉後起登车，席上回尊勸僮僕。","青天漫漫覆长路，远游無家安得住。","願君到处自題名，他日知君從此去。"]', '诗', 'shi', '', NULL, '送遠曲 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bcb1dcc-33d6-4983-a3e1-d2a0db8416a4', '築城詞', '築城词', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["築城處，千人萬人齊把杵。","重重土堅試行錐，軍吏執鞭催作遲。","來時一年深磧裏，盡著短衣渴無水。","力盡不得拋杵聲，杵聲未盡人皆死。","家家養男當門戶，今日作君城下土。"]', '["築城处，千人万人齊把杵。","重重土堅試行錐，軍吏執鞭催作遲。","来时一年深磧裏，尽著短衣渴無水。","力尽不得拋杵声，杵声未尽人皆死。","家家養男當门戶，今日作君城下土。"]', '诗', 'shi', '', NULL, '築城詞 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fec9452-4066-4bce-a4b6-18f0fcbd4a78', '猛虎行', '猛虎行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["南山北山樹冥冥，猛虎白日繞林行。","向晚一身當道食，山中麋鹿盡無聲。","年年養子在空谷，雌雄上山不相逐。","谷中近窟有山村，長向村家取黃犢。","五陵年少不敢射，空來林下看行迹。"]', '["南山北山樹冥冥，猛虎白日繞林行。","向晚一身當道食，山中麋鹿尽無声。","年年養子在空谷，雌雄上山不相逐。","谷中近窟有山村，长向村家取黄犢。","五陵年少不敢射，空来林下看行迹。"]', '诗', 'shi', '', NULL, '猛虎行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e746df5e-8161-458b-8bbf-4ca3f3c90b91', '別離曲', '別離曲', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["行人結束出門去，幾時更踏門前路。","憶昔君初納采時，不言身屬遼陽戍。","早知今日當別離，成君家計良爲誰。","男兒生身自有役，那得誤我少年時。","不如逐君征戰死，誰能獨老空閨裏。"]', '["行人結束出门去，幾时更踏门前路。","憶昔君初納采时，不言身屬遼陽戍。","早知今日當別離，成君家計良爲誰。","男兒生身自有役，那得誤我少年时。","不如逐君征戰死，誰能独老空閨裏。"]', '诗', 'shi', '', NULL, '別離曲 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a89bd17-bf77-4229-aed9-1418f67081e4', '牧童詞', '牧童词', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["遠牧牛，遶村四面禾黍稠。","陂中飢烏啄牛背，令我不得戲壠頭。","入陂草多牛散行，白犢時向蘆中鳴。","隔堤吹葉應同伴，還鼓長鞭三四聲。","牛牛食草莫相觸，官家截爾頭上角。"]', '["远牧牛，遶村四面禾黍稠。","陂中飢烏啄牛背，令我不得戲壠头。","入陂草多牛散行，白犢时向蘆中鳴。","隔堤吹葉應同伴，還鼓长鞭三四声。","牛牛食草莫相觸，官家截爾头上角。"]', '诗', 'shi', '', NULL, '牧童詞 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d59506ee-5231-4bc1-bdbc-478c7a7074b8', '沙堤行呈裴相公', '沙堤行呈裴相公', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["長安大道沙爲堤，早風無塵雨無泥。","宮中玉漏下三刻，朱衣導騎丞相來。","路傍高樓息歌吹，千車不行行者避。","街官閭吏相傳呼，當前十里惟空衢。","白麻詔下移相印，新堤未成舊堤盡。"]', '["长安大道沙爲堤，早风無塵雨無泥。","宮中玉漏下三刻，朱衣導騎丞相来。","路傍高楼息歌吹，千车不行行者避。","街官閭吏相傳呼，當前十里惟空衢。","白麻詔下移相印，新堤未成旧堤尽。"]', '诗', 'shi', '', NULL, '沙堤行呈裴相公 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49522bf6-df30-4a45-a34f-68ed4c97bcc9', '求仙行', '求仙行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["漢皇欲作飛仙子，年年採藥東海裏。","蓬萊無路海無邊，方士舟中相枕死。","招搖在天迴白日，甘泉玉樹無仙實。","九皇真人終不下，空向離宮祠太乙。","丹田有氣凝素華，君能保之昇絳霞。"]', '["漢皇欲作飞仙子，年年採藥东海裏。","蓬萊無路海無邊，方士舟中相枕死。","招搖在天迴白日，甘泉玉樹無仙實。","九皇真人終不下，空向離宮祠太乙。","丹田有氣凝素华，君能保之昇絳霞。"]', '诗', 'shi', '', NULL, '求仙行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5466d66-fe78-40d7-a3e6-3bbb2cf58405', '古釵歎', '古釵歎', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["古釵墮井無顏色，百尺泥中今復得。","鳳凰宛轉有古儀，欲爲首飾不稱時。","女伴傳看不知主，羅袖拂拭生光輝。","蘭膏已盡股半折，雕文刻樣無年月。","雖離井底入匣中，不用還與墜時同。"]', '["古釵墮井無顏色，百尺泥中今复得。","鳳凰宛轉有古儀，欲爲首飾不稱时。","女伴傳看不知主，羅袖拂拭生光輝。","蘭膏已尽股半折，雕文刻樣無年月。","雖離井底入匣中，不用還與墜时同。"]', '诗', 'shi', '', NULL, '古釵歎 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b27631db-b481-41c5-94a8-e876dfebd693', '各東西', '各东西', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["遊人別，一東復一西。","出門相背兩不返，惟信車輪與馬蹄。","道路悠悠不知處，山高海闊誰辛苦。","遠遊不定難寄書，日日空尋別時語。","浮雲上天雨墮地，暫時會合終離異。","我今與子非一身，安得死生不相棄。"]', '["游人別，一东复一西。","出门相背兩不返，惟信车輪與马蹄。","道路悠悠不知处，山高海闊誰辛苦。","远游不定难寄书，日日空尋別时語。","浮云上天雨墮地，暫时會合終離異。","我今與子非一身，安得死生不相棄。"]', '诗', 'shi', '', NULL, '各東西 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f57cb22-3bda-45c2-b5cb-aeaa10a3376d', '節婦吟寄東平李司空師道', '節婦吟寄东平李司空師道', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["君知妾有夫，贈妾雙明珠。","感君纏綿意，繫在紅羅襦。","妾家高樓連苑起，良人執戟明光裏。","知君用心如日月，事夫誓擬同生死。"]', '["君知妾有夫，贈妾雙明珠。","感君纏綿意，繫在紅羅襦。","妾家高楼連苑起，良人執戟明光裏。","知君用心如日月，事夫誓擬同生死。"]', '诗', 'shi', '', NULL, '節婦吟寄東平李司空師道 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87ea2b40-5293-4d9d-97ef-aea11337a8cb', '讌客詞', '讌客词', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["上客不用顧金羈，主人有酒君莫違。","請君看取園中花，地上漸多枝上稀。","山頭樹影不見石，溪水無風應更碧。","人人齊醉起舞時，誰覺翻衣與倒幘。","明朝花盡人已去，此地獨來空繞樹。"]', '["上客不用顧金羈，主人有酒君莫違。","請君看取园中花，地上漸多枝上稀。","山头樹影不见石，溪水無风應更碧。","人人齊醉起舞时，誰覺翻衣與倒幘。","明朝花尽人已去，此地独来空繞樹。"]', '诗', 'shi', '', NULL, '讌客詞 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e203343-f5ca-44ee-9f86-6b7d806726a8', '永嘉行', '永嘉行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["黃頭鮮卑入洛陽，胡兒執戟升明堂。","晉家天子作降虜，公卿奔走如牛羊。","紫陌旌幡暗相觸，家家雞犬驚上屋。","婦人出門隨亂兵，夫死眼前不敢哭。","九州諸侯自顧土，無人領兵來護主。","北人避胡多在南，南人至今能晉語。"]', '["黄头鲜卑入洛陽，胡兒執戟升明堂。","晉家天子作降虜，公卿奔走如牛羊。","紫陌旌幡暗相觸，家家雞犬驚上屋。","婦人出门隨亂兵，夫死眼前不敢哭。","九州諸侯自顧土，無人領兵来護主。","北人避胡多在南，南人至今能晉語。"]', '诗', 'shi', '', NULL, '永嘉行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23ab2f0e-060c-40b8-b711-024666849c7f', '採蓮曲', '採蓮曲', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["秋江岸邊蓮子多，採蓮女兒凭船歌。","青房圓實齊戢戢，爭前競折漾微波。","試牽綠莖下尋藕，斷處絲多刺傷手。","白練束腰袖半卷，不插玉釵妝梳淺。","船中未滿度前洲，借問阿誰家住遠。","歸時共待暮潮上，自弄芙蓉還蕩槳。"]', '["秋江岸邊蓮子多，採蓮女兒凭船歌。","青房圓實齊戢戢，爭前競折漾微波。","試牽綠莖下尋藕，斷处絲多刺傷手。","白練束腰袖半卷，不插玉釵妝梳淺。","船中未满度前洲，借问阿誰家住远。","归时共待暮潮上，自弄芙蓉還蕩槳。"]', '诗', 'shi', '', NULL, '採蓮曲 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8cc1a6e-077f-41c5-9ad3-2f8af41a9a18', '傷歌行', '傷歌行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["黃門詔下促收捕，京兆尹繫御史府。","出門無復部曲隨，親戚相逢不容語。","辭成謫尉南海州，受命不得須臾留。","身着青衫騎惡馬，中門之外無送者。","郵夫防吏急諠驅，往往驚墮馬蹄下。","長安里中荒大宅，朱門已除十二戟。","高堂舞榭鎖管絃，美人遙望西南天。"]', '["黄门詔下促收捕，京兆尹繫御史府。","出门無复部曲隨，親戚相逢不容語。","辞成謫尉南海州，受命不得須臾留。","身着青衫騎惡马，中门之外無送者。","郵夫防吏急諠驱，往往驚墮马蹄下。","长安里中荒大宅，朱门已除十二戟。","高堂舞榭鎖管絃，美人遙望西南天。"]', '诗', 'shi', '', NULL, '傷歌行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0209bc51-5bf0-4413-af8a-a31388e1d542', '吳宮怨', '吳宮怨', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["吳宮四面秋江水，江清露白芙蓉死。","吳王醉後欲更衣，座上美人嬌不起。","宮中千門復萬戶，君恩反覆誰能數。","君心與妾既不同，徒向君前作歌舞。","茱萸滿宮紅實垂，秋風嫋嫋生繁枝。","姑蘇臺上夕燕罷，佗人侍寢還獨歸。","白日在天光在地，君今那得長相棄。"]', '["吳宮四面秋江水，江清露白芙蓉死。","吳王醉後欲更衣，座上美人嬌不起。","宮中千门复万戶，君恩反覆誰能數。","君心與妾既不同，徒向君前作歌舞。","茱萸满宮紅實垂，秋风嫋嫋生繁枝。","姑蘇台上夕燕罷，佗人侍寢還独归。","白日在天光在地，君今那得长相棄。"]', '诗', 'shi', '', NULL, '吳宮怨 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f1aa35f-ea49-46f3-9a38-cd901e54bd88', '北邙行', '北邙行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["洛陽北門北邙道，喪車轔轔入秋草。","車前齊唱薤露歌，高墳新起白峨峨。","朝朝暮暮人送葬，洛陽城中人更多。","千金立碑高百尺，終作誰家柱下石。","山頭松柏半無主，地下白骨多於土。","寒食家家送紙錢，烏鳶作窠銜上樹。","人居朝市未解愁，請君暫向北邙遊。"]', '["洛陽北门北邙道，喪车轔轔入秋草。","车前齊唱薤露歌，高墳新起白峨峨。","朝朝暮暮人送葬，洛陽城中人更多。","千金立碑高百尺，終作誰家柱下石。","山头松柏半無主，地下白骨多於土。","寒食家家送紙錢，烏鳶作窠銜上樹。","人居朝市未解愁，請君暫向北邙游。"]', '诗', 'shi', '', NULL, '北邙行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('203fcabb-90e3-433f-b578-f73c204c7059', '關山月', '关山月', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["秋月朗朗關山上，山中行人馬蹄響。","關山秋來雨雪多，行人見月唱邊歌。","海邊茫茫天氣白，胡兒夜度黃龍磧。","軍中探騎暮出城，伏兵暗處低旌戟。","溪水連天霜草平，野駝尋水磧中鳴。","隴頭風急雁不下，沙場苦戰多流星。","可憐萬國關山道，年年戰骨多秋草。"]', '["秋月朗朗关山上，山中行人马蹄响。","关山秋来雨雪多，行人见月唱邊歌。","海邊茫茫天氣白，胡兒夜度黄龙磧。","軍中探騎暮出城，伏兵暗处低旌戟。","溪水連天霜草平，野駝尋水磧中鳴。","隴头风急雁不下，沙場苦戰多流星。","可怜万国关山道，年年戰骨多秋草。"]', '诗', 'shi', '', NULL, '關山月 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5f74a11-92b2-42b3-b360-0caab73939b3', '隴頭行', '隴头行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["隴頭路斷人不行，胡騎夜入涼州城。","漢兵處處格鬬死，一朝盡沒隴西地。","驅我邊人胡中去，散放牛羊食禾黍。","去年中國養子孫，今著氈裘學胡語。","誰能更使李輕車，收取涼州入漢家。"]', '["隴头路斷人不行，胡騎夜入涼州城。","漢兵处处格鬬死，一朝尽沒隴西地。","驱我邊人胡中去，散放牛羊食禾黍。","去年中国養子孫，今著氈裘学胡語。","誰能更使李轻车，收取涼州入漢家。"]', '诗', 'shi', '', NULL, '隴頭行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e884efcb-d9c0-48b5-95b3-e644dba54b9b', '楚妃歎', '楚妃歎', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["湘雲初起江沉沉，君王遙在雲夢林。","江南雨多旌旗暗，臺下朝朝春水深。","章華殿前朝萬國，君心獨自無終極。","楚兵滿地能逐禽，誰用一身騁筋力。","西江若飜雲夢中，麋鹿死盡應還宮。"]', '["湘云初起江沉沉，君王遙在云梦林。","江南雨多旌旗暗，台下朝朝春水深。","章华殿前朝万国，君心独自無終極。","楚兵满地能逐禽，誰用一身騁筋力。","西江若飜云梦中，麋鹿死尽應還宮。"]', '诗', 'shi', '', NULL, '楚妃歎 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37c902a0-b08c-4226-81d1-c6600bec4220', '春日行', '春日行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["春日融融池上暖，竹牙出土蘭心短。","草堂晨起酒半醒，家僮報我園花滿。","頭上皮冠未曾整，直入花間不尋徑。","樹樹殷勤盡遶行，攀枝未徧春日暝。","不用積金著青天，不用服藥求神仙。","但願園裏花長好，一生飲酒花前老。"]', '["春日融融池上暖，竹牙出土蘭心短。","草堂晨起酒半醒，家僮報我园花满。","头上皮冠未曾整，直入花间不尋徑。","樹樹殷勤尽遶行，攀枝未徧春日暝。","不用積金著青天，不用服藥求神仙。","但願园裏花长好，一生饮酒花前老。"]', '诗', 'shi', '', NULL, '春日行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad0f966c-f139-4667-8533-dc2e49657492', '秋夜長', '秋夜长', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["秋天如水夜未央，天漢東西月色光。","愁人不寐畏枕席，暗蟲唧唧遶我傍。","荒城爲村無更聲，起看北斗天未明。","白露滿田風嫋嫋，千聲萬聲鶡鳥鳴。"]', '["秋天如水夜未央，天漢东西月色光。","愁人不寐畏枕席，暗蟲唧唧遶我傍。","荒城爲村無更声，起看北斗天未明。","白露满田风嫋嫋，千声万声鶡鸟鳴。"]', '诗', 'shi', '', NULL, '秋夜長 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eaf535f0-d599-4356-b69d-2ad5622e018f', '白鼉鳴', '白鼉鳴', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["天欲雨，有東風，南谿白鼉鳴窟中。","六月人家井無水，夜聞鼉聲人盡起。"]', '["天欲雨，有东风，南谿白鼉鳴窟中。","六月人家井無水，夜闻鼉声人尽起。"]', '诗', 'shi', '', NULL, '白鼉鳴 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd8604be-3ce1-4a4e-891b-c30857a16fa0', '洛陽行', '洛陽行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["洛陽宮闕當中州，城上峨峨十二樓。","翠華西去幾時返，梟巢乳鳥藏蟄燕。","御門空鎖五十年，稅彼農夫修玉殿。","六街朝暮鼓鼕鼕，禁兵持戟守空宮。","百官月月拜章表，驛使相續長安道。","上陽宮樹黃復綠，野豺入苑食麋鹿。","陌上老翁雙淚垂，共說武皇巡幸時。"]', '["洛陽宮闕當中州，城上峨峨十二楼。","翠华西去幾时返，梟巢乳鸟藏蟄燕。","御门空鎖五十年，稅彼農夫修玉殿。","六街朝暮鼓鼕鼕，禁兵持戟守空宮。","百官月月拜章表，驛使相續长安道。","上陽宮樹黄复綠，野豺入苑食麋鹿。","陌上老翁雙泪垂，共说武皇巡幸时。"]', '诗', 'shi', '', NULL, '洛陽行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d276f70-5659-4c8b-ae55-32fad946ad9e', '春江曲', '春江曲', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["春江無雲潮水平，蒲心出水鳧雛鳴。","長干夫壻愛遠行，自染春衣縫已成。","妾身生長金陵側，去年隨夫住江北。","春來未到父母家，舟小風多渡不得。","欲辭舅姑先問人，私向江頭祭水神。"]', '["春江無云潮水平，蒲心出水鳧雛鳴。","长干夫壻愛远行，自染春衣縫已成。","妾身生长金陵側，去年隨夫住江北。","春来未到父母家，舟小风多渡不得。","欲辞舅姑先问人，私向江头祭水神。"]', '诗', 'shi', '', NULL, '春江曲 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5639c076-ff59-4271-bfff-731b0ab3b719', '送遠曲', '送远曲', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["吳門向西流水長，水長柳暗煙茫茫。","行人送客各惆悵，話離敘別傾清觴。","吟絲竹，鳴笙簧，酒酣性逸歌猖狂。","行人告我挂帆去，此去何時返故鄉。","殷勤振衣兩相囑，世事近來還淺促。","願君看取吳門山，帶雪經春依舊綠。","行人行處求知親，送君去去徒酸辛。"]', '["吳门向西流水长，水长柳暗煙茫茫。","行人送客各惆悵，話離敘別傾清觴。","吟絲竹，鳴笙簧，酒酣性逸歌猖狂。","行人告我挂帆去，此去何时返故乡。","殷勤振衣兩相囑，世事近来還淺促。","願君看取吳门山，带雪經春依旧綠。","行人行处求知親，送君去去徒酸辛。"]', '诗', 'shi', '', NULL, '送遠曲 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ab92554-c207-49bf-a3d3-edb6b7f6b0bb', '塞下曲', '塞下曲', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["邊州八月修城堡，候騎先燒磧中草。","胡風吹沙度隴飛，隴頭林木無北枝。","將軍閱兵青塞下，鳴鼓逢逢促獵圍。","天寒山路石斷裂，白日不銷帳上雪。","烏孫國亂多降胡，詔使名王持漢節。","年年征戰不得閑，邊人殺盡唯空山。"]', '["邊州八月修城堡，候騎先燒磧中草。","胡风吹沙度隴飞，隴头林木無北枝。","將軍閱兵青塞下，鳴鼓逢逢促獵圍。","天寒山路石斷裂，白日不銷帳上雪。","烏孫国亂多降胡，詔使名王持漢節。","年年征戰不得闲，邊人殺尽唯空山。"]', '诗', 'shi', '', NULL, '塞下曲 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('593f42d7-3b06-4409-bd98-00513a326392', '董逃行', '董逃行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["洛陽城頭火曈曈，亂兵燒我天子宮。","宮城南面有深山，盡將老幼藏其間。","重巖爲屋橡爲食，丁男夜行候消息。","聞道官軍猶掠人，舊里如今歸未得。","董逃行，漢家幾時重太平。"]', '["洛陽城头火曈曈，亂兵燒我天子宮。","宮城南面有深山，尽將老幼藏其间。","重巖爲屋橡爲食，丁男夜行候消息。","闻道官軍猶掠人，旧里如今归未得。","董逃行，漢家幾时重太平。"]', '诗', 'shi', '', NULL, '董逃行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc5bbf65-131f-496a-bb4d-656e68f06918', '少年行', '少年行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["少年從獵出長楊，禁中新拜羽林郎。","獨對輦前射雙虎，君王手賜黃金璫。","日日鬬雞都市裏，贏得寶刀重刻字。","百里報仇夜出城，平明還在娼樓醉。","遙聞虜到平陵下，不待詔書行上馬。","斬得名王獻桂宮，封侯起第一日中。","不爲六郡良家子，百戰始取邊城功。"]', '["少年從獵出长楊，禁中新拜羽林郎。","独对輦前射雙虎，君王手賜黄金璫。","日日鬬雞都市裏，贏得寶刀重刻字。","百里報仇夜出城，平明還在娼楼醉。","遙闻虜到平陵下，不待詔书行上马。","斬得名王獻桂宮，封侯起第一日中。","不爲六郡良家子，百戰始取邊城功。"]', '诗', 'shi', '', NULL, '少年行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fef3b512-d4e0-473b-9b3a-b1d87831dfdd', '白頭吟', '白头吟', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["請君漆上琴，彈我白頭吟。","憶昔君前嬌笑語，兩情宛轉如縈素。","宮中爲我起高樓，更開花池種芳樹。","春天百草秋始衰，棄我不待白頭時。","羅襦玉珥色未暗，今朝已道不相宜。","揚州青銅作明鏡，暗中持照不見影。","人心回互自無窮，眼前好惡那能定。","君恩已去若再返，菖蒲花開月長滿。"]', '["請君漆上琴，彈我白头吟。","憶昔君前嬌笑語，兩情宛轉如縈素。","宮中爲我起高楼，更开花池種芳樹。","春天百草秋始衰，棄我不待白头时。","羅襦玉珥色未暗，今朝已道不相宜。","揚州青銅作明镜，暗中持照不见影。","人心回互自無窮，眼前好惡那能定。","君恩已去若再返，菖蒲花开月长满。"]', '诗', 'shi', '', NULL, '白頭吟 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a90fd6d4-03a9-408e-afd2-4c0246edabc3', '將軍行', '將軍行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["彈箏峽東有胡塵，天子擇日拜將軍。","蓬萊殿前賜六纛，還領禁兵爲部曲。","當朝受詔不辭家，夜向咸陽原上宿。","戰車彭彭旌旗動，三十六軍齊上隴。","隴頭戰勝夜亦行，分兵處處收舊城。","胡兒殺盡陰磧暮，擾擾唯有牛羊聲。","邊人親戚曾戰沒，今逐官軍收舊骨。","磧西行見萬里空，幕府獨奏將軍功。"]', '["彈箏峽东有胡塵，天子擇日拜將軍。","蓬萊殿前賜六纛，還領禁兵爲部曲。","當朝受詔不辞家，夜向咸陽原上宿。","戰车彭彭旌旗动，三十六軍齊上隴。","隴头戰勝夜亦行，分兵处处收旧城。","胡兒殺尽陰磧暮，擾擾唯有牛羊声。","邊人親戚曾戰沒，今逐官軍收旧骨。","磧西行见万里空，幕府独奏將軍功。"]', '诗', 'shi', '', NULL, '將軍行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd94f220-36a3-4e1d-9ee9-cde5f2b95b56', '賈客樂', '賈客乐', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["金陵向西賈客多，船中生長樂風波。","欲發移船近江口，船頭祭神各澆酒。","停杯共說遠行期，入蜀經蠻誰別離。","金多衆中爲上客，夜夜算緡眠獨遲。","秋江初月猩猩語，孤帆夜發瀟湘渚。","水工持檝防暗灘，直過山邊及前侶。","年年逐利西復東，姓名不在縣籍中。","農夫稅多長辛苦，棄業長爲販寶翁。"]', '["金陵向西賈客多，船中生长乐风波。","欲發移船近江口，船头祭神各澆酒。","停杯共说远行期，入蜀經蠻誰別離。","金多衆中爲上客，夜夜算緡眠独遲。","秋江初月猩猩語，孤帆夜發瀟湘渚。","水工持檝防暗灘，直過山邊及前侶。","年年逐利西复东，姓名不在縣籍中。","農夫稅多长辛苦，棄業长爲販寶翁。"]', '诗', 'shi', '', NULL, '賈客樂 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd210732-06c5-4b11-9db7-6a813d71ac4c', '羈旅行', '羈旅行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["遠客出門行路難，停車斂策在門端。","荒城無人霜滿路，野火燒橋不得度。","寒蟲入窟鳥歸巢，僮僕問我誰家去。","行尋田頭暝未息，雙轂長轅礙荆棘。","緣岡入澗投田家，主人舂米爲夜食。","晨雞喔喔茅屋傍，行人起掃車上霜。","舊山已別行已遠，身計未成難復返。","長安陌上相識稀，遙望天山白日晚。","誰能聽我辛苦行，爲向君前歌一聲。"]', '["远客出门行路难，停车斂策在门端。","荒城無人霜满路，野火燒橋不得度。","寒蟲入窟鸟归巢，僮僕问我誰家去。","行尋田头暝未息，雙轂长轅礙荆棘。","緣岡入澗投田家，主人舂米爲夜食。","晨雞喔喔茅屋傍，行人起掃车上霜。","旧山已別行已远，身計未成难复返。","长安陌上相識稀，遙望天山白日晚。","誰能听我辛苦行，爲向君前歌一声。"]', '诗', 'shi', '', NULL, '羈旅行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c3dbfc3-e271-4454-93b0-2abb419ac45c', '車遙遙', '车遙遙', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["征人遙遙出古城，雙輪齊動駟馬鳴。","山川無處不歸路，念君長作萬里行。","野田人稀秋草綠，日暮放馬車中宿。","驚麏游兔在我傍，獨唱鄉歌對僮僕。","君家大宅鳳城隅，年年道上隨行車。","願爲玉鑾繫華軾，終日有聲在君側。","門前舊轍久已平，無由復得君消息。"]', '["征人遙遙出古城，雙輪齊动駟马鳴。","山川無处不归路，念君长作万里行。","野田人稀秋草綠，日暮放马车中宿。","驚麏游兔在我傍，独唱乡歌对僮僕。","君家大宅鳳城隅，年年道上隨行车。","願爲玉鑾繫华軾，終日有声在君側。","门前旧轍久已平，無由复得君消息。"]', '诗', 'shi', '', NULL, '車遙遙 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa247c16-f33d-427b-ba30-20a1cd152f54', '妾薄命', '妾薄命', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["薄命婦，良家子，無事從軍去萬里。","漢家天子平四夷，護羌都尉裹尸歸。","念君此行爲死別，對君裁縫泉下衣。","與君一日爲夫婦，千年萬歲亦相守。","君愛龍城征戰功，妾願青樓歌樂同。","人生各各有所欲，詎得將心入君腹。"]', '["薄命婦，良家子，無事從軍去万里。","漢家天子平四夷，護羌都尉裹尸归。","念君此行爲死別，对君裁縫泉下衣。","與君一日爲夫婦，千年万歲亦相守。","君愛龙城征戰功，妾願青楼歌乐同。","人生各各有所欲，詎得將心入君腹。"]', '诗', 'shi', '', NULL, '妾薄命 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f8f39f3-51ea-40e5-89b5-d0f7575d7055', '朱鷺', '朱鷺', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["翩翩兮朱鷺，來汎春塘栖綠樹。","羽毛如翦色如染，遠飛欲下雙翅斂。","避人引子入深壍，動處水紋開灩灩。","誰知豪家網爾軀，不如飲啄江海隅。"]', '["翩翩兮朱鷺，来汎春塘栖綠樹。","羽毛如翦色如染，远飞欲下雙翅斂。","避人引子入深壍，动处水紋开灩灩。","誰知豪家網爾軀，不如饮啄江海隅。"]', '诗', 'shi', '', NULL, '朱鷺 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8df321b-96ae-4faa-8e6e-c1cce6bd3e07', '遠別離', '远別離', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["蓮葉團團杏花拆，長江鯉魚鬐鬣赤。","念君少年棄親戚，千里萬里獨爲客。","誰言遠別心不易，天星墜地能爲石。","幾時斷得城南陌，勿使居人有行役。"]', '["蓮葉團團杏花拆，长江鯉鱼鬐鬣赤。","念君少年棄親戚，千里万里独爲客。","誰言远別心不易，天星墜地能爲石。","幾时斷得城南陌，勿使居人有行役。"]', '诗', 'shi', '', NULL, '遠別離 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c612716-883d-459c-bc5a-ed043128792f', '楚宮行', '楚宮行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["章華宮中九月時，桂花半落紅橘垂。","江頭騎火照輦道，君王夜從雲夢歸。","霓旌鳳蓋到雙闕，臺上重重歌吹發。","千門萬戶開相當，燭籠左右列成行。","下輦更衣入洞房，洞房侍女盡焚香。","玉階羅幕微有霜，齊言此夕樂未央。","玉酒湛湛盈華觴，絲竹次第鳴中堂。","巴姬起舞向君王，迴身垂手結明璫。","願君千年萬年壽，朝出射麋夜飲酒。"]', '["章华宮中九月时，桂花半落紅橘垂。","江头騎火照輦道，君王夜從云梦归。","霓旌鳳蓋到雙闕，台上重重歌吹發。","千门万戶开相當，燭籠左右列成行。","下輦更衣入洞房，洞房侍女尽焚香。","玉階羅幕微有霜，齊言此夕乐未央。","玉酒湛湛盈华觴，絲竹次第鳴中堂。","巴姬起舞向君王，迴身垂手結明璫。","願君千年万年壽，朝出射麋夜饮酒。"]', '诗', 'shi', '', NULL, '楚宮行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a10fe79c-f316-4f75-8ea0-8f5fe5f239aa', '江南行', '江南行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["江南人家多橘樹，吳姬舟上織白苧。","土地卑濕饒蟲蛇，連木爲牌入江住。","江村亥日長爲市，落帆度橋來蒲裏。","清莎覆城竹爲屋，無井家家飲潮水。","長干午日沽春酒，高高酒旗懸江口。","娼樓兩岸臨水柵，夜唱竹枝留北客。","江南風土歡樂多，悠悠處處盡經過。"]', '["江南人家多橘樹，吳姬舟上织白苧。","土地卑濕饒蟲蛇，連木爲牌入江住。","江村亥日长爲市，落帆度橋来蒲裏。","清莎覆城竹爲屋，無井家家饮潮水。","长干午日沽春酒，高高酒旗懸江口。","娼楼兩岸臨水柵，夜唱竹枝留北客。","江南风土歡乐多，悠悠处处尽經過。"]', '诗', 'shi', '', NULL, '江南行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14e2e1e8-85c4-4b6b-92a8-e0d3501f1899', '烏夜啼引', '烏夜啼引', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["秦烏啼啞啞，夜啼長安吏人家。","吏人得罪囚在獄，傾家賣產將自贖。","少婦起聽夜啼烏，知是官家有赦書。","下牀心喜不重寐，未明上堂賀舅姑。","少婦語啼烏，汝啼慎勿虛。","借汝庭樹作高巢，年年不令傷爾雛。"]', '["秦烏啼啞啞，夜啼长安吏人家。","吏人得罪囚在獄，傾家賣產將自贖。","少婦起听夜啼烏，知是官家有赦书。","下牀心喜不重寐，未明上堂賀舅姑。","少婦語啼烏，汝啼慎勿虛。","借汝庭樹作高巢，年年不令傷爾雛。"]', '诗', 'shi', '', NULL, '烏夜啼引 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6234488-2cb9-426a-92fa-7bbf5c1d7811', '促促詞', '促促词', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["促促復促促，家貧夫婦歡不足。","今年爲人送租船，去年捕魚在江邊。","家中姑老子復小，自執吳綃輸稅錢。","家家桑麻滿地黑，念君一身空努力。","願教牛蹄團團羊角直，君身常在應不得。"]', '["促促复促促，家貧夫婦歡不足。","今年爲人送租船，去年捕鱼在江邊。","家中姑老子复小，自執吳綃輸稅錢。","家家桑麻满地黑，念君一身空努力。","願教牛蹄團團羊角直，君身常在應不得。"]', '诗', 'shi', '', NULL, '促促詞 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a002dfd5-85f1-451e-aff2-9971432d0a23', '宛轉行', '宛轉行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["華屋重翠幄，綺席雕象牀。","遠漏微更疎，薄衾中夜涼。","爐氣暗裴徊，寒燈背斜光。","妍姿結宵態，寢臂幽夢長。","宛轉復宛轉，憶君更未央。"]', '["华屋重翠幄，綺席雕象牀。","远漏微更疎，薄衾中夜涼。","爐氣暗裴徊，寒灯背斜光。","妍姿結宵態，寢臂幽梦长。","宛轉复宛轉，憶君更未央。"]', '诗', 'shi', '', NULL, '宛轉行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81bc9fa6-fd47-4437-a3fc-6a92a7ee4ded', '短歌行', '短歌行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["青天蕩蕩高且虛，上有白日無根株。","流光暫出還入地，使我年少不須臾。","與君相逢勿寂寞，衰老不復如今樂。","玉巵盛酒置君前，再拜願君千萬年。"]', '["青天蕩蕩高且虛，上有白日無根株。","流光暫出還入地，使我年少不須臾。","與君相逢勿寂寞，衰老不复如今乐。","玉巵盛酒置君前，再拜願君千万年。"]', '诗', 'shi', '', NULL, '短歌行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc737538-d2f9-44e0-b663-09d41410e9e8', '山頭鹿', '山头鹿', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["山頭鹿，角芟芟，尾促促。","貧兒多租輸不足，夫死未葬兒在獄。","早日熬熬蒸野岡，禾黍不收無獄糧。","縣家唯憂少軍食，誰能令爾無死傷。"]', '["山头鹿，角芟芟，尾促促。","貧兒多租輸不足，夫死未葬兒在獄。","早日熬熬蒸野岡，禾黍不收無獄糧。","縣家唯憂少軍食，誰能令爾無死傷。"]', '诗', 'shi', '', NULL, '山頭鹿 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b3d3cc0-6c4d-4c4b-a987-81ae9ac321f1', '湘江曲', '湘江曲', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["湘水無潮秋水闊，湘中月落行人發。","送人發，送人歸，白蘋茫茫鷓鴣飛。"]', '["湘水無潮秋水闊，湘中月落行人發。","送人發，送人归，白蘋茫茫鷓鴣飞。"]', '诗', 'shi', '', NULL, '湘江曲 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35ef0bea-62c9-40f6-b20e-d5c6b94e9383', '楚妃怨', '楚妃怨', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["梧桐葉下黃金井，橫架轆轤牽素綆。","美人初起天未明，手拂銀缾秋水冷。"]', '["梧桐葉下黄金井，橫架轆轤牽素綆。","美人初起天未明，手拂銀缾秋水冷。"]', '诗', 'shi', '', NULL, '楚妃怨 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58380015-6707-4e90-994d-c9aa635f835b', '離宮怨', '離宮怨', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["高堂別館連湘渚，長向春光開萬戶。","荆王去去不復來，宮中美人自歌舞。"]', '["高堂別館連湘渚，长向春光开万戶。","荆王去去不复来，宮中美人自歌舞。"]', '诗', 'shi', '', NULL, '離宮怨 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('651987af-2600-4410-a813-0d0f8ae28b66', '成都曲', '成都曲', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["錦江近西煙水綠，新雨山頭荔枝熟。","萬里橋邊多酒家，遊人愛向誰家宿。"]', '["錦江近西煙水綠，新雨山头荔枝熟。","万里橋邊多酒家，游人愛向誰家宿。"]', '诗', 'shi', '', NULL, '成都曲 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c605ce03-b734-46c5-ad73-7e8ddf072cf0', '寒塘曲', '寒塘曲', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["寒塘沉沉柳葉疎，水暗人語驚棲鳧。","舟中少年醉不起，持燭照水射遊魚。"]', '["寒塘沉沉柳葉疎，水暗人語驚棲鳧。","舟中少年醉不起，持燭照水射游鱼。"]', '诗', 'shi', '', NULL, '寒塘曲 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e283aa1c-56bb-490b-89dc-54e0a33465d4', '春別曲', '春別曲', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["長江春水綠堪染，蓮葉出水大如錢。","江頭橘樹君自種，那不長繫木蘭船。"]', '["长江春水綠堪染，蓮葉出水大如錢。","江头橘樹君自種，那不长繫木蘭船。"]', '诗', 'shi', '', NULL, '春別曲 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e878fb0-293f-4513-8624-4c57000921ff', '春堤曲', '春堤曲', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["野塘鵁鶄飛樹頭，綠蒲紫菱蓋碧流。","狂客誰家愛雲水，日日獨來城下遊。"]', '["野塘鵁鶄飞樹头，綠蒲紫菱蓋碧流。","狂客誰家愛云水，日日独来城下游。"]', '诗', 'shi', '', NULL, '春堤曲 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fe2eef5-dd56-4343-9f7f-a9c12499e22e', '烏棲曲', '烏棲曲', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["西山作宮潮滿池，宮鳥曉鳴茱萸枝。","吳姬採蓮自唱曲，君王昨夜舟中宿。"]', '["西山作宮潮满池，宮鸟晓鳴茱萸枝。","吳姬採蓮自唱曲，君王昨夜舟中宿。"]', '诗', 'shi', '', NULL, '烏棲曲 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8892f5b-777e-4221-be4b-65e43a230725', '雀飛多', '雀飞多', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["雀飛多，觸網羅，網羅高樹顛。","汝飛蓬蒿下，勿復投身網羅間。","粟積倉，禾在田。","巢之雛，望其母來還。"]', '["雀飞多，觸網羅，網羅高樹顛。","汝飞蓬蒿下，勿复投身網羅间。","粟積倉，禾在田。","巢之雛，望其母来還。"]', '诗', 'shi', '', NULL, '雀飛多 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4453d037-74ce-434d-8db0-1c63b6cc62b8', '泗水行', '泗水行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["泗水流急石纂纂，鯉魚上下紅尾短。","春冰銷散日華滿，行舟往來浮橋斷。","城邊魚市人早行，水煙漠漠多棹聲。"]', '["泗水流急石纂纂，鯉鱼上下紅尾短。","春冰銷散日华满，行舟往来浮橋斷。","城邊鱼市人早行，水煙漠漠多棹声。"]', '诗', 'shi', '', NULL, '泗水行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ce0a98f-2b5f-4cfe-bfc5-6967bfeb87a6', '廢居行', '廢居行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["胡馬崩騰滿阡陌，都人避亂唯空宅。","宅邊青桑垂宛宛，野蠶食葉還成繭。","黃雀銜草入燕窠，嘖嘖啾啾白日晚。","去時禾黍埋地中，飢兵掘土翻重重。","鴟梟養子庭樹上，曲牆空屋多旋風。","亂定幾人還本土，唯有官家重作主。"]', '["胡马崩腾满阡陌，都人避亂唯空宅。","宅邊青桑垂宛宛，野蠶食葉還成繭。","黄雀銜草入燕窠，嘖嘖啾啾白日晚。","去时禾黍埋地中，飢兵掘土翻重重。","鴟梟養子庭樹上，曲牆空屋多旋风。","亂定幾人還本土，唯有官家重作主。"]', '诗', 'shi', '', NULL, '廢居行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08a57734-3ccb-4ba5-bfe5-a33ac611c1af', '寄菖蒲', '寄菖蒲', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["石上生菖蒲，一寸十二節。","仙人勸我食，令我頭青面如雪。","逢人寄君一絳囊，書中不得傳此方。","君能來作棲霞侶，與君同入丹玄鄉。"]', '["石上生菖蒲，一寸十二節。","仙人勸我食，令我头青面如雪。","逢人寄君一絳囊，书中不得傳此方。","君能来作棲霞侶，與君同入丹玄乡。"]', '诗', 'shi', '', NULL, '寄菖蒲 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('667d82a0-09a4-4191-966a-ab32956894f5', '江村行', '江村行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["南塘水深蘆笋齊，下田種稻不作畦。","耕場磷磷在水底，短衣半染蘆中泥。","田頭刈莎結爲屋，歸來繫牛還獨宿。","水淹手足盡有瘡，山蝱遶身飛颺颺。","桑林椹黑蠶再眠，婦姑採桑不向田。","江南熱旱天氣毒，雨中移秧顏色鮮。","一年耕種長苦辛，田熟家家將賽神。"]', '["南塘水深蘆笋齊，下田種稻不作畦。","耕場磷磷在水底，短衣半染蘆中泥。","田头刈莎結爲屋，归来繫牛還独宿。","水淹手足尽有瘡，山蝱遶身飞颺颺。","桑林椹黑蠶再眠，婦姑採桑不向田。","江南熱旱天氣毒，雨中移秧顏色鲜。","一年耕種长苦辛，田熟家家將賽神。"]', '诗', 'shi', '', NULL, '江村行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9565e5d-ab7e-4293-88d0-ea04ad751c7b', '樵客吟', '樵客吟', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["上山採樵選枯樹，深處樵多出辛苦。","秋來野火燒櫟林，枝柯已枯堪採取。","斧聲坎坎在幽谷，採得齊梢青葛束。","日西待伴同下山，竹擔彎彎向身曲。","共知路傍多虎窟，未出深林不敢歇。","村西地暗狐兔行，稚子呌時相應聲。","採樵客，莫採松與栢。","松栢生枝直且堅，與君作屋成家宅。"]', '["上山採樵選枯樹，深处樵多出辛苦。","秋来野火燒櫟林，枝柯已枯堪採取。","斧声坎坎在幽谷，採得齊梢青葛束。","日西待伴同下山，竹擔彎彎向身曲。","共知路傍多虎窟，未出深林不敢歇。","村西地暗狐兔行，稚子呌时相應声。","採樵客，莫採松與栢。","松栢生枝直且堅，與君作屋成家宅。"]', '诗', 'shi', '', NULL, '樵客吟 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b89c7d43-a354-4903-bb84-b0e3fb1caba8', '湖南曲', '湖南曲', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["瀟湘多別離，風起芙蓉洲。","江上人已遠，夕陽滿中流。","鴛鴦東南飛，飛上青山頭。"]', '["瀟湘多別離，风起芙蓉洲。","江上人已远，夕陽满中流。","鴛鴦东南飞，飞上青山头。"]', '诗', 'shi', '', NULL, '湖南曲 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9f520a9-13e6-4379-b6fd-f86904c219d6', '春水曲', '春水曲', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["鴨鴨，觜唼唼。","青蒲生，春水狹。","蕩漾木蘭船，中有雙少年。","少年醉，鴨不起。"]', '["鴨鴨，觜唼唼。","青蒲生，春水狹。","蕩漾木蘭船，中有雙少年。","少年醉，鴨不起。"]', '诗', 'shi', '', NULL, '春水曲 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4a58042-0cb6-4881-83cf-6dbc6efda309', '雲童行', '云童行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["雲童童，白龍之尾垂江中。","今年天旱不作雨，水足牆上有禾黍。"]', '["云童童，白龙之尾垂江中。","今年天旱不作雨，水足牆上有禾黍。"]', '诗', 'shi', '', NULL, '雲童行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('029ff16c-6562-4d06-95d9-765045b30c69', '新桃行', '新桃行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["桃生葉婆娑，枝葉四向多。","高未出牆顛，蒿莧相凌摩。","植之三年餘，今年初試花。","秋來已成實，其陰良已嘉。","青蟬不來鳴，安得迅羽過。","常惡牽絲蟲，蒙冪成網羅。","顧託戲兒童，勿折吾柔柯。","明年結其實，磊磊充汝家。"]', '["桃生葉婆娑，枝葉四向多。","高未出牆顛，蒿莧相凌摩。","植之三年餘，今年初試花。","秋来已成實，其陰良已嘉。","青蟬不来鳴，安得迅羽過。","常惡牽絲蟲，蒙冪成網羅。","顧託戲兒童，勿折吾柔柯。","明年結其實，磊磊充汝家。"]', '诗', 'shi', '', NULL, '新桃行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3743cb0-1b04-48da-b200-539bed84707f', '憶遠曲', '憶远曲', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["水上山沈沈，征途復繞林。","途荒人行少，馬跡猶可尋。","雪中獨立樹，海口失侶禽。","離憂如長線，千里縈我心。"]', '["水上山沈沈，征途复繞林。","途荒人行少，马跡猶可尋。","雪中独立樹，海口失侶禽。","離憂如长線，千里縈我心。"]', '诗', 'shi', '', NULL, '憶遠曲 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06510f1b-fb30-43ee-a941-b013f96f6601', '長塘湖', '长塘湖', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["長塘湖，一斛水中半斛魚。","大魚如柳葉，小魚如針鋒，水濁誰能辨真龍。"]', '["长塘湖，一斛水中半斛鱼。","大鱼如柳葉，小鱼如針鋒，水濁誰能辨真龙。"]', '诗', 'shi', '', NULL, '長塘湖 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fa1686d-4d76-4113-9758-3dd042a3c36a', '廢瑟詞', '廢瑟词', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["古瑟在匣誰復識，玉柱顛倒朱絲黑。","千年曲譜不分明，樂府無人傳正聲。","秋蟲暗穿塵作色，腹中不辨工人名。","幾時天下復古樂，此瑟還奏雲門曲。"]', '["古瑟在匣誰复識，玉柱顛倒朱絲黑。","千年曲譜不分明，乐府無人傳正声。","秋蟲暗穿塵作色，腹中不辨工人名。","幾时天下复古乐，此瑟還奏云门曲。"]', '诗', 'shi', '', NULL, '廢瑟詞 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a45c880-aded-459f-a5a5-a67fab2f7665', '野居', '野居', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["貧賤易爲適，荒郊亦安居。","端坐無餘思，彌樂古人書。","秋田多良苗，野水多遊魚。","我無耒與網，安得充廩廚。","寒天白日短，簷下煖我軀。","四肢暫寬柔，中腸鬱不舒。","多病減志氣，爲客足憂虞。","況復苦時節，覽景獨踟躕。"]', '["貧賤易爲適，荒郊亦安居。","端坐無餘思，彌乐古人书。","秋田多良苗，野水多游鱼。","我無耒與網，安得充廩廚。","寒天白日短，簷下煖我軀。","四肢暫寬柔，中腸鬱不舒。","多病減志氣，爲客足憂虞。","況复苦时節，覽景独踟躕。"]', '诗', 'shi', '', NULL, '野居 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb2087c2-631e-4425-b387-f262110567a2', '西州', '西州', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["羌胡據西州，近甸無邊城。","山東收稅租，養我防塞兵。","胡騎來無時，居人常震驚。","嗟我五陵間，農者罷耘耕。","邊頭多殺傷，士卒難全形。","郡縣發丁役，丈夫各征行。","生男不能養，懼身有姓名。","良馬不念秣，烈士不苟營。","所願除國難，再逢天下平。"]', '["羌胡據西州，近甸無邊城。","山东收稅租，養我防塞兵。","胡騎来無时，居人常震驚。","嗟我五陵间，農者罷耘耕。","邊头多殺傷，士卒难全形。","郡縣發丁役，丈夫各征行。","生男不能養，懼身有姓名。","良马不念秣，烈士不苟營。","所願除国难，再逢天下平。"]', '诗', 'shi', '', NULL, '西州 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d166ac5-5466-46a8-943d-1d7df991eeee', '雜怨', '杂怨', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["切切重切切，秋風桂枝折。","人當少年嫁，我當少年別。","念君非征行，年年長遠途。","妾身甘獨歿，高堂有舅姑。","山川豈遙遠，行人自不返。"]', '["切切重切切，秋风桂枝折。","人當少年嫁，我當少年別。","念君非征行，年年长远途。","妾身甘独歿，高堂有舅姑。","山川豈遙远，行人自不返。"]', '诗', 'shi', '', NULL, '雜怨 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0665115d-dc5d-4bd0-9130-05dd7dc03d75', '惜花', '惜花', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["春潭足芳樹，水清不如素。","幽人愛華景，一一空山暮。","月出潭氣白，游魚暗衝石。","夜深春思多，酒醒山寂寂。"]', '["春潭足芳樹，水清不如素。","幽人愛华景，一一空山暮。","月出潭氣白，游鱼暗衝石。","夜深春思多，酒醒山寂寂。"]', '诗', 'shi', '', NULL, '惜花 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ffd2a7f-75c9-44e9-b3a9-2ea43014554c', '三原李氏園宴集', '三原李氏园宴集', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["暮春天早熱，邑居苦囂煩。","言從君子樂，樂彼李氏園。","園中有草堂，池引涇水泉。","開戶西北望，遠見嵯峨山。","借問主人翁，北州佐戎軒。","僕夫守舊宅，爲客侍華筵。","高懷有餘興，竹樹芳且鮮。","傾我所持觴，盡日共留連。","疎拙不偶俗，常喜形體閑。","況來幽棲地，能不重歎言。"]', '["暮春天早熱，邑居苦囂煩。","言從君子乐，乐彼李氏园。","园中有草堂，池引涇水泉。","开戶西北望，远见嵯峨山。","借问主人翁，北州佐戎軒。","僕夫守旧宅，爲客侍华筵。","高懷有餘兴，竹樹芳且鲜。","傾我所持觴，尽日共留連。","疎拙不偶俗，常喜形體闲。","況来幽棲地，能不重歎言。"]', '诗', 'shi', '', NULL, '三原李氏園宴集 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c490a58a-f973-4f3b-842c-472aeb3f660e', '沈千運舊居', '沈千運旧居', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["汝北君子宅，我來見頹墉。","亂離子孫盡，地屬鄰里翁。","土木被丘墟，谿路不連通。","舊井蔓草合，牛羊墜其中。","君辭天下書，放意任體躬。","一生不自力，家與逆旅同。","高議切星辰，餘聲激瘖聾。","方將旌舊閭，百世可封崇。","嗟其未積年，已爲荒林叢。","時豈無知音，不能崇此風。","浩蕩竟無覩，我將安所從。"]', '["汝北君子宅，我来见頹墉。","亂離子孫尽，地屬鄰里翁。","土木被丘墟，谿路不連通。","旧井蔓草合，牛羊墜其中。","君辞天下书，放意任體躬。","一生不自力，家與逆旅同。","高議切星辰，餘声激瘖聾。","方將旌旧閭，百世可封崇。","嗟其未積年，已爲荒林叢。","时豈無知音，不能崇此风。","浩蕩竟無覩，我將安所從。"]', '诗', 'shi', '', NULL, '沈千運舊居 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a888e890-ca60-47f3-a750-3df66492fb8c', '贈別孟郊', '贈別孟郊', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["歷歷天上星，沉沉水中萍。","幸當清秋夜，流影及微形。","君生衰俗間，立身如禮經。","純誠發新文，獨有金石聲。","才名振京國，歸省東南行。","停車楚城下，顧我不念程。","寶鏡曾墜水，不磨豈自明。","苦節居貧賤，所知賴友生。","歡會方別離，戚戚憂慮幷。","安得在一方，終老無送迎。"]', '["歷歷天上星，沉沉水中萍。","幸當清秋夜，流影及微形。","君生衰俗间，立身如禮經。","純誠發新文，独有金石声。","才名振京国，归省东南行。","停车楚城下，顧我不念程。","寶镜曾墜水，不磨豈自明。","苦節居貧賤，所知賴友生。","歡會方別離，戚戚憂慮幷。","安得在一方，終老無送迎。"]', '诗', 'shi', '', NULL, '贈別孟郊 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1451f8f4-ea3c-444d-8a2d-cb370fcad7d5', '臥疾', '臥疾', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["身病多思慮，亦讀神農經。","空堂留燈燭，四壁青熒熒。","羈旅隨人歡，貧賤還自輕。","今來問良醫，乃知病所生。","僮僕各憂愁，杵臼無停聲。","見我形顦顇，勸藥語丁寧。","春雨枕席冷，窗前新禽鳴。","開門起無力，遙愛雞犬行。","服藥察耳目，漸如醉者醒。","顧非達性命，猶爲憂患生。"]', '["身病多思慮，亦读神農經。","空堂留灯燭，四壁青熒熒。","羈旅隨人歡，貧賤還自轻。","今来问良醫，乃知病所生。","僮僕各憂愁，杵臼無停声。","见我形顦顇，勸藥語丁寧。","春雨枕席冷，窗前新禽鳴。","开门起無力，遙愛雞犬行。","服藥察耳目，漸如醉者醒。","顧非達性命，猶爲憂患生。"]', '诗', 'shi', '', NULL, '臥疾 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e482fbfb-c53a-4202-bde6-410b0cccc84f', '臥疾', '臥疾', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["身病始知道，卧讀神農經。","空房夜留燈，四壁青熒熒。","羇旅逐人歡，貧賤還自輕。","今來問良醫，乃知病所生。","僮僕各相憂，杵臼無停聲。","見我形憔悴，勸藥語丁寧。","春雨枕席冷，窗前新禽鳴。","開門起無力，遥愛鷄犬行。","服藥察耳目，漸覺如酒醒。","方悟養生者，不為憂患并。"]', '["身病始知道，卧读神農經。","空房夜留灯，四壁青熒熒。","羇旅逐人歡，貧賤還自轻。","今来问良醫，乃知病所生。","僮僕各相憂，杵臼無停声。","见我形憔悴，勸藥語丁寧。","春雨枕席冷，窗前新禽鳴。","开门起無力，遥愛鷄犬行。","服藥察耳目，漸覺如酒醒。","方悟養生者，不為憂患并。"]', '诗', 'shi', '', NULL, '臥疾 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('738d2629-b1b5-4688-bca6-bee1805a13fb', '別段生', '別段生', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["與子骨肉親，願言長相隨。","況離父母傍，從我學書詩。","同在道路間，講論亦未虧。","爲文於我前，日夕生光儀。","行役多疾疚，賴此相扶持。","貧賤事難拘，今日有別離。","我去秦城中，子留汴水湄。","離情兩飄斷，不異風中絲。","幼年獨爲客，舉動難得宜。","努力自修勵，常如見我時。","送我登山岡，再拜問還期。","還期在新年，勿怨歡會遲。"]', '["與子骨肉親，願言长相隨。","況離父母傍，從我学书诗。","同在道路间，講論亦未虧。","爲文於我前，日夕生光儀。","行役多疾疚，賴此相扶持。","貧賤事难拘，今日有別離。","我去秦城中，子留汴水湄。","離情兩飄斷，不異风中絲。","幼年独爲客，舉动难得宜。","努力自修勵，常如见我时。","送我登山岡，再拜问還期。","還期在新年，勿怨歡會遲。"]', '诗', 'shi', '', NULL, '別段生 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41070caa-7d85-4393-99c5-06abbda8eb37', '哭于鵠', '哭于鵠', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["青山無逸人，忽覺大國貧。","良玉沈幽泉，名爲天下珍。","野性疎時俗，再拜乃從軍。","氣高終不合，去如鏡上塵。","我初有章句，相合者唯君。","今來弔嗣子，對隴燒新文。","耕者廢其耜，爨者絕其薪。","苟無新衣裳，曷用光我身。","奠酒徒拜手，哀懷安能陳。","徒保金石韻，千載人所聞。"]', '["青山無逸人，忽覺大国貧。","良玉沈幽泉，名爲天下珍。","野性疎时俗，再拜乃從軍。","氣高終不合，去如镜上塵。","我初有章句，相合者唯君。","今来弔嗣子，对隴燒新文。","耕者廢其耜，爨者絕其薪。","苟無新衣裳，曷用光我身。","奠酒徒拜手，哀懷安能陳。","徒保金石韻，千載人所闻。"]', '诗', 'shi', '', NULL, '哭于鵠 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b5d6e14-a07e-422c-8a6d-c8e343ac8fc6', '南歸', '南归', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["促促念道路，四支不常寧。","行車未及家，天外非盡程。","骨肉待我歡，鄉里望我榮。","豈知東與西，顦顇竟無成。","人言苦夜長，窮者不念明。","懼離其寢寐，百憂傷性靈。","世道多險薄，相勸畢中誠。","遠遊無知音，不如商賈行。","達人有常志，愚夫勞所營。","舊山行去遠，言歸樂此生。"]', '["促促念道路，四支不常寧。","行车未及家，天外非尽程。","骨肉待我歡，乡里望我榮。","豈知东與西，顦顇竟無成。","人言苦夜长，窮者不念明。","懼離其寢寐，百憂傷性靈。","世道多險薄，相勸畢中誠。","远游無知音，不如商賈行。","達人有常志，愚夫勞所營。","旧山行去远，言归乐此生。"]', '诗', 'shi', '', NULL, '南歸 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8e69d3f-323e-4e7b-a49f-86254e40c644', '惜花', '惜花', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["濛濛庭樹花，墜地無顏色。","日暮東風起，飄揚玉階側。","殘蘂在猶稀，青條聳復直。","爲君結芳實，令君勿歎息。"]', '["濛濛庭樹花，墜地無顏色。","日暮东风起，飄揚玉階側。","殘蘂在猶稀，青條聳复直。","爲君結芳實，令君勿歎息。"]', '诗', 'shi', '', NULL, '惜花 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d462022f-de0f-450b-9410-3dacca1f1d4d', '奉和舍人叔直省時思琴', '奉和舍人叔直省时思琴', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["藹藹紫薇直，秋意深無窮。","滴瀝仙閣漏，肅穆禁池風。","竹月泛涼影，萱露澹幽叢。","地清物態勝，宵閑琴思通。","時屬雅音際，逈凝虛抱中。","達人掌樞近，常與隱默同。"]', '["藹藹紫薇直，秋意深無窮。","滴瀝仙閣漏，肅穆禁池风。","竹月泛涼影，萱露澹幽叢。","地清物態勝，宵闲琴思通。","时屬雅音際，逈凝虛抱中。","達人掌樞近，常與隐默同。"]', '诗', 'shi', '', NULL, '奉和舍人叔直省時思琴 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ea07b6e-b3fc-4f30-a95d-b2eb178f6193', '離婦', '離婦', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["十載來夫家，閨門無瑕疵。","薄命不生子，古制有分離。","託身言同穴，今日事乖違。","念君終棄捐，誰能強在茲。","堂上謝姑嫜，長跪請離辭。","姑嫜見我往，將決復沉疑。","與我古時釧，留我嫁時衣。","高堂拊我身，哭我於路陲。","昔日初爲婦，當君貧賤時。","晝夜常紡績，不得事蛾眉。","辛勤積黃金，濟君寒與飢。","洛陽買大宅，邯鄲買侍兒。","夫壻乘龍馬，出入有光儀。","將爲富家婦，永爲子孫資。","誰謂出君門，一身上車歸。","有子未必榮，無子坐生悲。","爲人莫作女，作女實難爲。"]', '["十載来夫家，閨门無瑕疵。","薄命不生子，古制有分離。","託身言同穴，今日事乖違。","念君終棄捐，誰能強在茲。","堂上謝姑嫜，长跪請離辞。","姑嫜见我往，將決复沉疑。","與我古时釧，留我嫁时衣。","高堂拊我身，哭我於路陲。","昔日初爲婦，當君貧賤时。","晝夜常紡績，不得事蛾眉。","辛勤積黄金，濟君寒與飢。","洛陽買大宅，邯鄲買侍兒。","夫壻乘龙马，出入有光儀。","將爲富家婦，永爲子孫資。","誰謂出君门，一身上车归。","有子未必榮，無子坐生悲。","爲人莫作女，作女實难爲。"]', '诗', 'shi', '', NULL, '離婦 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e43da74-cffe-4a4c-9b54-5781fe17153b', '懷別', '懷別', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["僕人驅行軒，低昂出我門。","離堂無留客，席上唯琴樽。","古道隨水曲，悠悠繞荒村。","遠程未奄息，別念在朝昏。","端居愁歲永，獨此留清景。","豈無經過人，尋歎門巷靜。","君如天上雨，我如屋下井。","無因同波流，願作形與影。"]', '["僕人驱行軒，低昂出我门。","離堂無留客，席上唯琴樽。","古道隨水曲，悠悠繞荒村。","远程未奄息，別念在朝昏。","端居愁歲永，独此留清景。","豈無經過人，尋歎门巷静。","君如天上雨，我如屋下井。","無因同波流，願作形與影。"]', '诗', 'shi', '', NULL, '懷別 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06cb49fe-1ae7-464b-8b6c-00fa521adf16', '學仙', '学仙', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["樓觀開朱門，樹木連房廊。","中有學仙人，少年休穀糧。","高冠如芙蓉，霞月披衣裳。","六時朝上清，佩玉紛鏗鏘。","自言天老書，祕覆雲錦囊。","百年度一人，妄泄有災殃。","每占有仙相，然後傳此方。","先生坐中堂，弟子跪四廂。","金刀截身髮，結誓焚靈香。","弟子得其訣，清齋入空房。","守神保元氣，動息隨天罡。","爐燒丹砂盡，晝夜候火光。","藥成既服食，計日乘鸞凰。","虛空無靈應，終歲安所望。","勤勞不能成，疑慮積心腸。","虛羸生疾疹，壽命多夭傷。","身歿懼人見，夜埋山谷傍。","求道慕靈異，不如守尋常。","先王知其非，戒之在國章。"]', '["楼观开朱门，樹木連房廊。","中有学仙人，少年休穀糧。","高冠如芙蓉，霞月披衣裳。","六时朝上清，佩玉紛鏗鏘。","自言天老书，祕覆云錦囊。","百年度一人，妄泄有災殃。","每占有仙相，然後傳此方。","先生坐中堂，弟子跪四廂。","金刀截身髮，結誓焚靈香。","弟子得其訣，清斋入空房。","守神保元氣，动息隨天罡。","爐燒丹砂尽，晝夜候火光。","藥成既服食，計日乘鸾凰。","虛空無靈應，終歲安所望。","勤勞不能成，疑慮積心腸。","虛羸生疾疹，壽命多夭傷。","身歿懼人见，夜埋山谷傍。","求道慕靈異，不如守尋常。","先王知其非，戒之在国章。"]', '诗', 'shi', '', NULL, '學仙 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3d7be3d-60a0-4af9-bafe-5ee50b68cd96', '夜懷', '夜懷', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["窮居積遠念，轉轉迷所歸。","幽蕙零落色，暗螢參差飛。","病生秋風簟，淚墮月明衣。","無愁坐寂寞，重使奏清徽。"]', '["窮居積远念，轉轉迷所归。","幽蕙零落色，暗螢參差飞。","病生秋风簟，泪墮月明衣。","無愁坐寂寞，重使奏清徽。"]', '诗', 'shi', '', NULL, '夜懷 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f962772-6ebf-4d81-bd74-2eb3e3736b85', '城南', '城南', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["漾漾南澗水，來作曲池流。","言尋參差島，曉榜輕盈舟。","萬繞不再止，千尋盡孤幽。","藻澀訝人重，萍分指魚游。","繁苗毯下垂，密箭翻迴輈。","曝鼈亂自墜，陰藤斜相鉤。","臥蔣黑米吐，翻芰紫角稠。","橋低競俯僂，亭近閑夷猶。","目爲逐勝朗，手因掇芳柔。","漸喜游來極，忽疑歸無由。","氣狀雖可覽，纖微諒難搜。","未聽主人賞，徒愛清華秋。"]', '["漾漾南澗水，来作曲池流。","言尋參差島，晓榜轻盈舟。","万繞不再止，千尋尽孤幽。","藻澀訝人重，萍分指鱼游。","繁苗毯下垂，密箭翻迴輈。","曝鼈亂自墜，陰藤斜相鉤。","臥蔣黑米吐，翻芰紫角稠。","橋低競俯僂，亭近闲夷猶。","目爲逐勝朗，手因掇芳柔。","漸喜游来極，忽疑归無由。","氣狀雖可覽，纖微諒难搜。","未听主人賞，徒愛清华秋。"]', '诗', 'shi', '', NULL, '城南 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afdc3f8f-8c56-42d8-a074-102b1811c2f9', '懷友', '懷友', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["人生有行役，誰能如草木。","別離感中懷，乃爲我桎梏。","百年受命短，光景良不足。","念我別離者，願懷日月促。","平地施道路，車馬往不復。","空知爲良田，秋望禾黍熟。","端居無儔侶，日夜禱耳目。","立身難自覺，常恐憂與辱。","窮賤無閑暇，疾痛多嗜欲。","我思攜手人，逍遙任心腹。"]', '["人生有行役，誰能如草木。","別離感中懷，乃爲我桎梏。","百年受命短，光景良不足。","念我別離者，願懷日月促。","平地施道路，车马往不复。","空知爲良田，秋望禾黍熟。","端居無儔侶，日夜禱耳目。","立身难自覺，常恐憂與辱。","窮賤無闲暇，疾痛多嗜欲。","我思携手人，逍遙任心腹。"]', '诗', 'shi', '', NULL, '懷友 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3b26734-32e3-4c56-a6d2-fa8a2a206fc0', '寄別者', '寄別者', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["寒天正飛雪，行人心切切。","同爲萬里客，中路忽離別。","別君汾水東，望君汾水西。","積雪無平岡，空山無人蹊。","羸馬時倚轅，行行未遑食。","下車勸僮僕，相顧莫歎息。","詎知佳期隔，離念終無極。"]', '["寒天正飞雪，行人心切切。","同爲万里客，中路忽離別。","別君汾水东，望君汾水西。","積雪無平岡，空山無人蹊。","羸马时倚轅，行行未遑食。","下车勸僮僕，相顧莫歎息。","詎知佳期隔，離念終無極。"]', '诗', 'shi', '', NULL, '寄別者 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c31c213f-6a36-4e49-b027-ba2f54bdb95e', '獻從兄', '獻從兄', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["悠悠旱天雲，不遠如飛塵。","賢達失其所，沉飄同衆人。","擢秀登王畿，出爲良使賓。","名高滿朝野，幼賤誰不聞。","一朝遇讒邪，流竄八九春。","詔書近遷移，組綬未及身。","冬井無寒冰，玉潤難爲焚。","虛懷日迢遙，榮辱常保純。","我念出游時，勿吟康樂文。","願言靈溪期，聊欲相依因。"]', '["悠悠旱天云，不远如飞塵。","賢達失其所，沉飄同衆人。","擢秀登王畿，出爲良使賓。","名高满朝野，幼賤誰不闻。","一朝遇讒邪，流竄八九春。","詔书近遷移，組綬未及身。","冬井無寒冰，玉潤难爲焚。","虛懷日迢遙，榮辱常保純。","我念出游时，勿吟康乐文。","願言靈溪期，聊欲相依因。"]', '诗', 'shi', '', NULL, '獻從兄 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b5cfd73-3877-4401-953e-d8cdf7510a91', '寄韓愈', '寄韓愈', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["野館非我室，新居未能安。","讀書避塵雜，方覺此地閑。","過郭多園墟，桑果相接連。","獨游竟寂寞，如寄空雲山。","夏景常晝毒，密林無鳴蟬。","臨溪一盥濯，清去肢體煩。","出林望曾城，君子在其間。","戎府草章記，阻我此遊盤。","憶昔西潭時，並持釣魚竿。","共忻得魴鯉，烹鱠于我前。","幾朝還復來，歎息時獨言。"]', '["野館非我室，新居未能安。","读书避塵杂，方覺此地闲。","過郭多园墟，桑果相接連。","独游竟寂寞，如寄空云山。","夏景常晝毒，密林無鳴蟬。","臨溪一盥濯，清去肢體煩。","出林望曾城，君子在其间。","戎府草章記，阻我此游盤。","憶昔西潭时，並持釣鱼竿。","共忻得魴鯉，烹鱠于我前。","幾朝還复来，歎息时独言。"]', '诗', 'shi', '', NULL, '寄韓愈 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb5eb77b-ff07-4b2b-87f7-40bf9ed03ca4', '贈姚怤', '贈姚怤', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["漏天日無光，澤土松不長。","君今職下位，志氣安得揚。","白髮文思壯，才爲國賢良。","無人識高韻，薦于天子傍。","況我愚朴姿，強趨利名場。","遠同干貴人，身舉固難彰。","昔逢汴水濱，今會習池陽。","豈無再來期，顧恐非此方。","願爲石中泉，不爲瓦上霜。","離別勿復道，所貴不相忘。"]', '["漏天日無光，澤土松不长。","君今職下位，志氣安得揚。","白髮文思壯，才爲国賢良。","無人識高韻，薦于天子傍。","況我愚朴姿，強趨利名場。","远同干貴人，身舉固难彰。","昔逢汴水濱，今會習池陽。","豈無再来期，顧恐非此方。","願爲石中泉，不爲瓦上霜。","離別勿复道，所貴不相忘。"]', '诗', 'shi', '', NULL, '贈姚怤 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42bd551f-6de1-4328-bac7-ca0a6e0c8d0e', '病中寄白學士拾遺', '病中寄白学士拾遺', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["秋亭病客眠，庭樹滿枝蟬。","涼風繞砌起，斜影入牀前。","梨晚漸紅墜，菊寒無黃鮮。","倦遊寂寞日，感歎蹉跎年。","塵歡久消委，華念獨迎延。","自寓城闕下，識君弟事焉。","君爲天子識，我方沉病纏。","無因會同語，悄悄中懷煎。"]', '["秋亭病客眠，庭樹满枝蟬。","涼风繞砌起，斜影入牀前。","梨晚漸紅墜，菊寒無黄鲜。","倦游寂寞日，感歎蹉跎年。","塵歡久消委，华念独迎延。","自寓城闕下，識君弟事焉。","君爲天子識，我方沉病纏。","無因會同語，悄悄中懷煎。"]', '诗', 'shi', '', NULL, '病中寄白學士拾遺 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29d665f0-6078-43cd-9d39-53ce82a28dc5', '雨中寄元宗簡', '雨中寄元宗簡', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["秋堂羸病起，盥漱風雨朝。","竹影冷疎澀，榆葉暗飄蕭。","街徑多墜果，牆隅有蛻蜩。","延瞻游步阻，獨坐閑思饒。","君居應如此，恨言相去遙。"]', '["秋堂羸病起，盥漱风雨朝。","竹影冷疎澀，榆葉暗飄蕭。","街徑多墜果，牆隅有蛻蜩。","延瞻游步阻，独坐闲思饒。","君居應如此，恨言相去遙。"]', '诗', 'shi', '', NULL, '雨中寄元宗簡 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96785bef-3908-4cb6-b354-c8168b1aed44', '野寺後池寄友', '野寺後池寄友', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["佛寺連野水，池幽夏景清。","繁木蔭芙蕖，時有水禽鳴。","通溪岸蹔斷，分渚流復縈。","伴僧鐘磬罷，月來池上明。","友人竟不至，東北見高城。","獨遊自寂寞，況此恨盈盈。"]', '["佛寺連野水，池幽夏景清。","繁木蔭芙蕖，时有水禽鳴。","通溪岸蹔斷，分渚流复縈。","伴僧鐘磬罷，月来池上明。","友人竟不至，东北见高城。","独游自寂寞，況此恨盈盈。"]', '诗', 'shi', '', NULL, '野寺後池寄友 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d88638c4-bbd6-42d4-a9fa-6ae172966ddd', '董公詩', '董公诗', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["誰主東諸侯，元臣隴西公。","旌節居汴水，四方皆承風。","在朝四十年，天下誦其功。","相我明天子，政成如太宗。","東方有艱難，公乃出臨戎。","單車入危城，慈惠安羣兇。","公謂其黨言，汝材甚驍雄。","爲我帳下士，出入衛我躬。","汝息爲我子，汝親我爲翁。","衆皆相顧泣，無不和且恭。","其父教子義，其妻勉夫忠。","不自以爲資，奉上但顒顒。","公衣無文采，公食少肥濃。","所憂在萬人，人實我寧空。","輕刑寬其政，薄賦弛租庸。","四郡三十城，不知歲饑凶。","天子臨朝喜，元老留在東。","今聞揚盛德，就安我大邦。","百辟賀明主，皇風恩賜重。","朝廷有大事，就決其所從。","海內既無虞，君臣方肅雍。","端居任僚屬，宴語常從容。","翩翩者蒼烏，來巢於林叢。","甘瓜生場圃，一蔕實連中。","田有嘉穀隴，異畝穗亦同。","賢人佐聖人，德與神明通。","感應我淳化，生瑞我地中。","昔者此州人，但矜馬與弓。","今公施德禮，自然威武崇。","公其共百年，受祿將無窮。"]', '["誰主东諸侯，元臣隴西公。","旌節居汴水，四方皆承风。","在朝四十年，天下誦其功。","相我明天子，政成如太宗。","东方有艱难，公乃出臨戎。","單车入危城，慈惠安羣兇。","公謂其黨言，汝材甚驍雄。","爲我帳下士，出入衛我躬。","汝息爲我子，汝親我爲翁。","衆皆相顧泣，無不和且恭。","其父教子義，其妻勉夫忠。","不自以爲資，奉上但顒顒。","公衣無文采，公食少肥濃。","所憂在万人，人實我寧空。","轻刑寬其政，薄賦弛租庸。","四郡三十城，不知歲饑凶。","天子臨朝喜，元老留在东。","今闻揚盛德，就安我大邦。","百辟賀明主，皇风恩賜重。","朝廷有大事，就決其所從。","海內既無虞，君臣方肅雍。","端居任僚屬，宴語常從容。","翩翩者蒼烏，来巢於林叢。","甘瓜生場圃，一蔕實連中。","田有嘉穀隴，異畝穗亦同。","賢人佐聖人，德與神明通。","感應我淳化，生瑞我地中。","昔者此州人，但矜马與弓。","今公施德禮，自然威武崇。","公其共百年，受祿將無窮。"]', '诗', 'shi', '', NULL, '董公詩 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7798a85b-ae35-4abc-bfb7-1c43940b2de2', '祭退之', '祭退之', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["嗚呼吏部公，其道誠巍昂。","生爲大賢姿，天使光我唐。","德義動鬼神，鑒用不可詳。","獨得雄直氣，發爲古文章。","學無不該貫，吏治得其方。","三次論諍退，其志亦剛強。","再使平山東，不言所謀臧。","薦待皆寒羸，但取其才良。","親朋有孤稚，婚姻有辦營。","如彼天有斗，人可爲信常。","如彼歲有春，物宜得華昌。","哀哉未申施，中年遽殂喪。","朝野良共哀，矧於知舊腸。","籍在江湖間，獨以道自將。","學詩爲衆體，久乃溢笈囊。","略無相知人，黯如霧中行。","北遊偶逢公，盛語相稱明。","名因天下聞，傳者入歌聲。","公領試士司，首薦到上京。","一來遂登科，不見苦貢場。","觀我性朴直，乃言及平生。","由茲類朋黨，骨肉無以當。","坐令其子拜，常呼幼時名。","追招不隔日，繼踐公之堂。","出則連轡馳，寢則對榻牀。","搜窮古今書，事事相酌量。","有花必同尋，有月必同望。","爲文先見草，釀熟偕共觴。","新果及異鮭，無不相待嘗。","到今三十年，曾不少異更。","公文爲時師，我亦有微聲。","而後之學者，或號爲韓張。","我官麟臺中，公爲大司成。","念此委末秩，不能力自揚。","特狀爲博士，始獲升朝行。","未幾享其資，遂忝南宮郎。","是事賴拯扶，如屋有棟梁。","去夏公請告，養疾城南莊。","籍時官休罷，兩月同游翔。","黃子陂岸曲，地曠氣色清。","新池四平漲，中有蒲荇香。","北臺臨稻疇，茂柳多陰涼。","板亭坐垂釣，煩苦稍已平。","共愛池上佳，聯句舒遐情。","偶有賈秀才，來茲亦同幷。","移船入南溪，東西縱篙撐。","劃波激船舷，前後飛鷗鶬。","回入潭瀨下，網截鯉與魴。","踏沙掇水蔬，樹下烝新秔。","日來相與嬉，不知暑日長。","柴翁攜童兒，聚觀於岸傍。","月中登高灘，星漢交垂芒。","釣車擲長綫，有獲齊歡驚。","夜闌乘馬歸，衣上草露光。","公爲遊谿詩，唱咏多慨慷。","自期此可老，結社於其鄉。","籍受新官詔，拜恩當入城。","公因同歸還，居處隔一坊。","中秋十六夜，魄圓天差晴。","公既相邀留，坐語於堦楹。","乃出二侍女，合彈琵琶箏。","臨風聽繁絲，忽遽聞再更。","顧我數來過，是夜涼難忘。","公疾浸日加，孺人視藥湯。","來候不得宿，出門每迴遑。","自是將重危，車馬候縱橫。","門僕皆逆遣，獨我到寢房。","公有曠達識，生死爲一綱。","及當臨終晨，意色亦不荒。","贈我珍重言，傲然委衾裳。","公比欲爲書，遺約有修章。","令我署其末，以爲後事程。","家人號於前，其書不果成。","子符奉其言，甚於親使令。","魯論未訖注，手跡今微茫。","新亭成未登，閉在莊西廂。","書札與詩文，重疊我笥盈。","頃息萬事盡，腸情多摧傷。","舊塋盟津北，野窆動鼓鉦。","柳車一出門，終天無迴箱。","籍貧無贈貲，曷用申哀誠。","衣器陳下帳，醪餌奠堂皇。","明靈庶鑒知，髣髴斯來饗。"]', '["嗚呼吏部公，其道誠巍昂。","生爲大賢姿，天使光我唐。","德義动鬼神，鑒用不可詳。","独得雄直氣，發爲古文章。","学無不該貫，吏治得其方。","三次論諍退，其志亦剛強。","再使平山东，不言所謀臧。","薦待皆寒羸，但取其才良。","親朋有孤稚，婚姻有辦營。","如彼天有斗，人可爲信常。","如彼歲有春，物宜得华昌。","哀哉未申施，中年遽殂喪。","朝野良共哀，矧於知旧腸。","籍在江湖间，独以道自將。","学诗爲衆體，久乃溢笈囊。","略無相知人，黯如霧中行。","北游偶逢公，盛語相稱明。","名因天下闻，傳者入歌声。","公領試士司，首薦到上京。","一来遂登科，不见苦貢場。","观我性朴直，乃言及平生。","由茲類朋黨，骨肉無以當。","坐令其子拜，常呼幼时名。","追招不隔日，繼踐公之堂。","出則連轡驰，寢則对榻牀。","搜窮古今书，事事相酌量。","有花必同尋，有月必同望。","爲文先见草，釀熟偕共觴。","新果及異鮭，無不相待嘗。","到今三十年，曾不少異更。","公文爲时師，我亦有微声。","而後之学者，或號爲韓張。","我官麟台中，公爲大司成。","念此委末秩，不能力自揚。","特狀爲博士，始獲升朝行。","未幾享其資，遂忝南宮郎。","是事賴拯扶，如屋有棟梁。","去夏公請告，養疾城南莊。","籍时官休罷，兩月同游翔。","黄子陂岸曲，地曠氣色清。","新池四平漲，中有蒲荇香。","北台臨稻疇，茂柳多陰涼。","板亭坐垂釣，煩苦稍已平。","共愛池上佳，聯句舒遐情。","偶有賈秀才，来茲亦同幷。","移船入南溪，东西縱篙撐。","劃波激船舷，前後飞鷗鶬。","回入潭瀨下，網截鯉與魴。","踏沙掇水蔬，樹下烝新秔。","日来相與嬉，不知暑日长。","柴翁携童兒，聚观於岸傍。","月中登高灘，星漢交垂芒。","釣车擲长綫，有獲齊歡驚。","夜闌乘马归，衣上草露光。","公爲游谿诗，唱咏多慨慷。","自期此可老，結社於其乡。","籍受新官詔，拜恩當入城。","公因同归還，居处隔一坊。","中秋十六夜，魄圓天差晴。","公既相邀留，坐語於堦楹。","乃出二侍女，合彈琵琶箏。","臨风听繁絲，忽遽闻再更。","顧我數来過，是夜涼难忘。","公疾浸日加，孺人視藥湯。","来候不得宿，出门每迴遑。","自是將重危，车马候縱橫。","门僕皆逆遣，独我到寢房。","公有曠達識，生死爲一綱。","及當臨終晨，意色亦不荒。","贈我珍重言，傲然委衾裳。","公比欲爲书，遺約有修章。","令我署其末，以爲後事程。","家人號於前，其书不果成。","子符奉其言，甚於親使令。","魯論未訖注，手跡今微茫。","新亭成未登，閉在莊西廂。","书札與诗文，重叠我笥盈。","頃息万事尽，腸情多摧傷。","旧塋盟津北，野窆动鼓鉦。","柳车一出门，終天無迴箱。","籍貧無贈貲，曷用申哀誠。","衣器陳下帳，醪餌奠堂皇。","明靈庶鑒知，髣髴斯来饗。"]', '诗', 'shi', '', NULL, '祭退之 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3920da1c-459c-4452-9d92-fd40d5ed5520', '薊北旅思', '薊北旅思', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["日日望鄉國，空謌白苧詞。","長因送人處，憶得別家時。","失意還獨語，多愁祗自知。","客亭門外柳，折盡向南枝。"]', '["日日望乡国，空謌白苧词。","长因送人处，憶得別家时。","失意還独語，多愁祗自知。","客亭门外柳，折尽向南枝。"]', '诗', 'shi', '', NULL, '薊北旅思 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07d2eddf-6b2a-4262-beeb-be35780550c8', '江南春', '江南春', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["江南楊柳春，日暖地無塵。","渡口過新雨，夜來生白蘋。","晴沙鳴乳燕，芳樹醉遊人。","向晚青山下，誰家祭水神。"]', '["江南楊柳春，日暖地無塵。","渡口過新雨，夜来生白蘋。","晴沙鳴乳燕，芳樹醉游人。","向晚青山下，誰家祭水神。"]', '诗', 'shi', '', NULL, '江南春 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6001b891-e317-4a8e-aa59-891d271b95a9', '西樓望月', '西楼望月', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["城西樓上月，復是雪晴時。","寒夜共來望，思鄉獨下遲。","幽光落水塹，淨色在霜枝。","明日千里去，此中還別離。"]', '["城西楼上月，复是雪晴时。","寒夜共来望，思乡独下遲。","幽光落水塹，淨色在霜枝。","明日千里去，此中還別離。"]', '诗', 'shi', '', NULL, '西樓望月 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edffb141-5b6c-4193-b6d2-a74bc02c0c11', '別鶴', '別鹤', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["雙鶴出雲谿，分飛各自迷。","空巢在松頂，折羽落紅泥。","尋水終不飲，逢林亦未棲。","別離應易老，萬里雨淒淒。"]', '["雙鹤出云谿，分飞各自迷。","空巢在松頂，折羽落紅泥。","尋水終不饮，逢林亦未棲。","別離應易老，万里雨淒淒。"]', '诗', 'shi', '', NULL, '別鶴 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('febead0e-6183-478c-88a5-bf9ef073d3ac', '江陵孝女', '江陵孝女', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["孝女獨垂髮，少年唯一身。","無家空托墓，主祭不從人。","相弔有行客，起廬無舊鄰。","江頭聞哭處，寂寂楚花春。"]', '["孝女独垂髮，少年唯一身。","無家空托墓，主祭不從人。","相弔有行客，起廬無旧鄰。","江头闻哭处，寂寂楚花春。"]', '诗', 'shi', '', NULL, '江陵孝女 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8aa4fd9-43ba-49ea-a4df-985b01c050a4', '山中古祠', '山中古祠', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["春草空祠墓，荒林唯鳥飛。","記年碑石在，經亂祭人稀。","野鼠緣朱帳，陰塵蓋畫衣。","近門潭水黑，時見宿龍歸。"]', '["春草空祠墓，荒林唯鸟飞。","記年碑石在，經亂祭人稀。","野鼠緣朱帳，陰塵蓋畫衣。","近门潭水黑，时见宿龙归。"]', '诗', 'shi', '', NULL, '山中古祠 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('027a565a-ada3-4e75-a195-e2322d952375', '漁陽將', '漁陽將', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["塞深沙草白，都護領燕兵。","放火燒奚帳，分旗築漢城。","下營看嶺勢，尋雪覺人行。","更向桑乾北，擒生問磧名。"]', '["塞深沙草白，都護領燕兵。","放火燒奚帳，分旗築漢城。","下營看嶺勢，尋雪覺人行。","更向桑乾北，擒生问磧名。"]', '诗', 'shi', '', NULL, '漁陽將 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92ea24f9-4780-4d8e-857a-3fd7b3778b39', '聽夜泉', '听夜泉', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["細泉深處落，夜久漸聞聲。","獨起出門聽，欲尋當澗行。","還疑隔林遠，復畏有風生。","月下長來此，無人亦到明。"]', '["細泉深处落，夜久漸闻声。","独起出门听，欲尋當澗行。","還疑隔林远，复畏有风生。","月下长来此，無人亦到明。"]', '诗', 'shi', '', NULL, '聽夜泉 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33fac8f1-e14d-4392-8357-a3f64ad78e09', '送南遷客', '送南遷客', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["去去遠遷客，瘴中衰病身。","青山無限路，白首不歸人。","海國戰騎象，蠻州市用銀。","一家分幾處，誰見日南春。"]', '["去去远遷客，瘴中衰病身。","青山無限路，白首不归人。","海国戰騎象，蠻州市用銀。","一家分幾处，誰见日南春。"]', '诗', 'shi', '', NULL, '送南遷客 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('737fcd5c-9ed6-4009-acc6-c279c05d3b55', '薊北春懷', '薊北春懷', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["渺渺水雲外，別來音信稀。","因逢過江使，却寄在家衣。","問路更愁遠，逢人空說歸。","今朝薊城北，又見塞鴻飛。"]', '["渺渺水云外，別来音信稀。","因逢過江使，却寄在家衣。","问路更愁远，逢人空说归。","今朝薊城北，又见塞鴻飞。"]', '诗', 'shi', '', NULL, '薊北春懷 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7002464-6e6b-4de1-b31c-0ec2612b4757', '思遠人', '思远人', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["野橋春水清，橋上送君行。","去去人應老，年年草自生。","出門看遠道，無信向邊城。","楊柳別離處，秋蟬今復鳴。"]', '["野橋春水清，橋上送君行。","去去人應老，年年草自生。","出门看远道，無信向邊城。","楊柳別離处，秋蟬今复鳴。"]', '诗', 'shi', '', NULL, '思遠人 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('718d4e6b-5a8e-4b47-9c24-6fea9c3b6ab8', '贈同溪客', '贈同溪客', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["幽居得相近，煙景每寥寥。","共伐臨谿樹，因爲過水橋。","自教青鶴舞，分採紫芝苗。","更愛南峰住，尋君路恐遙。"]', '["幽居得相近，煙景每寥寥。","共伐臨谿樹，因爲過水橋。","自教青鹤舞，分採紫芝苗。","更愛南峰住，尋君路恐遙。"]', '诗', 'shi', '', NULL, '贈同溪客 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef5c91ad-be60-4308-aa07-5d89717c9908', '望行人', '望行人', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["秋風窗下起，旅雁向南飛。","日日出門望，家家行客歸。","無因見邊使，空待寄寒衣。","獨倚青樓暮，煙深鳥雀稀。"]', '["秋风窗下起，旅雁向南飞。","日日出门望，家家行客归。","無因见邊使，空待寄寒衣。","独倚青楼暮，煙深鸟雀稀。"]', '诗', 'shi', '', NULL, '望行人 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9015c97-d2fe-4fdb-af24-1ce00e084986', '送宮人入道', '送宮人入道', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["舊寵昭陽裏，尋仙此最稀。","名初出宮籍，身未稱霞衣。","已別歌舞貴，長隨鸞鶴飛。","中官看入洞，空駕玉輪歸。"]', '["旧寵昭陽裏，尋仙此最稀。","名初出宮籍，身未稱霞衣。","已別歌舞貴，长隨鸾鹤飞。","中官看入洞，空駕玉輪归。"]', '诗', 'shi', '', NULL, '送宮人入道 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35f681d8-2999-41d7-ab86-4594e93e64e1', '送越客', '送越客', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["見說孤帆去，東南到會稽。","春雲剡溪口，殘月鏡湖西。","水鶴沙邊立，山鼯竹裏啼。","謝家曾住處，煙洞入應迷。"]', '["见说孤帆去，东南到會稽。","春云剡溪口，殘月镜湖西。","水鹤沙邊立，山鼯竹裏啼。","謝家曾住处，煙洞入應迷。"]', '诗', 'shi', '', NULL, '送越客 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b688d659-e36a-4c0d-85d5-a17054131575', '贈辟穀者', '贈辟穀者', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["學得餐霞法，逢人與小還。","身輕曾試鶴，力弱未離山。","無食犬猶在，不耕牛自閑。","朝朝空漱水，叩齒草堂間。"]', '["学得餐霞法，逢人與小還。","身轻曾試鹤，力弱未離山。","無食犬猶在，不耕牛自闲。","朝朝空漱水，叩齒草堂间。"]', '诗', 'shi', '', NULL, '贈辟穀者 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('932a8566-a2ee-48a7-878d-f051ca6fae15', '思江南舊遊', '思江南旧游', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["江臯三月時，花發石楠枝。","歸客應無數，春山自不知。","獨行愁道遠，迴信畏家移。","楊柳東西渡，茫茫欲問誰。"]', '["江臯三月时，花發石楠枝。","归客應無數，春山自不知。","独行愁道远，迴信畏家移。","楊柳东西渡，茫茫欲问誰。"]', '诗', 'shi', '', NULL, '思江南舊遊 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3df89b4-1a24-40b5-b668-1348f73d22c6', '夜到漁家', '夜到漁家', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["漁家在江口，潮水入柴扉。","行客欲投宿，主人猶未歸。","竹深村路遠，月出釣船稀。","遙見尋沙岸，春風動草衣。"]', '["漁家在江口，潮水入柴扉。","行客欲投宿，主人猶未归。","竹深村路远，月出釣船稀。","遙见尋沙岸，春风动草衣。"]', '诗', 'shi', '', NULL, '夜到漁家 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c8e7368-a276-45e8-99ea-c23474cf39ef', '送遠使', '送远使', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["揚旌過隴頭，隴水向西流。","塞路依山遠，戍城逢笛秋。","寒沙陰漫漫，疲馬去悠悠。","爲問征行將，誰封定遠侯。"]', '["揚旌過隴头，隴水向西流。","塞路依山远，戍城逢笛秋。","寒沙陰漫漫，疲马去悠悠。","爲问征行將，誰封定远侯。"]', '诗', 'shi', '', NULL, '送遠使 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ecad10d-5ac7-423f-b2bd-bb86f0e21b39', '不食姑', '不食姑', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["幾年山裏住，已作綠毛身。","護氣常稀語，存思自見神。","養龜同不食，留藥任生塵。","要問西王母，仙中第幾人。"]', '["幾年山裏住，已作綠毛身。","護氣常稀語，存思自见神。","養龟同不食，留藥任生塵。","要问西王母，仙中第幾人。"]', '诗', 'shi', '', NULL, '不食姑 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0872f854-66eb-44bb-b652-da68abad8429', '古苑杏花', '古苑杏花', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["廢苑杏花在，行人愁到時。","獨開新塹底，半露舊燒枝。","晚色連荒轍，低陰覆折碑。","茫茫古陵下，春盡又誰知。"]', '["廢苑杏花在，行人愁到时。","独开新塹底，半露旧燒枝。","晚色連荒轍，低陰覆折碑。","茫茫古陵下，春尽又誰知。"]', '诗', 'shi', '', NULL, '古苑杏花 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf8dca5e-f104-4fd7-a5ed-1820014b96d8', '送流人', '送流人', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["獨向長城北，黃雲暗塞天。","流名屬邊將，舊業作公田。","擁雪添軍壘，收冰當井泉。","知君住應老，須記別鄉年。"]', '["独向长城北，黄云暗塞天。","流名屬邊將，旧業作公田。","擁雪添軍壘，收冰當井泉。","知君住應老，須記別乡年。"]', '诗', 'shi', '', NULL, '送流人 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fa47ded-6d42-4689-a632-a5b472e3449e', '宿臨江驛', '宿臨江驛', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["楚驛南渡口，夜深來客稀。","月明見潮上，江靜覺鷗飛。","旅宿今已遠，此行殊未歸。","離家久無信，又聽擣寒衣。"]', '["楚驛南渡口，夜深来客稀。","月明见潮上，江静覺鷗飞。","旅宿今已远，此行殊未归。","離家久無信，又听擣寒衣。"]', '诗', 'shi', '', NULL, '宿臨江驛 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6af3fae-9f7c-44a7-8e8e-dda896fb8497', '送蠻客', '送蠻客', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["借問炎州客，天南幾日行。","江連惡谿路，山遶夜郎城。","柳葉瘴雲濕，桂叢蠻鳥聲。","知君却迴日，記得海花名。"]', '["借问炎州客，天南幾日行。","江連惡谿路，山遶夜郎城。","柳葉瘴云濕，桂叢蠻鸟声。","知君却迴日，記得海花名。"]', '诗', 'shi', '', NULL, '送蠻客 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9422679-c159-4bf1-8351-083069848194', '襄國別友', '襄国別友', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["曉色荒城下，相看秋草時。","獨遊無定計，不欲道來期。","別處去家遠，愁中驅馬遲。","歸人渡煙水，遙暎野棠枝。"]', '["晓色荒城下，相看秋草时。","独游無定計，不欲道来期。","別处去家远，愁中驱马遲。","归人渡煙水，遙暎野棠枝。"]', '诗', 'shi', '', NULL, '襄國別友 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a772176-3c27-442a-9fe6-5b44ed42423a', '送遠客', '送远客', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["南原相送處，秋水草還生。","同作憶鄉客，如今分路行。","因誰寄歸信，漸遠問前程。","明日重陽節，無人上古城。"]', '["南原相送处，秋水草還生。","同作憶乡客，如今分路行。","因誰寄归信，漸远问前程。","明日重陽節，無人上古城。"]', '诗', 'shi', '', NULL, '送遠客 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bd9b340-a9b3-4979-9c8e-fc36a559aa5d', '山中贈日南僧', '山中贈日南僧', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["獨向雙峰老，松門閉兩崖。","翻經上蕉葉，挂衲落藤花。","甃石新開井，穿林自種茶。","時逢海南客，蠻語問誰家。"]', '["独向雙峰老，松门閉兩崖。","翻經上蕉葉，挂衲落藤花。","甃石新开井，穿林自種茶。","时逢海南客，蠻語问誰家。"]', '诗', 'shi', '', NULL, '山中贈日南僧 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99c50768-61db-4ca5-9f28-810d9ce6fa72', '征西將', '征西將', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["黃沙北風起，半夜又翻營。","戰馬雪中宿，探人冰上行。","深山旗未展，陰磧鼓無聲。","幾道征西將，同收碎葉城。"]', '["黄沙北风起，半夜又翻營。","戰马雪中宿，探人冰上行。","深山旗未展，陰磧鼓無声。","幾道征西將，同收碎葉城。"]', '诗', 'shi', '', NULL, '征西將 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9c7c5b0-202f-42be-876d-62737b4daab0', '寄友人', '寄友人', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["憶在江南日，同遊三月時。","採茶尋遠澗，鬬鴨向春池。","送客沙頭宿，招僧竹裏碁。","如今各千里，無計得相隨。"]', '["憶在江南日，同游三月时。","採茶尋远澗，鬬鴨向春池。","送客沙头宿，招僧竹裏碁。","如今各千里，無計得相隨。"]', '诗', 'shi', '', NULL, '寄友人 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0173008-7777-4799-afe3-7e1b4bd1ce89', '送防秋將', '送防秋將', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["白首征西將，猶能射戟支。","元戎選部曲，軍吏換旌旗。","逐虜招降遠，開邊舊壘移。","重收隴外地，應似漢家時。"]', '["白首征西將，猶能射戟支。","元戎選部曲，軍吏換旌旗。","逐虜招降远，开邊旧壘移。","重收隴外地，應似漢家时。"]', '诗', 'shi', '', NULL, '送防秋將 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e511964-25aa-42b4-8e37-c92c84246060', '律僧', '律僧', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["苦行長不出，清羸最少年。","持齋唯一食，講律豈曾眠。","避草每移徑，濾蟲還入泉。","從來天竺法，到此幾人傳。"]', '["苦行长不出，清羸最少年。","持斋唯一食，講律豈曾眠。","避草每移徑，濾蟲還入泉。","從来天竺法，到此幾人傳。"]', '诗', 'shi', '', NULL, '律僧 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('037532de-b69a-4032-ae4b-63d8b28c101a', '山中秋夜', '山中秋夜', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["寂寂山景靜，幽人歸去遲。","橫琴當月下，壓酒及花時。","冷露濕茆屋，暗泉衝竹籬。","西峰採藥伴，此夕恨無期。"]', '["寂寂山景静，幽人归去遲。","橫琴當月下，壓酒及花时。","冷露濕茆屋，暗泉衝竹籬。","西峰採藥伴，此夕恨無期。"]', '诗', 'shi', '', NULL, '山中秋夜 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad33bfc2-7b45-48ee-b3ca-3891ab32a9f5', '送南客', '送南客', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["行路雨脩脩，青山盡海頭。","天涯人去遠，嶺北水空流。","夜市連銅柱，巢居屬象州。","來時舊相識，誰向日南遊。"]', '["行路雨脩脩，青山尽海头。","天涯人去远，嶺北水空流。","夜市連銅柱，巢居屬象州。","来时旧相識，誰向日南游。"]', '诗', 'shi', '', NULL, '送南客 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89c302eb-ba2e-41eb-ba00-12993d2db718', '宿江店', '宿江店', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["野店臨西浦，門前有橘花。","停燈待賈客，賣酒與漁家。","夜靜江水白，路迴山月斜。","閑尋泊船處，潮落見平沙。"]', '["野店臨西浦，门前有橘花。","停灯待賈客，賣酒與漁家。","夜静江水白，路迴山月斜。","闲尋泊船处，潮落见平沙。"]', '诗', 'shi', '', NULL, '宿江店 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adbd2eab-c9ed-4cdc-955d-8da6e2c6a143', '嶺表逢故人', '嶺表逢故人', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["過嶺萬餘里，旅遊經此稀。","相逢去家遠，共說幾時歸。","海上見花發，瘴中唯鳥飛。","炎州望鄉伴，自識北人衣。"]', '["過嶺万餘里，旅游經此稀。","相逢去家远，共说幾时归。","海上见花發，瘴中唯鸟飞。","炎州望乡伴，自識北人衣。"]', '诗', 'shi', '', NULL, '嶺表逢故人 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6082d88e-bb2c-4f44-aa55-1c9e3d526d87', '出塞', '出塞', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["秋塞雪初下，將軍遠出師。","分營長記火，放馬不收旗。","月冷邊帳濕，沙昏夜探遲。","征人皆白首，誰見滅胡時。"]', '["秋塞雪初下，將軍远出師。","分營长記火，放马不收旗。","月冷邊帳濕，沙昏夜探遲。","征人皆白首，誰见滅胡时。"]', '诗', 'shi', '', NULL, '出塞 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61242ff9-7965-47a3-9301-a882f67aa3b1', '寄紫閣隱者', '寄紫閣隐者', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["紫閣氣沉沉，先生住處深。","有人時得見，無路可相尋。","夜鹿伴茅屋，秋猿守栗林。","唯應採靈藥，更不別營心。"]', '["紫閣氣沉沉，先生住处深。","有人时得见，無路可相尋。","夜鹿伴茅屋，秋猿守栗林。","唯應採靈藥，更不別營心。"]', '诗', 'shi', '', NULL, '寄紫閣隱者 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('720e3d90-14ad-4393-9163-e063ab3e6783', '夜宿黑竈溪', '夜宿黑竈溪', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["夜到碧溪裏，無人秋月明。","逢幽更移宿，取伴亦探行。","花下紅泉色，雲西乳鶴聲。","明朝記歸處，石上自書名。"]', '["夜到碧溪裏，無人秋月明。","逢幽更移宿，取伴亦探行。","花下紅泉色，云西乳鹤声。","明朝記归处，石上自书名。"]', '诗', 'shi', '', NULL, '夜宿黑竈溪 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3e065ca-9346-44be-9ae2-323f9a8e243b', '古樹', '古樹', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["古樹枝柯少，枯來復幾春。","露根堪繫馬，空腹定藏人。","蠹節莓苔老，燒痕霹靂新。","若當江浦上，行客祭爲神。"]', '["古樹枝柯少，枯来复幾春。","露根堪繫马，空腹定藏人。","蠹節莓苔老，燒痕霹靂新。","若當江浦上，行客祭爲神。"]', '诗', 'shi', '', NULL, '古樹 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66dea4bd-06d8-498b-9c44-baf2170078f3', '送徐先生歸蜀', '送徐先生归蜀', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["日暮遠歸處，雲間仙觀鐘。","唯持青玉牒，獨立碧雞峰。","陰澗長收乳，寒泉舊養龍。","幾時因賣藥，得向海邊逢。"]', '["日暮远归处，云间仙观鐘。","唯持青玉牒，独立碧雞峰。","陰澗长收乳，寒泉旧養龙。","幾时因賣藥，得向海邊逢。"]', '诗', 'shi', '', NULL, '送徐先生歸蜀 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d4a4e82-31f1-4e92-810f-a34b82888813', '隱者', '隐者', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["先生已得道，市井亦容身。","救病自行藥，得錢多與人。","問年長不定，傳法又非真。","每見鄰家說，時聞使鬼神。"]', '["先生已得道，市井亦容身。","救病自行藥，得錢多與人。","问年长不定，傳法又非真。","每见鄰家说，时闻使鬼神。"]', '诗', 'shi', '', NULL, '隱者 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ffd476a-aeec-4e83-80e5-53ace51e3042', '送友人歸山', '送友人归山', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["出山成北首，重去結茅廬。","移石修廢井，埽龕盛舊書。","開田留杏樹，分洞與僧居。","長在幽峰裏，樵人見亦疎。"]', '["出山成北首，重去結茅廬。","移石修廢井，埽龕盛旧书。","开田留杏樹，分洞與僧居。","长在幽峰裏，樵人见亦疎。"]', '诗', 'shi', '', NULL, '送友人歸山 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fef09002-3a03-415d-8a92-e7e3b297e404', '霅溪西亭晚望', '霅溪西亭晚望', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["霅水碧悠悠，西亭柳岸頭。","夕陰生遠岫，斜照逐迴流。","此地動歸思，逢人方倦遊。","吳興耆舊盡，空見白蘋州。"]', '["霅水碧悠悠，西亭柳岸头。","夕陰生远岫，斜照逐迴流。","此地动归思，逢人方倦游。","吳兴耆旧尽，空见白蘋州。"]', '诗', 'shi', '', NULL, '霅溪西亭晚望 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff3993de-4db8-46b0-9930-079acb652167', '哭山中友人', '哭山中友人', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["入雲遙便哭，山友隔今生。","遶墓招魂魄，鐫巖記姓名。","犬因無主善，鶴爲見人鳴。","長說能尸解，多應別路行。"]', '["入云遙便哭，山友隔今生。","遶墓招魂魄，鐫巖記姓名。","犬因無主善，鹤爲见人鳴。","长说能尸解，多應別路行。"]', '诗', 'shi', '', NULL, '哭山中友人 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('856b1f2a-4307-414b-987a-f4735d7f96de', '答僧拄杖', '答僧拄杖', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["靈籐爲拄杖，白淨色如銀。","得自高僧手，將扶病客身。","春遊不騎馬，夜會亦呈人。","持此歸山去，深宜戴角巾。"]', '["靈籐爲拄杖，白淨色如銀。","得自高僧手，將扶病客身。","春游不騎马，夜會亦呈人。","持此归山去，深宜戴角巾。"]', '诗', 'shi', '', NULL, '答僧拄杖 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da540ddc-fd16-476b-8fa8-4706310f1759', '靈都觀李道士', '靈都观李道士', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["仙觀雨來靜，遶房瓊草春。","素書天上字，花洞古時人。","泥竈煮靈液，埽壇朝玉真。","幾迴遊閬苑，青節亦隨身。"]', '["仙观雨来静，遶房瓊草春。","素书天上字，花洞古时人。","泥竈煮靈液，埽壇朝玉真。","幾迴游閬苑，青節亦隨身。"]', '诗', 'shi', '', NULL, '靈都觀李道士 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91a0cff0-9b7f-4241-8980-5f0d6ef4b35b', '送韋評事歸華陰', '送韋評事归华陰', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["三峰西面住，出見世人稀。","老大誰相識，恓惶又獨歸。","埽窗秋菌落，開篋夜蛾飛。","若向雲中伴，還應着褐衣。"]', '["三峰西面住，出见世人稀。","老大誰相識，恓惶又独归。","埽窗秋菌落，开篋夜蛾飞。","若向云中伴，還應着褐衣。"]', '诗', 'shi', '', NULL, '送韋評事歸華陰 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e17e8a22-ed6d-40bb-8451-b95a597d7c6f', '送閩僧', '送閩僧', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["幾夏京城住，今朝獨遠歸。","修行四分律，護淨七條衣。","谿寺黃橙熟，沙田紫芋肥。","九龍潭上路，同去客應稀。"]', '["幾夏京城住，今朝独远归。","修行四分律，護淨七條衣。","谿寺黄橙熟，沙田紫芋肥。","九龙潭上路，同去客應稀。"]', '诗', 'shi', '', NULL, '送閩僧 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('039c3d4d-158d-4417-99e5-5ab66b78513d', '送海南客歸舊島', '送海南客归旧島', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["海上去應遠，蠻家雲島孤。","竹船來桂浦，山市賣魚鬚。","入國自獻寶，逢人多贈珠。","却歸春洞口，斬象祭天吳。"]', '["海上去應远，蠻家云島孤。","竹船来桂浦，山市賣鱼鬚。","入国自獻寶，逢人多贈珠。","却归春洞口，斬象祭天吳。"]', '诗', 'shi', '', NULL, '送海南客歸舊島 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cf0aafb-1902-4f56-8c86-1a92ee61158c', '登咸陽北寺樓', '登咸陽北寺楼', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["高秋原上寺，下馬一登臨。","渭水西來直，秦山南向深。","舊宮人不住，荒碣路難尋。","日暮涼風起，蕭條多遠心。"]', '["高秋原上寺，下马一登臨。","渭水西来直，秦山南向深。","旧宮人不住，荒碣路难尋。","日暮涼风起，蕭條多远心。"]', '诗', 'shi', '', NULL, '登咸陽北寺樓 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b99f297-4701-4256-91bc-e33a5ac4b67c', '送新羅使', '送新羅使', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["萬里爲朝使，離家今幾年。","應知舊行路，却上遠歸船。","夜泊避蛟窟，朝炊求島泉。","悠悠到鄉國，還望海西天。"]', '["万里爲朝使，離家今幾年。","應知旧行路，却上远归船。","夜泊避蛟窟，朝炊求島泉。","悠悠到乡国，還望海西天。"]', '诗', 'shi', '', NULL, '送新羅使 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6781ec4f-db7c-4fba-9ee0-ec6fa445733e', '宿廣德寺寄從舅', '宿廣德寺寄從舅', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["古寺客堂空，開簾四面風。","移牀動棲鶴，停燭聚飛蟲。","閑臥逐涼處，遠愁生靜中。","林西微月色，思與甯家同。"]', '["古寺客堂空，开簾四面风。","移牀动棲鹤，停燭聚飞蟲。","闲臥逐涼处，远愁生静中。","林西微月色，思與甯家同。"]', '诗', 'shi', '', NULL, '宿廣德寺寄從舅 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c05cbcb0-dd20-4466-945d-160774bc39bf', '宿邯鄲館寄馬磁州', '宿邯鄲館寄马磁州', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["孤客到空館，夜寒愁臥遲。","雖沽主人酒，不似在家時。","幾宿得歡笑，如今成別離。","明朝行更遠，迴望隔山陂。"]', '["孤客到空館，夜寒愁臥遲。","雖沽主人酒，不似在家时。","幾宿得歡笑，如今成別離。","明朝行更远，迴望隔山陂。"]', '诗', 'shi', '', NULL, '宿邯鄲館寄馬磁州 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bf18f08-22d2-4833-8b58-ff141dac39a4', '舟行寄李湖州', '舟行寄李湖州', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["客愁無次第，川路重辛勤。","藻密行舟澀，灣多轉檝頻。","薄遊空感惠，失計自憐貧。","賴有汀洲句，時時慰遠人。"]', '["客愁無次第，川路重辛勤。","藻密行舟澀，灣多轉檝頻。","薄游空感惠，失計自怜貧。","賴有汀洲句，时时慰远人。"]', '诗', 'shi', '', NULL, '舟行寄李湖州 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ade1893-a44d-45f0-9f9a-0bc2a7402a44', '送閑師歸江南', '送闲師归江南', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["徧住江南寺，隨緣到上京。","多生修律業，外學得詩名。","講殿偏追入，齋家別請行。","青楓鄉路遠，幾日盡歸程。"]', '["徧住江南寺，隨緣到上京。","多生修律業，外学得诗名。","講殿偏追入，斋家別請行。","青楓乡路远，幾日尽归程。"]', '诗', 'shi', '', NULL, '送閑師歸江南 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a74a799-c767-440f-82d1-182b33e3ddb1', '遊襄陽山寺', '游襄陽山寺', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["秋色江邊路，煙霞若有期。","寺貧無利施，僧老足慈悲。","薜荔侵禪窟，蝦蟆占浴池。","閑遊殊未徧，即是下山時。"]', '["秋色江邊路，煙霞若有期。","寺貧無利施，僧老足慈悲。","薜荔侵禪窟，蝦蟆占浴池。","闲游殊未徧，即是下山时。"]', '诗', 'shi', '', NULL, '遊襄陽山寺 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af210310-c5ef-4a03-ba98-783c415bc79e', '登城寄王秘書建', '登城寄王秘书建', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["聞君鶴嶺住，西望日依依。","遠客偏相憶，登城獨不歸。","十年爲道侶，幾處共柴扉。","今日煙霞外，人間得見稀。"]', '["闻君鹤嶺住，西望日依依。","远客偏相憶，登城独不归。","十年爲道侶，幾处共柴扉。","今日煙霞外，人间得见稀。"]', '诗', 'shi', '', NULL, '登城寄王秘書建 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95fd9611-2959-4b07-a810-cd374d48c49b', '送從弟戴玄往蘇州', '送從弟戴玄往蘇州', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["楊柳閶門路，悠悠水岸斜。","乘舟向山寺，着屐到漁家。","夜月紅柑樹，秋風白藕花。","江天詩景好，迴日莫令賒。"]', '["楊柳閶门路，悠悠水岸斜。","乘舟向山寺，着屐到漁家。","夜月紅柑樹，秋风白藕花。","江天诗景好，迴日莫令賒。"]', '诗', 'shi', '', NULL, '送從弟戴玄往蘇州 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eea19f4a-cb6d-4d23-8d27-367ed5c9b8f0', '送朱慶餘及第歸越', '送朱慶餘及第归越', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["東南歸路遠，幾日到鄉中。","有寺山皆遍，無家水不通。","湖聲蓮葉雨，野氣稻花風。","州縣知名久，爭邀與客同。"]', '["东南归路远，幾日到乡中。","有寺山皆遍，無家水不通。","湖声蓮葉雨，野氣稻花风。","州縣知名久，爭邀與客同。"]', '诗', 'shi', '', NULL, '送朱慶餘及第歸越 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e797885d-1d00-48f0-9f55-d45b2365608d', '過賈島野居', '過賈島野居', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["青門坊外住，行坐見南山。","此地去人遠，知君終日閑。","蛙聲籬落下，草色戶庭間。","好是經過處，唯愁暮獨還。"]', '["青门坊外住，行坐见南山。","此地去人远，知君終日闲。","蛙声籬落下，草色戶庭间。","好是經過处，唯愁暮独還。"]', '诗', 'shi', '', NULL, '過賈島野居 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b05412b6-d656-4086-a022-771c4f0dfad9', '酬韓庶子', '酬韓庶子', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["西街幽僻處，正與嬾相宜。","尋寺獨行遠，借書常送遲。","家貧無易事，身病足閑時。","寂寞誰相問，祗應君自知。"]', '["西街幽僻处，正與嬾相宜。","尋寺独行远，借书常送遲。","家貧無易事，身病足闲时。","寂寞誰相问，祗應君自知。"]', '诗', 'shi', '', NULL, '酬韓庶子 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f315ed4-b73a-4a9e-8799-98871c553726', '贈姚合少府', '贈姚合少府', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["病來辭赤縣，案上有丹經。","爲客燒茶竈，教兒埽竹亭。","詩成添舊卷，酒盡臥空缾。","闕下今遺逸，誰瞻隱士星。"]', '["病来辞赤縣，案上有丹經。","爲客燒茶竈，教兒埽竹亭。","诗成添旧卷，酒尽臥空缾。","闕下今遺逸，誰瞻隐士星。"]', '诗', 'shi', '', NULL, '贈姚合少府 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db6329f7-80c7-4e65-9ec2-ce7082d05c8c', '送僧遊五臺兼謁李司空', '送僧游五台兼謁李司空', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["遠去見雙節，因行上五臺。","化樓侵曉出，雪路向春開。","邊寺連峰去，胡兒聽法來。","定知巡禮後，解夏始應迴。"]', '["远去见雙節，因行上五台。","化楼侵晓出，雪路向春开。","邊寺連峰去，胡兒听法来。","定知巡禮後，解夏始應迴。"]', '诗', 'shi', '', NULL, '送僧遊五臺兼謁李司空 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dda2181-90a1-4622-8881-4aa7f81c1080', '送鄭秀才歸寧', '送鄭秀才归寧', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["桂檝彩爲衣，行當令節歸。","夕潮迷浦遠，晝雨見人稀。","野芰到時熟，江鷗泊處飛。","離琴一奏罷，山雨靄餘暉。"]', '["桂檝彩爲衣，行當令節归。","夕潮迷浦远，晝雨见人稀。","野芰到时熟，江鷗泊处飞。","離琴一奏罷，山雨靄餘暉。"]', '诗', 'shi', '', NULL, '送鄭秀才歸寧 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8300243-8092-4941-9161-3ed3764e0d0f', '送李評事遊越', '送李評事游越', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["未習風塵事，初爲吳越遊。","露沾湖草晚，日照海山秋。","梅市門何在，蘭亭水尚流。","西陵待潮處，知汝不勝愁。"]', '["未習风塵事，初爲吳越游。","露沾湖草晚，日照海山秋。","梅市门何在，蘭亭水尚流。","西陵待潮处，知汝不勝愁。"]', '诗', 'shi', '', NULL, '送李評事遊越 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e458cb0-2f60-4831-8ccd-049b303ad609', '夏日閑居', '夏日闲居', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["無事門多閉，偏知夏日長。","早蟬聲寂寞，新竹氣清涼。","閑對臨書案，看移曬藥牀。","自憐歸未得，猶寄在班行。"]', '["無事门多閉，偏知夏日长。","早蟬声寂寞，新竹氣清涼。","闲对臨书案，看移曬藥牀。","自怜归未得，猶寄在班行。"]', '诗', 'shi', '', NULL, '夏日閑居 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53e87e6e-3833-4b4e-9c99-9f25a7aa2185', '閑居', '闲居', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["東城南陌塵，紫幰與朱輪。","盡說無多事，能閑有幾人。","唯教推甲子，不信守庚申。","誰見衡門裏，終朝自在貧。"]', '["东城南陌塵，紫幰與朱輪。","尽说無多事，能闲有幾人。","唯教推甲子，不信守庚申。","誰见衡门裏，終朝自在貧。"]', '诗', 'shi', '', NULL, '閑居 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f62bdde6-4814-4e8b-a607-f5a2a9881d0d', '寄昭應王中丞', '寄昭應王中丞', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["借得街西宅，開門渭水頭。","長貧唯要健，漸老不禁愁。","獨憑藤書案，空懸竹酒鉤。","春風石甕寺，作意共君遊。"]', '["借得街西宅，开门渭水头。","长貧唯要健，漸老不禁愁。","独憑藤书案，空懸竹酒鉤。","春风石甕寺，作意共君游。"]', '诗', 'shi', '', NULL, '寄昭應王中丞 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00b5f102-385c-409f-959b-7a8485ea2430', '酬孫洛陽', '酬孫洛陽', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["家貧相遠住，齋館入時稀。","獨坐看書卷，閑行著褐衣。","早蟬庭笋老，新雨徑莎肥。","各離爭名地，無人見是非。"]', '["家貧相远住，斋館入时稀。","独坐看书卷，闲行著褐衣。","早蟬庭笋老，新雨徑莎肥。","各離爭名地，無人见是非。"]', '诗', 'shi', '', NULL, '酬孫洛陽 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56f869de-4152-49d1-978d-c9176ae97171', '送人任濟陰', '送人任濟陰', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["黃綬在腰下，知君非旅行。","將書報舊里，留褐與諸生。","贈別盡沽酒，惜歡多出城。","春風濟水上，候吏聽車聲。"]', '["黄綬在腰下，知君非旅行。","將书報旧里，留褐與諸生。","贈別尽沽酒，惜歡多出城。","春风濟水上，候吏听车声。"]', '诗', 'shi', '', NULL, '送人任濟陰 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5051ad05-212b-4755-9439-cb2e4201c39a', '晚春過崔駙馬東園', '晚春過崔駙马东园', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["閑園多好風，不意在街東。","早早詩名遠，長長酒性同。","竹香新雨後，鶯語落花中。","莫遣經過少，年光漸覺空。"]', '["闲园多好风，不意在街东。","早早诗名远，长长酒性同。","竹香新雨後，鶯語落花中。","莫遣經過少，年光漸覺空。"]', '诗', 'shi', '', NULL, '晚春過崔駙馬東園 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ca8af28-a319-4e0e-95a3-0e757323ebed', '夏日閑居', '夏日闲居', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["多病逢迎少，閑居又一年。","藥看辰日合，茶過卯時煎。","草長晴來地，蟲飛晚後天。","此時幽夢遠，不覺到山邊。"]', '["多病逢迎少，闲居又一年。","藥看辰日合，茶過卯时煎。","草长晴来地，蟲飞晚後天。","此时幽梦远，不覺到山邊。"]', '诗', 'shi', '', NULL, '夏日閑居 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('419f06f5-c946-42ea-b277-3ebbca04eaa6', '晚秋閑居', '晚秋闲居', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["獨坐高秋晚，蕭條足遠思。","家貧常畏客，身老轉憐兒。","萬種盡閑事，一生能幾時。","從來疎嬾性，應祗有僧知。"]', '["独坐高秋晚，蕭條足远思。","家貧常畏客，身老轉怜兒。","万種尽闲事，一生能幾时。","從来疎嬾性，應祗有僧知。"]', '诗', 'shi', '', NULL, '晚秋閑居 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5cade8e-f374-4251-a466-5661d1c7cef9', '和陸司業習靜寄所知', '和陸司業習静寄所知', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["幽室獨焚香，清晨下未央。","山開登竹閣，僧到出茶牀。","收拾新琴譜，封題舊藥方。","逍遙無別事，不似在班行。"]', '["幽室独焚香，清晨下未央。","山开登竹閣，僧到出茶牀。","收拾新琴譜，封題旧藥方。","逍遙無別事，不似在班行。"]', '诗', 'shi', '', NULL, '和陸司業習靜寄所知 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a1d7258-c61a-484e-a98c-49a7f09f3825', '酬韓祭酒雨中見寄', '酬韓祭酒雨中见寄', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["雨中愁不出，陰黑盡連宵。","屋濕唯添漏，泥深未放朝。","無芻憐馬瘦，少食信兒嬌。","聞道韓夫子，還同此寂寥。"]', '["雨中愁不出，陰黑尽連宵。","屋濕唯添漏，泥深未放朝。","無芻怜马瘦，少食信兒嬌。","闻道韓夫子，還同此寂寥。"]', '诗', 'shi', '', NULL, '酬韓祭酒雨中見寄 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79955b13-4756-4e3b-80e0-c8607d0721d1', '和裴僕射移官言志', '和裴僕射移官言志', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["身在勤勞地，常思放曠時。","功成歸聖主，位重委羣司。","看壘臺邊石，閑吟篋裏詩。","蒼生正瞻望，難與故山期。"]', '["身在勤勞地，常思放曠时。","功成归聖主，位重委羣司。","看壘台邊石，闲吟篋裏诗。","蒼生正瞻望，难與故山期。"]', '诗', 'shi', '', NULL, '和裴僕射移官言志 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe3e33eb-4b54-4644-80ee-ebfc7b8f5813', '酬白二十二舍人早春曲江見招', '酬白二十二舍人早春曲江见招', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["曲江冰欲盡，風日已恬和。","柳色看猶淺，泉聲覺漸多。","紫蒲生濕岸，青鴨戲新波。","仙掖高情客，相招共一過。"]', '["曲江冰欲尽，风日已恬和。","柳色看猶淺，泉声覺漸多。","紫蒲生濕岸，青鴨戲新波。","仙掖高情客，相招共一過。"]', '诗', 'shi', '', NULL, '酬白二十二舍人早春曲江見招 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd2c2b8d-0040-42ce-84dc-8ae12a14b91f', '和裴僕射朝回寄韓吏部', '和裴僕射朝回寄韓吏部', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["獨愛南關裏，山晴竹杪風。","從容朝早退，蕭灑客常通。","案曲新亭上，移花遠寺中。","唯應有吏部，詩酒每相同。"]', '["独愛南关裏，山晴竹杪风。","從容朝早退，蕭灑客常通。","案曲新亭上，移花远寺中。","唯應有吏部，诗酒每相同。"]', '诗', 'shi', '', NULL, '和裴僕射朝回寄韓吏部 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfc477d0-e9ae-44eb-9cd6-0f412289e9fc', '春日李舍人宅見兩省諸公唱和因書情即事', '春日李舍人宅见兩省諸公唱和因书情即事', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["又見帝城裏，東風天氣和。","官閑人事少，年長道情多。","紫掖發章句，青闈更詠歌。","誰知余寂寞，終日斷經過。"]', '["又见帝城裏，东风天氣和。","官闲人事少，年长道情多。","紫掖發章句，青闈更詠歌。","誰知余寂寞，終日斷經過。"]', '诗', 'shi', '', NULL, '春日李舍人宅見兩省諸公唱和因書情即事 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dff6637d-5cf1-4765-b063-9f5f7cc7be52', '和李僕射秋日病中作', '和李僕射秋日病中作', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["由來病根淺，易見藥功成。","曉日杵臼靜，涼風衣服輕。","猶疑少氣力，漸覺有心情。","獨倚紅藤杖，時時堦上行。"]', '["由来病根淺，易见藥功成。","晓日杵臼静，涼风衣服轻。","猶疑少氣力，漸覺有心情。","独倚紅藤杖，时时堦上行。"]', '诗', 'shi', '', NULL, '和李僕射秋日病中作 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba68f2e9-87b9-4ba1-84b6-bbe65c46bcd5', '早春病中', '早春病中', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["羸病及年初，心情不自如。","多申請假牒，祗送賀官書。","幽徑獨行步，白頭長嬾梳。","更憐晴日色，漸漸暖貧居。"]', '["羸病及年初，心情不自如。","多申請假牒，祗送賀官书。","幽徑独行步，白头长嬾梳。","更怜晴日色，漸漸暖貧居。"]', '诗', 'shi', '', NULL, '早春病中 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fe9e9d6-56f0-478d-a667-32f0e01eb0b8', '送嚴大夫之桂州', '送嚴大夫之桂州', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["旌斾過湘潭，幽奇得徧探。","莎城百越北，行路九疑南。","有地多生桂，無時不養蠶。","聽歌疑似曲，風俗自相諳。"]', '["旌斾過湘潭，幽奇得徧探。","莎城百越北，行路九疑南。","有地多生桂，無时不養蠶。","听歌疑似曲，风俗自相諳。"]', '诗', 'shi', '', NULL, '送嚴大夫之桂州 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b4a688f-ba5f-41a3-b9e5-53d51dda5daa', '詠懷', '詠懷', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["老去多悲事，非唯見二毛。","眼昏書字大，耳重覺聲高。","望月偏增思，尋山易發勞。","都無作官意，賴得在閑曹。"]', '["老去多悲事，非唯见二毛。","眼昏书字大，耳重覺声高。","望月偏增思，尋山易發勞。","都無作官意，賴得在闲曹。"]', '诗', 'shi', '', NULL, '詠懷 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dea6d052-14da-4ae4-ab06-2f7007c0f842', '使至藍谿驛寄太常王丞', '使至藍谿驛寄太常王丞', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["獨上七盤去，峰巒轉轉稠。","雲中迷象鼻，雨裏下箏頭。","水沒荒橋路，鴉啼古驛樓。","君今在城闕，肯見此中愁。"]', '["独上七盤去，峰巒轉轉稠。","云中迷象鼻，雨裏下箏头。","水沒荒橋路，鴉啼古驛楼。","君今在城闕，肯见此中愁。"]', '诗', 'shi', '', NULL, '使至藍谿驛寄太常王丞 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f2ce9af-aff0-480d-bf2a-86f46bee6362', '留別江陵王少府', '留別江陵王少府', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["迢迢山上路，病客獨行遲。","況此分手處，當君失意時。","寒林遠路驛，晚燒過荒陂。","別後空迴首，相逢未有期。"]', '["迢迢山上路，病客独行遲。","況此分手处，當君失意时。","寒林远路驛，晚燒過荒陂。","別後空迴首，相逢未有期。"]', '诗', 'shi', '', NULL, '留別江陵王少府 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdeadecf-359a-4514-96e5-fe73d31997e1', '贈海東僧', '贈海东僧', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["別家行萬里，自說過扶餘。","學得中州語，能爲外國書。","與醫收海藻，持咒取龍魚。","更問同來伴，天台幾處居。"]', '["別家行万里，自说過扶餘。","学得中州語，能爲外国书。","與醫收海藻，持咒取龙鱼。","更问同来伴，天台幾处居。"]', '诗', 'shi', '', NULL, '贈海東僧 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08a4cb9d-55b0-4d4b-912a-88b4d0af6a63', '寄漢陽故人', '寄漢陽故人', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["知君漢陽住，煙樹遠重重。","歸使雨中發，寄書燈下封。","同時買江塢，今日別雲松。","欲問新移處，青蘿最北峰。"]', '["知君漢陽住，煙樹远重重。","归使雨中發，寄书灯下封。","同时買江塢，今日別云松。","欲问新移处，青蘿最北峰。"]', '诗', 'shi', '', NULL, '寄漢陽故人 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7ec4374-24b2-4fd8-8d5d-5b3e9b63f3d4', '送安西將', '送安西將', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["萬里海西路，茫茫邊草秋。","計程沙塞口，望伴驛峰頭。","雪暗非時宿，沙深獨去愁。","塞鄉人易老，莫住近蕃州。"]', '["万里海西路，茫茫邊草秋。","計程沙塞口，望伴驛峰头。","雪暗非时宿，沙深独去愁。","塞乡人易老，莫住近蕃州。"]', '诗', 'shi', '', NULL, '送安西將 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b96f1531-8af5-4481-8e9a-669721f8d5a7', '題李山人幽居', '題李山人幽居', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["襄陽南郭外，茅屋一書生。","無事焚香坐，有時尋竹行。","畫苔藤杖細，踏石笋鞋輕。","應笑風塵客，區區逐世名。"]', '["襄陽南郭外，茅屋一书生。","無事焚香坐，有时尋竹行。","畫苔藤杖細，踏石笋鞋轻。","應笑风塵客，區區逐世名。"]', '诗', 'shi', '', NULL, '題李山人幽居 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1eee64c5-7701-40ea-abf5-97454c69ab05', '早春閑遊', '早春闲游', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["年長身多病，獨宜作冷官。","從來閑坐慣，漸覺出門難。","樹影新猶薄，池光晚尚寒。","遙聞有花發，騎馬暫行看。"]', '["年长身多病，独宜作冷官。","從来闲坐慣，漸覺出门难。","樹影新猶薄，池光晚尚寒。","遙闻有花發，騎马暫行看。"]', '诗', 'shi', '', NULL, '早春閑遊 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c24ee792-d69e-405f-aa1e-a7e31611ad03', '贈太常王建藤杖笋鞋', '贈太常王建藤杖笋鞋', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["蠻藤剪爲杖，楚笋結成鞋。","稱與詩人用，堪隨禮寺齋。","尋花入幽徑，步日下寒堦。","以此持相贈，君應愜素懷。"]', '["蠻藤剪爲杖，楚笋結成鞋。","稱與诗人用，堪隨禮寺斋。","尋花入幽徑，步日下寒堦。","以此持相贈，君應愜素懷。"]', '诗', 'shi', '', NULL, '贈太常王建藤杖笋鞋 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6662459-18b5-4cef-9f1b-e52a3b185b18', '和周贊善聞子規', '和周贊善闻子規', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["秦城啼楚鳥，遠思更紛紛。","況是街西夜，偏當雨裏聞。","應投最高樹，似隔數重雲。","此處誰能聽，遙知獨有君。"]', '["秦城啼楚鸟，远思更紛紛。","況是街西夜，偏當雨裏闻。","應投最高樹，似隔數重云。","此处誰能听，遙知独有君。"]', '诗', 'shi', '', NULL, '和周贊善聞子規 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d89890cd-b694-4aaf-bade-5f0491dc3003', '送李騎曹靈州歸覲', '送李騎曹靈州归覲', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["翩翩出上京，幾日到邊城。","漸覺風沙起，還將弓箭行。","席箕侵路暗，野馬見人驚。","軍府知歸慶，應教數騎迎。"]', '["翩翩出上京，幾日到邊城。","漸覺风沙起，還將弓箭行。","席箕侵路暗，野马见人驚。","軍府知归慶，應教數騎迎。"]', '诗', 'shi', '', NULL, '送李騎曹靈州歸覲 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c89ec01-675c-4238-a2a7-881f6636e733', '寒食夜寄姚侍郎', '寒食夜寄姚侍郎', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["貧官多寂寞，不異野人居。","作酒和山藥，教兒寫道書。","五湖歸去遠，百事病來疎。","況憶同懷者，寒庭月上初。"]', '["貧官多寂寞，不異野人居。","作酒和山藥，教兒寫道书。","五湖归去远，百事病来疎。","況憶同懷者，寒庭月上初。"]', '诗', 'shi', '', NULL, '寒食夜寄姚侍郎 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4fbbd3e-4001-421f-9a95-b300d522bada', '題清徹上人院', '題清徹上人院', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["古寺臨壇久，松間別起堂。","看添浴佛水，自合讀經香。","愛養無家客，多傳得效方。","過齋長不出，坐臥一繩牀。"]', '["古寺臨壇久，松间別起堂。","看添浴佛水，自合读經香。","愛養無家客，多傳得效方。","過斋长不出，坐臥一繩牀。"]', '诗', 'shi', '', NULL, '題清徹上人院 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35bfb080-c773-4bbe-9fe9-b4f1b30d6e4e', '寄靈一上人初歸雲門寺', '寄靈一上人初归云门寺', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["寒山白雲裏，法侶自招攜。","竹徑通城下，松門隔水西。","方同沃洲去，不作武陵迷。","髣髴遙看處，秋風是會稽。"]', '["寒山白云裏，法侶自招携。","竹徑通城下，松门隔水西。","方同沃洲去，不作武陵迷。","髣髴遙看处，秋风是會稽。"]', '诗', 'shi', '', NULL, '寄靈一上人初歸雲門寺 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffb034af-8dc0-47c1-9410-42e15f64b187', '和裴司空即事通簡舊僚', '和裴司空即事通簡旧僚', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["肅肅上台坐，四方皆仰風。","當朝奉明政，早日立元功。","獨對赤墀下，密宣黃閣中。","猶聞動高韻，思與舊僚同。"]', '["肅肅上台坐，四方皆仰风。","當朝奉明政，早日立元功。","独对赤墀下，密宣黄閣中。","猶闻动高韻，思與旧僚同。"]', '诗', 'shi', '', NULL, '和裴司空即事通簡舊僚 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bd50387-6d28-4394-921b-f30ee9ad37c9', '使回留別襄陽李司空', '使回留別襄陽李司空', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["江亭寒日晚，弦管有離聲。","從此一筵別，獨爲千里行。","遲遲戀恩德，役役限公程。","迴首吟新句，霜雲滿楚城。"]', '["江亭寒日晚，弦管有離声。","從此一筵別，独爲千里行。","遲遲戀恩德，役役限公程。","迴首吟新句，霜云满楚城。"]', '诗', 'shi', '', NULL, '使回留別襄陽李司空 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4260e861-cbbb-4ffd-a284-7ce1ced21787', '和戶部令狐尚書喜裴司空見招看雪', '和戶部令狐尚书喜裴司空见招看雪', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["南園新覆雪，上宰曉來看。","誰共登春榭，唯聞有地官。","色連山遠靜，氣與竹偏寒。","高韻更相應，寧同謌吹歡。"]', '["南园新覆雪，上宰晓来看。","誰共登春榭，唯闻有地官。","色連山远静，氣與竹偏寒。","高韻更相應，寧同謌吹歡。"]', '诗', 'shi', '', NULL, '和戶部令狐尚書喜裴司空見招看雪 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8d8cce8-9094-4f66-b7ac-dc0079ecaf02', '和裴司空以詩請刑部白侍郎雙鶴', '和裴司空以诗請刑部白侍郎雙鹤', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["皎皎仙家鶴，遠留閑宅中。","徘徊幽樹月，嘹唳小亭風。","丞相西園好，池塘野水通。","欲將來放此，賞望與賓同。"]', '["皎皎仙家鹤，远留闲宅中。","徘徊幽樹月，嘹唳小亭风。","丞相西园好，池塘野水通。","欲將来放此，賞望與賓同。"]', '诗', 'shi', '', NULL, '和裴司空以詩請刑部白侍郎雙鶴 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc340943-4814-45c0-931d-1bb90932e610', '同錦州胡郎中清明日對雨西亭宴', '同錦州胡郎中清明日对雨西亭宴', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["郡內開新火，高齋雨氣清。","惜花邀客賞，勸酒促歌聲。","共醉移芳席，留歡閉暮城。","政閑方宴語，琴筑任遙情。"]', '["郡內开新火，高斋雨氣清。","惜花邀客賞，勸酒促歌声。","共醉移芳席，留歡閉暮城。","政闲方宴語，琴筑任遙情。"]', '诗', 'shi', '', NULL, '同錦州胡郎中清明日對雨西亭宴 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('064fca51-bb9d-4137-8884-3c22e00f2736', '莊陵挽歌詞三首 一', '莊陵挽歌词三首 一', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["白日已昭昭，干戈亦漸消。","迎師親出道，從諫早臨朝。","佞倖威權薄，忠良寵錫饒。","丘陵今一變，無復白雲謠。"]', '["白日已昭昭，干戈亦漸消。","迎師親出道，從諫早臨朝。","佞倖威權薄，忠良寵錫饒。","丘陵今一变，無复白云謠。"]', '诗', 'shi', '', NULL, '莊陵挽歌詞三首 一 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cd12133-f003-4c64-917c-9b4e79378aea', '莊陵挽歌詞三首 二', '莊陵挽歌词三首 二', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["觀風欲巡洛，習戰亦開池。","始改三年政，旋聞七月期。","陵分內外使，官具吉凶儀。","渭北新園路，簫笳遠更悲。"]', '["观风欲巡洛，習戰亦开池。","始改三年政，旋闻七月期。","陵分內外使，官具吉凶儀。","渭北新园路，簫笳远更悲。"]', '诗', 'shi', '', NULL, '莊陵挽歌詞三首 二 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('739d2637-932f-4ef4-9ce8-63506681e838', '莊陵挽歌詞三首 三', '莊陵挽歌词三首 三', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["曉日龍車動，秋風閶闔開。","行帷六宮出，執紼萬方來。","慘慘郊原暮，遲遲挽唱哀。","空山煙雨夕，新陌遶陵臺。"]', '["晓日龙车动，秋风閶闔开。","行帷六宮出，執紼万方来。","慘慘郊原暮，遲遲挽唱哀。","空山煙雨夕，新陌遶陵台。"]', '诗', 'shi', '', NULL, '莊陵挽歌詞三首 三 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7786ba76-e740-4805-a0d0-2c6a96c6d787', '和左司元郎中秋居十首 一', '和左司元郎中秋居十首 一', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["選得閑坊住，秋來草樹肥。","風前卷筒簟，雨裏脫荷衣。","野客留方去，山童取藥歸。","非因入朝省，過此出門稀。"]', '["選得闲坊住，秋来草樹肥。","风前卷筒簟，雨裏脫荷衣。","野客留方去，山童取藥归。","非因入朝省，過此出门稀。"]', '诗', 'shi', '', NULL, '和左司元郎中秋居十首 一 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('551395d4-51fe-4705-b567-6374534816d2', '和左司元郎中秋居十首 二', '和左司元郎中秋居十首 二', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["有地唯栽竹，無池亦養鵝。","學書求墨跡，釀酒愛朝和。","古鏡銘文淺，神方謎語多。","居貧閑自樂，豪客莫相過。"]', '["有地唯栽竹，無池亦養鵝。","学书求墨跡，釀酒愛朝和。","古镜銘文淺，神方謎語多。","居貧闲自乐，豪客莫相過。"]', '诗', 'shi', '', NULL, '和左司元郎中秋居十首 二 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c601a045-73d5-4843-a0c9-ed31f7de853a', '和左司元郎中秋居十首 三', '和左司元郎中秋居十首 三', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["閑來松菊地，未省有埃塵。","直去多將藥，朝迴不訪人。","見僧收酒器，迎客換紗巾。","更恐登清要，難成自在身。"]', '["闲来松菊地，未省有埃塵。","直去多將藥，朝迴不訪人。","见僧收酒器，迎客換紗巾。","更恐登清要，难成自在身。"]', '诗', 'shi', '', NULL, '和左司元郎中秋居十首 三 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5505d72c-bb20-43c5-afd1-9fda4da75819', '和左司元郎中秋居十首 四', '和左司元郎中秋居十首 四', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["自知清靜好，不要問時豪。","就石安琴枕，穿松壓酒槽。","山晴因月甚，詩語入秋高。","身外無餘事，唯應筆硯勞。"]', '["自知清静好，不要问时豪。","就石安琴枕，穿松壓酒槽。","山晴因月甚，诗語入秋高。","身外無餘事，唯應笔硯勞。"]', '诗', 'shi', '', NULL, '和左司元郎中秋居十首 四 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6eceba24-f1f3-4729-8e8b-40f146385bf2', '和左司元郎中秋居十首 五', '和左司元郎中秋居十首 五', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["閑堂新埽灑，稱是早秋天。","書客多呈帖，琴僧與合弦。","莎臺乘晚上，竹院就涼眠。","終日無忙事，還應似得仙。"]', '["闲堂新埽灑，稱是早秋天。","书客多呈帖，琴僧與合弦。","莎台乘晚上，竹院就涼眠。","終日無忙事，還應似得仙。"]', '诗', 'shi', '', NULL, '和左司元郎中秋居十首 五 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2182dbf8-4ba1-4781-ac36-949a4e5f5056', '和左司元郎中秋居十首 六', '和左司元郎中秋居十首 六', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["醉倚斑藤杖，閑眠癭木牀。","案頭行氣訣，爐裏降真香。","尚儉經營少，居閑意思長。","秋茶莫夜飲，新自作松漿。"]', '["醉倚斑藤杖，闲眠癭木牀。","案头行氣訣，爐裏降真香。","尚儉經營少，居闲意思长。","秋茶莫夜饮，新自作松漿。"]', '诗', 'shi', '', NULL, '和左司元郎中秋居十首 六 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1055b759-2c85-4724-917c-d95410153657', '和左司元郎中秋居十首 七', '和左司元郎中秋居十首 七', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["每憶舊山居，新教上墨圖。","晚花迴地種，好酒問人沽。","夜後開朝簿，申前發省符。","爲郎凡幾歲，已見白髭鬚。"]', '["每憶旧山居，新教上墨圖。","晚花迴地種，好酒问人沽。","夜後开朝簿，申前發省符。","爲郎凡幾歲，已见白髭鬚。"]', '诗', 'shi', '', NULL, '和左司元郎中秋居十首 七 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18cce48e-12e5-44d8-80b4-47a6d962accf', '和左司元郎中秋居十首 八', '和左司元郎中秋居十首 八', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["菊地纔通履，茶房不壘階。","憑醫看蜀藥，寄信覓吳鞋。","盡得仙家法，多隨道客齋。","本無榮辱意，不是學安排。"]', '["菊地纔通履，茶房不壘階。","憑醫看蜀藥，寄信覓吳鞋。","尽得仙家法，多隨道客斋。","本無榮辱意，不是学安排。"]', '诗', 'shi', '', NULL, '和左司元郎中秋居十首 八 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f75c67e-70b9-42e7-87e4-ee893aa67d91', '和左司元郎中秋居十首 九', '和左司元郎中秋居十首 九', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["林下無拘束，閑行放性靈。","好時開藥竈，高處置琴亭。","更撰居山記，唯尋相鶴經。","初當授衣假，無吏挽門鈴。"]', '["林下無拘束，闲行放性靈。","好时开藥竈，高处置琴亭。","更撰居山記，唯尋相鹤經。","初當授衣假，無吏挽门鈴。"]', '诗', 'shi', '', NULL, '和左司元郎中秋居十首 九 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a6e417b-c863-48ae-8443-1e3447abbc78', '和左司元郎中秋居十首 十', '和左司元郎中秋居十首 十', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["客散高齋晚，東園景象偏。","晴明猶有蝶，涼冷漸無蟬。","藤折霜來子，蝸行雨後涎。","新詩纔上卷，已得滿城傳。"]', '["客散高斋晚，东园景象偏。","晴明猶有蝶，涼冷漸無蟬。","藤折霜来子，蝸行雨後涎。","新诗纔上卷，已得满城傳。"]', '诗', 'shi', '', NULL, '和左司元郎中秋居十首 十 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf94838a-f165-449a-9069-c9564727a8ae', '經王處士原居', '經王处士原居', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["舊宅誰相近，唯僧近竹關。","庭閑雲滿井，窗曉雪通山。","來客半留宿，借書多寄還。","明時未中歲，莫便一生閑。"]', '["旧宅誰相近，唯僧近竹关。","庭闲云满井，窗晓雪通山。","来客半留宿，借书多寄還。","明时未中歲，莫便一生闲。"]', '诗', 'shi', '', NULL, '經王處士原居 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fce4765-c327-4724-a0a1-807b00cc6ca1', '不食仙姑山房', '不食仙姑山房', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["寂寂花枝裏，草堂唯素琴。","因山曾改眼，見客不言心。","月出溪路靜，鶴鳴雲樹深。","丹砂如可學，便欲住幽林。"]', '["寂寂花枝裏，草堂唯素琴。","因山曾改眼，见客不言心。","月出溪路静，鹤鳴云樹深。","丹砂如可学，便欲住幽林。"]', '诗', 'shi', '', NULL, '不食仙姑山房 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1b45254-d4b4-44aa-a068-b4027219ccdf', '江頭', '江头', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["晚步隨江遠，來帆過眼頻。","試尋新住客，少見故鄉人。","回首憐歸翼，長吟任此身。","應同南浦雁，更見嶺頭春。"]', '["晚步隨江远，来帆過眼頻。","試尋新住客，少见故乡人。","回首怜归翼，长吟任此身。","應同南浦雁，更见嶺头春。"]', '诗', 'shi', '', NULL, '江頭 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('415041a9-5162-4470-b063-74957cf056cb', '寄孫沖主簿', '寄孫沖主簿', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["低折滄州簿，無書整兩春。","馬從同事借，妻怕罷官貧。","道僻收閑藥，詩高笑故人。","仍聞長吏奏，表乞鎖廳頻。"]', '["低折滄州簿，無书整兩春。","马從同事借，妻怕罷官貧。","道僻收闲藥，诗高笑故人。","仍闻长吏奏，表乞鎖廳頻。"]', '诗', 'shi', '', NULL, '寄孫沖主簿 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e47339f6-9095-40b8-9a43-bbeacbf3d24c', '贈任懶', '贈任懶', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["未肯求科第，深坊且隱居。","勝遊尋野客，高臥看兵書。","點藥醫閑馬，分泉灌遠蔬。","漢庭無得意，誰擬薦相如。"]', '["未肯求科第，深坊且隐居。","勝游尋野客，高臥看兵书。","点藥醫闲马，分泉灌远蔬。","漢庭無得意，誰擬薦相如。"]', '诗', 'shi', '', NULL, '贈任懶 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f73675fa-9c67-4e5c-b489-3005c1958483', '舊宮人', '旧宮人', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["謌舞梁州女，歸時白髮生。","全家沒蕃地，無處問鄉程。","宮錦不傳樣，御香空記名。","一身難自說，愁逐路人行。"]', '["謌舞梁州女，归时白髮生。","全家沒蕃地，無处问乡程。","宮錦不傳樣，御香空記名。","一身难自说，愁逐路人行。"]', '诗', 'shi', '', NULL, '舊宮人 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ca34906-4e7e-482e-9466-22d89a5f87ec', '春日留別', '春日留別', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["遊人欲別離，半醉對花枝。","看著春又晚，莫輕少年時。","臨行記分處，廻首是相思。","各向天涯去，重來未可期。"]', '["游人欲別離，半醉对花枝。","看著春又晚，莫轻少年时。","臨行記分处，廻首是相思。","各向天涯去，重来未可期。"]', '诗', 'shi', '', NULL, '春日留別 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ccd5188-0e5d-450e-8ec5-d6e661fac4f7', '沒蕃故人', '沒蕃故人', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["前年伐月支，城上沒全師。","蕃漢斷消息，死生長別離。","無人收廢帳，歸馬識殘旗。","欲祭疑君在，天涯哭此時。"]', '["前年伐月支，城上沒全師。","蕃漢斷消息，死生长別離。","無人收廢帳，归马識殘旗。","欲祭疑君在，天涯哭此时。"]', '诗', 'shi', '', NULL, '沒蕃故人 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d8625bb-d201-45d8-9e5a-56346d0cbea6', '贈箕山僧', '贈箕山僧', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["久住空林下，長齋耳目清。","蒲團借客坐，石磹甃人行。","似鶴難知性，因山強號名。","時聞衣袖裏，闇掐念珠聲。"]', '["久住空林下，长斋耳目清。","蒲團借客坐，石磹甃人行。","似鹤难知性，因山強號名。","时闻衣袖裏，闇掐念珠声。"]', '诗', 'shi', '', NULL, '贈箕山僧 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf5cb147-b653-4297-8569-0d487601292f', '冬夕', '冬夕', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["寒蛩獨罷織，湘雁猶能鳴。","月色當窗入，鄉心半夜生。","不成高枕夢，復作遶堦行。","迴首嗟淹泊，城頭北斗橫。"]', '["寒蛩独罷织，湘雁猶能鳴。","月色當窗入，乡心半夜生。","不成高枕梦，复作遶堦行。","迴首嗟淹泊，城头北斗橫。"]', '诗', 'shi', '', NULL, '冬夕 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('804932ef-6151-43b7-b6e6-3f961fbe840a', '奉和陝州十四翁中丞寄雷州二十二翁司戶之作', '奉和陝州十四翁中丞寄雷州二十二翁司戶之作', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["聯飛獨不前，迥落海南天。","賈傅竟行矣，邵公惟泫然。","瘴開山更遠，路極水無邊。","沈劣本多感，況聞原上篇。"]', '["聯飞独不前，迥落海南天。","賈傅竟行矣，邵公惟泫然。","瘴开山更远，路極水無邊。","沈劣本多感，況闻原上篇。"]', '诗', 'shi', '', NULL, '奉和陝州十四翁中丞寄雷州二十二翁司戶之作 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('790f454c-649e-4cb3-a7ff-e1bfde4373ba', '老將', '老將', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["鬢衰頭似雪，行步急如風。","不怕騎生馬，猶能挽硬弓。","兵書封錦字，手詔滿香筒。","今日身憔悴，猶誇定遠功。"]', '["鬢衰头似雪，行步急如风。","不怕騎生马，猶能挽硬弓。","兵书封錦字，手詔满香筒。","今日身憔悴，猶誇定远功。"]', '诗', 'shi', '', NULL, '老將 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c65c447-6c02-4b8a-918b-485a35466025', '送友生遊峽中', '送友生游峽中', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["風靜楊柳垂，看花又別離。","幾年同在此，今日各驅馳。","峽裏聞猿呌，山頭見月時。","殷勤一盃酒，珍重歲寒姿。"]', '["风静楊柳垂，看花又別離。","幾年同在此，今日各驱驰。","峽裏闻猿呌，山头见月时。","殷勤一盃酒，珍重歲寒姿。"]', '诗', 'shi', '', NULL, '送友生遊峽中 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('587eaf17-f792-45bd-a6b6-6d843d0da11e', '送安法師', '送安法師', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["出郭見落日，別君臨古津。","遠程無野寺，宿處問何人。","原色不分路，錫聲遙隔塵。","山陰到家節，猶及蕙蘭春。"]', '["出郭见落日，別君臨古津。","远程無野寺，宿处问何人。","原色不分路，錫声遙隔塵。","山陰到家節，猶及蕙蘭春。"]', '诗', 'shi', '', NULL, '送安法師 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b1b4f63-c207-4a11-b6f2-c677e0e4e0d5', '水', '水', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["蕩漾空沙際，虛明入遠天。","秋光照不極，鳥色去無邊。","勢引長雲闊，波輕片雪連。","汀洲杳難測，萬古覆蒼煙。"]', '["蕩漾空沙際，虛明入远天。","秋光照不極，鸟色去無邊。","勢引长云闊，波轻片雪連。","汀洲杳难測，万古覆蒼煙。"]', '诗', 'shi', '', NULL, '水 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e8b950d-862a-4c8d-9fe5-8327e4d31eb9', '岳州晚景', '岳州晚景', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["晚景寒鴉集，秋聲旅雁歸。","水光浮日去，霞彩暎江飛。","洲白蘆花吐，園紅柿葉稀。","長沙卑濕地，九月未成衣。"]', '["晚景寒鴉集，秋声旅雁归。","水光浮日去，霞彩暎江飞。","洲白蘆花吐，园紅柿葉稀。","长沙卑濕地，九月未成衣。"]', '诗', 'shi', '', NULL, '岳州晚景 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53f8a86c-d7b9-4272-b028-a5fc16ccee53', '寒食後', '寒食後', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["田舍清明日，家家出火遲。","白衫眠古巷，紅索搭高枝。","紗帶生難結，銅釵重易垂。","斬新衣著盡，還似去年時。"]', '["田舍清明日，家家出火遲。","白衫眠古巷，紅索搭高枝。","紗带生难結，銅釵重易垂。","斬新衣著尽，還似去年时。"]', '诗', 'shi', '', NULL, '寒食後 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f170945-6d17-44bc-b6c9-e8311dd8a963', '寒食書事二首 一', '寒食书事二首 一', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["今朝一百五，出戶雨初晴。","舞愛雙飛蝶，歌聞數里鶯。","江深青草岸，花滿白雲城。","爲政多孱懦，應無酷吏名。"]', '["今朝一百五，出戶雨初晴。","舞愛雙飞蝶，歌闻數里鶯。","江深青草岸，花满白云城。","爲政多孱懦，應無酷吏名。"]', '诗', 'shi', '', NULL, '寒食書事二首 一 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('186a3ef0-4ea6-4e6d-a87e-e60fd78cb793', '寒食書事二首 二', '寒食书事二首 二', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["出城煙火少，況復是今朝。","閑坐將誰語，臨觴只自謠。","堦前春蘚徧，衣上落花飄。","妓樂州人戲，使君心寂寥。"]', '["出城煙火少，況复是今朝。","闲坐將誰語，臨觴只自謠。","堦前春蘚徧，衣上落花飄。","妓乐州人戲，使君心寂寥。"]', '诗', 'shi', '', NULL, '寒食書事二首 二 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4679dd5e-f054-4ed3-8c25-70dc7e43f568', '和李僕射雨中寄盧嚴二給事', '和李僕射雨中寄盧嚴二給事', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["郊原飛雨至，城闕濕雲埋。","迸點時穿牖，浮漚欲上堦。","偏滋解籜竹，併灑落花槐。","晚潤生琴匣，新涼滿藥齋。","從容朝務退，放曠掖曹乖。","盡日無來客，閑吟感此懷。"]', '["郊原飞雨至，城闕濕云埋。","迸点时穿牖，浮漚欲上堦。","偏滋解籜竹，併灑落花槐。","晚潤生琴匣，新涼满藥斋。","從容朝務退，放曠掖曹乖。","尽日無来客，闲吟感此懷。"]', '诗', 'shi', '', NULL, '和李僕射雨中寄盧嚴二給事 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50815b10-6ce9-4de8-8d1d-12321b2ae2e4', '酬李僕射晚春見寄', '酬李僕射晚春见寄', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["戟戶洞初晨，鶯聲雨後頻。","虛庭清氣在，衆藥濕光新。","魚動芳池面，苔侵老竹身。","教鋪嘗酒處，自問探花人。","獨此長多病，幽居欲過春。","今朝聽高韻，忽覺離埃塵。"]', '["戟戶洞初晨，鶯声雨後頻。","虛庭清氣在，衆藥濕光新。","鱼动芳池面，苔侵老竹身。","教鋪嘗酒处，自问探花人。","独此长多病，幽居欲過春。","今朝听高韻，忽覺離埃塵。"]', '诗', 'shi', '', NULL, '酬李僕射晚春見寄 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0a4d401-6371-4fcc-ae25-6219c8be047f', '和盧常侍寄華山鄭隱者', '和盧常侍寄华山鄭隐者', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["獨住三峰下，年深學煉丹。","一間松葉屋，數片石花冠。","酒待山中飲，琴將洞口彈。","開門移遠竹，剪草出幽蘭。","荒壁通泉架，晴崖曬藥壇。","寄知騎省客，長向白雲閑。"]', '["独住三峰下，年深学煉丹。","一间松葉屋，數片石花冠。","酒待山中饮，琴將洞口彈。","开门移远竹，剪草出幽蘭。","荒壁通泉架，晴崖曬藥壇。","寄知騎省客，长向白云闲。"]', '诗', 'shi', '', NULL, '和盧常侍寄華山鄭隱者 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d9f705a-7212-4565-aaac-87ae359f6194', '和令狐尚書平泉東莊近居李僕射有寄十韻', '和令狐尚书平泉东莊近居李僕射有寄十韻', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["平地有清泉，伊南古寺邊。","漲池閑遶屋，出野徧澆田。","舊隱離多日，新鄰得幾年。","探幽皆一絕，選勝又雙全。","門靜山光別，園深竹影連。","斜分採藥徑，直過釣魚船。","雞犬還應識，雲霞頓覺鮮。","追思應不遠，賞愛諒難偏。","此處堪長往，遊人早共傳。","各當恩寄重，歸臥恐無緣。"]', '["平地有清泉，伊南古寺邊。","漲池闲遶屋，出野徧澆田。","旧隐離多日，新鄰得幾年。","探幽皆一絕，選勝又雙全。","门静山光別，园深竹影連。","斜分採藥徑，直過釣鱼船。","雞犬還應識，云霞頓覺鲜。","追思應不远，賞愛諒难偏。","此处堪长往，游人早共傳。","各當恩寄重，归臥恐無緣。"]', '诗', 'shi', '', NULL, '和令狐尚書平泉東莊近居李僕射有寄十韻 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84b870dc-c0f8-486a-b858-5e4ba8ea619f', '送鄭尚書出鎮南海', '送鄭尚书出鎮南海', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["遠鎮承新命，王程不假催。","班行爭路送，恩賜併時來。","牙斾從城展，兵符到府開。","蠻聲喧夜市，海色浸潮臺。","畫角天邊月，寒關嶺上梅。","共知公望重，多是隔年迴。"]', '["远鎮承新命，王程不假催。","班行爭路送，恩賜併时来。","牙斾從城展，兵符到府开。","蠻声喧夜市，海色浸潮台。","畫角天邊月，寒关嶺上梅。","共知公望重，多是隔年迴。"]', '诗', 'shi', '', NULL, '送鄭尚書出鎮南海 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35100df3-5470-494b-b237-f5a010690ede', '徐州試反舌無聲', '徐州試反舌無声', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["夏木多好鳥，偏知反舌名。","林幽仍共宿，時過即無聲。","竹外天空曉，谿頭雨自晴。","居人宜寂寞，深院益淒清。","入霧暗相失，當風閑易驚。","來年上林苑，知爾最先鳴。"]', '["夏木多好鸟，偏知反舌名。","林幽仍共宿，时過即無声。","竹外天空晓，谿头雨自晴。","居人宜寂寞，深院益淒清。","入霧暗相失，當风闲易驚。","来年上林苑，知爾最先鳴。"]', '诗', 'shi', '', NULL, '徐州試反舌無聲 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d82ae593-0d36-4453-a086-502a28c34d97', '省試行不由徑', '省試行不由徑', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["田裏有微徑，賢人不復行。","孰知求捷步，又恐異端成。","從易衆所欲，安邪患亦生。","誰能達天道，共此競前程。","子羽有遺跡，孔門傳舊聲。","今逢大君子，士節自光明。"]', '["田裏有微徑，賢人不复行。","孰知求捷步，又恐異端成。","從易衆所欲，安邪患亦生。","誰能達天道，共此競前程。","子羽有遺跡，孔门傳旧声。","今逢大君子，士節自光明。"]', '诗', 'shi', '', NULL, '省試行不由徑 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0be7423-c79f-4ed1-a93c-389dc46e7cef', '新城甲仗樓', '新城甲仗楼', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["謝氏起新樓，西臨城角頭。","圖功百尺麗，藏器五兵修。","結締榱甍固，虛明戶檻幽。","魚龍卷旗幟，霜雪積戈矛。","暑雨熇烝隔，涼風宴位留。","地高形出沒，山靜氣清優。","睥睨斜光徹，闌干宿靄浮。","芊芊秔稻色，脉脉苑谿流。","郡化黃丞相，詩成沈隱侯。","居茲良得景，殊勝峴山遊。"]', '["謝氏起新楼，西臨城角头。","圖功百尺丽，藏器五兵修。","結締榱甍固，虛明戶檻幽。","鱼龙卷旗幟，霜雪積戈矛。","暑雨熇烝隔，涼风宴位留。","地高形出沒，山静氣清優。","睥睨斜光徹，闌干宿靄浮。","芊芊秔稻色，脉脉苑谿流。","郡化黄丞相，诗成沈隐侯。","居茲良得景，殊勝峴山游。"]', '诗', 'shi', '', NULL, '新城甲仗樓 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4083322-3d89-4037-83b0-8e445f977b34', '贈殷山人', '贈殷山人', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["鬱鬱山中客，知名四十年。","恓惶身獨隱，寂寞性應便。","世業公侯籍，生涯黍稷田。","藤懸讀書帳，竹繫網魚船。","已種千頭橘，新開數脉泉。","閑遊攜酒遠，幽語向僧偏。","入洞題松過，看花選石眠。","避喧長汩沒，逢勝即留連。","自古多高跡，如君少比肩。","耕耘此辛苦，章句已流傳。","昔日交遊盛，當時省閣賢。","同袍還共弊，連轡每推先。","講序居重席，羣儒願執鞭。","滿堂虛左待，衆目望喬遷。","才異時難用，情高道自全。","畏人顏慘澹，疎物勢迍邅。","賢者聞知命，吾生復禮玄。","深藏報恩劒，久緝養生篇。","憔悴衆夫笑，經過郡守憐。","夕陽悲病鶴，霜氣動飢鸇。","處士誰能薦，窮途世所捐。","伯鸞甘寄食，元淑苦無錢。","策蹇秋塵裏，吟詩黃葉前。","故裘餘白領，廢瑟斷朱弦。","志氣終猶在，逍遙任自然。","家貧念婚嫁，身老戀雲煙。","放逸栖巖鹿，清虛飲露蟬。","鄭逃秦谷口，嚴愛越溪邊。","霄漢予猶阻，榮枯子不牽。","山城一相遇，感激意難宣。"]', '["鬱鬱山中客，知名四十年。","恓惶身独隐，寂寞性應便。","世業公侯籍，生涯黍稷田。","藤懸读书帳，竹繫網鱼船。","已種千头橘，新开數脉泉。","闲游携酒远，幽語向僧偏。","入洞題松過，看花選石眠。","避喧长汩沒，逢勝即留連。","自古多高跡，如君少比肩。","耕耘此辛苦，章句已流傳。","昔日交游盛，當时省閣賢。","同袍還共弊，連轡每推先。","講序居重席，羣儒願執鞭。","满堂虛左待，衆目望喬遷。","才異时难用，情高道自全。","畏人顏慘澹，疎物勢迍邅。","賢者闻知命，吾生复禮玄。","深藏報恩劒，久緝養生篇。","憔悴衆夫笑，經過郡守怜。","夕陽悲病鹤，霜氣动飢鸇。","处士誰能薦，窮途世所捐。","伯鸾甘寄食，元淑苦無錢。","策蹇秋塵裏，吟诗黄葉前。","故裘餘白領，廢瑟斷朱弦。","志氣終猶在，逍遙任自然。","家貧念婚嫁，身老戀云煙。","放逸栖巖鹿，清虛饮露蟬。","鄭逃秦谷口，嚴愛越溪邊。","霄漢予猶阻，榮枯子不牽。","山城一相遇，感激意难宣。"]', '诗', 'shi', '', NULL, '贈殷山人 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8648474-aede-477f-bbd8-9793db49a9e7', '夏日可畏', '夏日可畏', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["赫赫溫風扇，炎炎夏日徂。","火威馳逈野，畏景鑠遙途。","勢矯翔陽翰，功分造化罏。","禁城千品燭，黃道一輪孤。","落照頻空簟，餘暉卷夕梧。","如何倦遊子，中路獨踟躕。"]', '["赫赫溫风扇，炎炎夏日徂。","火威驰逈野，畏景鑠遙途。","勢矯翔陽翰，功分造化罏。","禁城千品燭，黄道一輪孤。","落照頻空簟，餘暉卷夕梧。","如何倦游子，中路独踟躕。"]', '诗', 'shi', '', NULL, '夏日可畏 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79f27efe-fb2a-4e22-b7ec-a30d9a0cfd1b', '罔象得玄珠', '罔象得玄珠', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["赤水今何處，遺珠已渺然。","離婁徒肆目，罔象乃通玄。","皎潔因成性，圓明不在泉。","暗中看夜色，塵外照晴田。","無脛真難掬，懷疑實易遷。","今朝搜擇得，應免媚晴川。"]', '["赤水今何处，遺珠已渺然。","離婁徒肆目，罔象乃通玄。","皎潔因成性，圓明不在泉。","暗中看夜色，塵外照晴田。","無脛真难掬，懷疑實易遷。","今朝搜擇得，應免媚晴川。"]', '诗', 'shi', '', NULL, '罔象得玄珠 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('247aeaa0-d69a-4c18-a69f-fc6cf9280161', '和李僕射西園', '和李僕射西园', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["遇午歸閑處，西庭敞四簷。","高眠著琴枕，散帖檢書簽。","印在休通客，山晴好捲簾。","竹涼蠅少到，藤暗蝶爭潛。","曉鵲頻驚喜，疎蟬不許拈。","石苔生紫點，欄藥吐紅尖。","虛坐詩情遠，幽探道侶兼。","所營尚勝地，雖儉復誰嫌。"]', '["遇午归闲处，西庭敞四簷。","高眠著琴枕，散帖檢书簽。","印在休通客，山晴好捲簾。","竹涼蠅少到，藤暗蝶爭潛。","晓鵲頻驚喜，疎蟬不許拈。","石苔生紫点，欄藥吐紅尖。","虛坐诗情远，幽探道侶兼。","所營尚勝地，雖儉复誰嫌。"]', '诗', 'shi', '', NULL, '和李僕射西園 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('781555b7-0c60-4783-9639-1609adb59969', '送裴相公赴鎮太原', '送裴相公赴鎮太原', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["盛德雄名遠近知，功高先乞守藩維。","銜恩暫遣分龍節，署勅還同在鳳池。","天子親臨樓上送，朝官齊出道傍辭。","明年塞北清蕃落，應建生祠請立碑。"]', '["盛德雄名远近知，功高先乞守藩維。","銜恩暫遣分龙節，署勅還同在鳳池。","天子親臨楼上送，朝官齊出道傍辞。","明年塞北清蕃落，應建生祠請立碑。"]', '诗', 'shi', '', NULL, '送裴相公赴鎮太原 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47a432f9-a8f7-48bd-903d-1fdb90cf3ea1', '寄元員外', '寄元員外', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["外郎直罷無餘事，埽灑書堂試藥爐。","門巷不教當要鬧，詩篇轉覺足工夫。","月明臺上唯僧到，夜靜坊中有酒沽。","朝省入頻閑日少，可能同作舊遊無。"]', '["外郎直罷無餘事，埽灑书堂試藥爐。","门巷不教當要鬧，诗篇轉覺足工夫。","月明台上唯僧到，夜静坊中有酒沽。","朝省入頻闲日少，可能同作旧游無。"]', '诗', 'shi', '', NULL, '寄元員外 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c637d249-8158-48b9-98ee-a2300c0acbde', '贈梅處士', '贈梅处士', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["早聞聲價滿京城，頭白江湖放曠情。","講易自傳新註義，題詩不著舊官名。","近移馬跡山前住，多向牛頭寺裏行。","天子如今議封禪，應將束帛請先生。"]', '["早闻声價满京城，头白江湖放曠情。","講易自傳新註義，題诗不著旧官名。","近移马跡山前住，多向牛头寺裏行。","天子如今議封禪，應將束帛請先生。"]', '诗', 'shi', '', NULL, '贈梅處士 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05bf7ea8-b98c-4a8c-b488-557dc2ae0db6', '贈王秘書', '贈王秘书', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["不曾浪出謁公侯，唯向花間水畔遊。","每著新衣看藥竈，多收古器在書樓。","有官祗作山人老，平地能開洞穴幽。","自領閑司了無事，得來君處喜相留。"]', '["不曾浪出謁公侯，唯向花间水畔游。","每著新衣看藥竈，多收古器在书楼。","有官祗作山人老，平地能开洞穴幽。","自領闲司了無事，得来君处喜相留。"]', '诗', 'shi', '', NULL, '贈王秘書 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('611a7cbf-4679-427d-bf88-784eb53bcdd2', '謝裴司空寄馬', '謝裴司空寄马', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["騄耳新駒駿得名，司空遠自寄書生。","乍離華廐移蹄澀，初到貧家舉眼驚。","每被閑人來借問，多尋古寺獨騎行。","長思歲旦沙堤上，得從鳴珂傍火城。"]', '["騄耳新駒駿得名，司空远自寄书生。","乍離华廐移蹄澀，初到貧家舉眼驚。","每被闲人来借问，多尋古寺独騎行。","长思歲旦沙堤上，得從鳴珂傍火城。"]', '诗', 'shi', '', NULL, '謝裴司空寄馬 張籍 shi');
